Ceviri.ekle("id","olay",{
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan memperoleh pengaruh sebagai valide sultan", "000bec21"], "d": ["Safiye Sultan, istri Murad III dan ibu Mehmed III, dengan naik takhtanya putranya naik ke kedudukan menentukan dalam politik istana sebagai valide sultan. Menurut TDV İslâm Ansiklopedisi, pada masa ini pengaruh yang berasal dari harem mencapai tingkat campur tangan langsung dalam urusan negara.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III berangkat ke ekspedisi sendiri atas tekanan janisari", "d3c50656"], "d": ["Meski ditentang Sadrazam Damad İbrahim Paşa, atas tekanan janisari Mehmed III berangkat dari Istanbul pada 20 Juni 1596 untuk berekspedisi sebagai sultan pertama yang memimpin pasukan sendiri setelah Sultan Süleyman Kanuni. Menurut TDV İslâm Ansiklopedisi, hal ini berarti dihidupkannya tradisi gaza lama.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Wabah tâun yang dimulai pada 1570-an terus memengaruhi Istanbul", "eb4ca37a"], "d": ["Menurut entri tâun di TDV İslâm Ansiklopedisi, epidemi yang dimulai pada 1570-an melanjutkan pengaruhnya hingga awal abad ke-17 dan menyerang terutama Istanbul, Anatolia, Balkan, Mesir, dan Afrika Utara. Masa-masa epidemi merupakan ancaman kronis yang sering memutus kehidupan istana dan kota.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Karayazıcı Abdülhalim wafat, gerakan pemberontakan melemah", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, yang mundur dalam keadaan terluka setelah kekalahan berat di Sepetli dekat Elbistan pada 12 Agustus 1601, wafat pada tahun 1010 (1602). Menurut TDV İslâm Ansiklopedisi, kabar wafatnya sampai ke Istanbul pada Ramadan 1010 (Februari-Maret 1602); sumber-sumber mencatat bahwa diperdebatkan apakah kematiannya akibat luka atau oleh anak buahnya sendiri.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Berakhirnya tradisi pembunuhan saudara secara faktual", "9046c607"], "d": ["Ahmed I, ketika naik takhta, tidak membunuh saudaranya Şehzade Mustafa dan mengampuni nyawanya, berbeda dengan para sultan sebelumnya; keputusan ini dianggap awal diterimanya asas ekber-erşed secara faktual dalam sistem suksesi Utsmaniyah. Entri \"Mustafa I\" di TDV İslâm Ansiklopedisi mencatat bahwa Mustafa sejak tanggal ini menjalani kehidupan mahfil di istana. Penerapan itu secara faktual mengakhiri pembunuhan naik takhta yang berlangsung selama berabad-abad.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Diletakkannya batu pertama Masjid Sultan Ahmed", "1683262f"], "d": ["Atas perintah Ahmed I, batu pertama masjid yang akan dibangun arsitek Sedefkâr Mehmed Ağa diletakkan dengan upacara di Atmeydanı. Menurut entri \"Masjid dan Kompleks Sultan Ahmed\" di TDV İslâm Ansiklopedisi, bangunan itu juga menjadi sasaran kritik zamannya karena merupakan masjid sultan besar pertama yang dibangun langsung dari perbendaharaan tanpa kemenangan penaklukan. Kompleks dirancang mencakup, bersama masjid, madrasah, imaret, dan makam.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Terbunuhnya Genç Osman oleh janisari (Hâile-i Osmâniye)", "324f6582"], "d": ["Atas rumor bahwa ia berencana keluar dari Istanbul dengan dalih haji untuk membubarkan korps janisari, para janisari dan sipahi memberontak, menurunkan Osman II dari takhta, dan mencekiknya di penjara Yedikule. Menurut entri \"Osman II\" di TDV İslâm Ansiklopedisi, peristiwa ini adalah kasus pertama dalam sejarah Utsmaniyah ketika seorang sultan dibunuh secara terbuka oleh pemberontakan militer dan menimbulkan patahan mendalam dalam hubungan dinasti-tentara. Jam-jam terakhirnya berlalu demikian: ketika upayanya berlindung di kediaman agha janisari Ali Ağa tidak membuahkan hasil, sultan, dalam ungkapan TDV 'dengan cara mengenaskan, dengan kepala terbuka, dalam keadaan berantakan', dinaikkan ke seekor kuda dan di bawah hinaan berat dibawa pertama ke Orta Cami tempat Mustafa I berada, dan pada sore hari yang sama ke Yedikule; menurut sebagian sejarawan, untuk membuktikan wafatnya, telinga dan hidungnya dipotong dan diperlihatkan kepada ibu Mustafa I. Setelah peristiwa itu Mustafa I dinaikkan ke takhta untuk kedua kalinya. Peristiwa yang disebut 'Hâile-i Osmâniye' (bencana Osman) itu merusak keseimbangan istana-ocak secara permanen dan memulai perdebatan legitimasi yang akan berlangsung sepanjang abad.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Dinaikkannya Mustafa I ke takhta untuk kedua kali", "34a0b29a"], "d": ["Setelah terbunuhnya Genç Osman oleh janisari, Mustafa I dinaikkan ke takhta untuk kedua kalinya karena tidak ada anggota laki-laki dewasa lain dalam dinasti. Menurut entri \"Mustafa I\" di TDV İslâm Ansiklopedisi, kesultanan kedua ini juga berlalu, tidak berbeda dari yang pertama, tanpa dapat menjalankan urusan negara secara faktual dan pemerintahan negara dibiarkan di tangan para wazir dan valide sultan. Masa empat belas bulan ini berakhir pada 1623 dengan naik takhtanya Murad IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Kebakaran Cibali", "3e42fb08"], "d": ["Kebakaran yang pecah di Cibali dan menyebar cepat karena angin membakar sebagian besar Istanbul; menurut entri \"İstanbul\" di TDV İslâm Ansiklopedisi, sumber-sumber zaman itu mencatat ribuan rumah terbakar. Dikaitkannya kebakaran dengan susunan rumah kayu dan kebiasaan merokok tembakau menjadi alasan langsung larangan keras tembakau dan kedai kopi yang tak lama kemudian diumumkan Murad IV. Bencana itu hanya salah satu dari kebakaran besar yang berulang di Istanbul masa itu.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Larangan tembakau dan kedai kopi oleh Murad IV", "5dd71297"], "d": ["Setelah Kebakaran Cibali, dengan kekhawatiran akan kebakaran dan ketertiban, Murad IV melarang merokok tembakau dan kedai kopi; hukuman berat, termasuk hukuman mati, diterapkan kepada pelanggar. Menurut entri \"Murad IV\" di TDV İslâm Ansiklopedisi, sultan menjalankan kebijakan disiplin dalam negeri yang begitu ketat sehingga ia berkeliling jalan-jalan kota sendiri dengan menyamar untuk mengawasi larangan. Tindakan keras ini dinilai bagian dari upaya Murad IV membangun kembali otoritas sentral.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Wabah di Istanbul", "f33f58c5"], "d": ["Pada masa Murad IV, Istanbul diguncang wabah berat yang memengaruhi sebagian besar penduduk; perdagangan dalam kota dan kehidupan sehari-hari terganggu berbulan-bulan. Entri \"İstanbul\" di TDV İslâm Ansiklopedisi mencatat bahwa wabah yang berulang pada abad ke-17 memengaruhi keseimbangan penduduk kota secara serius. Pada masa wabah, istana dan kalangan elite untuk sementara pindah ke taman dan paviliun di luar kota.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Penerbangan bersayap Hezarfen Ahmed Çelebi (riwayat)", "df474c04"], "d": ["Menurut riwayat yang disampaikan Evliya Çelebi, Hezarfen Ahmed Çelebi melompat dari Menara Galata dengan sayap buatannya sendiri dan berhasil meluncur hingga Üsküdar; meski kepastian sejarahnya diperdebatkan, ia menjadi simbol imajinasi teknis. Sultan, yang pada mulanya memberi hadiah kepada Hezarfen, kemudian mengasingkannya ke Aljir karena gaung yang ditimbulkan peristiwa itu.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Cinci Hoca Hüseyin Efendi memperoleh pengaruh di istana", "41d21572"], "d": ["Hüseyin Efendi, tukang tiup (üfürükçü) yang dipanggil ke istana untuk mengobati kesulitan jiwa Sultan İbrahim, dalam waktu singkat memperoleh kepercayaan sultan dan naik hingga jabatan kazasker Anatolia. Menurut entri \"Hüseyin Efendi, Cinci Hoca\" di TDV İslâm Ansiklopedisi, ia menggunakan pengaruh ini untuk menimbun kekayaan dan campur tangan dalam peristiwa politik zamannya. Setelah wafatnya İbrahim ia dicopot dari semua jabatannya dan dieksekusi pada 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Eksekusi Kemankeş Mustafa Paşa", "0ecc8030"], "d": ["Kemankeş Mustafa Paşa, yang menjabat sadrazam sejak masa Murad IV dan membawa kelebihan penting ke kas dengan reformasi keuangannya, dicekik dan dieksekusi karena para saingan di istana memengaruhi İbrahim dan ia dituduh membuat pemberontakan janisari. Menurut entri \"Kemankeş Mustafa Paşa\" di TDV İslâm Ansiklopedisi, eksekusinya terjadi pada 21 Zulkaidah 1053 / 31 Januari 1644: Kemankeş Kara Mustafa Paşa dicekik oleh algojo Kara Ali di Pasar Hocapaşa dan dimakamkan di makamnya sendiri di Çarşıkapı. Wafatnya dikenang sebagai contoh mencolok ketidakstabilan jabatan sadrazam masa itu dan mengakhiri periode reformasi ketat yang singkat.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Diputuskannya Ekspedisi Kreta di divan dan keberangkatan armada", "9076827e"], "d": ["Pembukaan ekspedisi besar terhadap Pulau Kreta milik Venesia diputuskan di Divan-ı Hümayun dan armada Utsmaniyah di bawah komando kaptan-ı derya berangkat dari Istanbul menuju Kreta. Menurut entri \"Girit\" di TDV İslâm Ansiklopedisi, keputusan ini membentuk awal politik periode pengepungan dan perang panjang yang akan berlangsung sekitar dua puluh lima tahun. Pembukaan ekspedisi menimbulkan perdebatan luas di kalangan pembesar negara sebagai upaya kebijakan luar negeri terbesar masa İbrahim.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Naik takhtanya Mehmed IV pada usia tujuh tahun", "a197a3bc"], "d": ["Segera setelah pemakzulan İbrahim, putranya Mehmed, yang baru berusia tujuh tahun, dinaikkan ke takhta dan menjadi sultan dengan gelar Mehmed IV. Menurut entri \"Mehmed IV\" di TDV İslâm Ansiklopedisi, naik takhta pada usia semuda ini memanaskan perebutan pengaruh dalam istana antara neneknya Kösem Sultan dan ibunya Turhan Sultan. Perebutan kekuasaan ini akan berujung pada dibunuhnya Kösem Sultan pada 1651.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Reformasi anggaran berimbang Tarhuncu Ahmed Paşa", "376fc7f2"], "d": ["Sadrazam Tarhuncu Ahmed Paşa, untuk mengatasi krisis keuangan yang ditimbulkan tahun-tahun perang panjang, menerapkan program penghematan keras yang mencakup pengeluaran istana dan menyiapkan anggaran berimbang pertama yang diketahui dalam sejarah Utsmaniyah (layihat Tarhuncu). Menurut entri \"Tarhuncu Ahmed Paşa\" di TDV İslâm Ansiklopedisi, reformasi ini memberi kas kelebihan penting, tetapi menimbulkan ketidakpuasan luas di kalangan istana dan birokrasi tinggi. Ketidakpuasan ini akan berujung pada eksekusinya setahun kemudian.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Peristiwa Çınar (Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Menurut entri Peristiwa Çınar di TDV İslâm Ansiklopedisi, para janisari dan sipahi yang kembali dari ekspedisi Kreta tanpa dibayar memberontak di Istanbul dan menuntut eksekusi negarawan yang mereka tuduh korupsi. Usul penyitaan dan pengasingan dari Sadrazam Zurnazen Mustafa Paşa tidak diterima; pertama tiga pejabat, kemudian hampir tiga puluh negarawan dieksekusi dan jenazah mereka digantung di pohon-pohon ara di Lapangan Sultanahmet. Karena itu peristiwa itu dikenal dengan nama Peristiwa Çınar.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Pengangkatan Köprülü Mehmed Paşa sebagai sadrazam dengan penerimaan bersyarat", "3a6b7f8f"], "d": ["Menurut entri Köprülü Mehmed Paşa di TDV İslâm Ansiklopedisi, Köprülü Mehmed Paşa, yang hampir berusia delapan puluh tahun, baru menerima stempel setelah membuat Valide Turhan Sultan dan Mehmed IV menerima syarat-syarat berat yang diajukannya — tidak dicampurinya pengangkatannya dan tidak dipercayainya apa yang dikatakan terhadapnya. Ia mulai bertugas pada 26 Zulkaidah 1066 menggantikan Boynueğri Mehmed Paşa dan segera berupaya menegakkan kembali disiplin negara dengan keras.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Penumpasan gerakan Kadizadeli oleh Köprülü Mehmed Paşa", "5ec3ce84"], "d": ["Menurut entri Kadızâdeliler di TDV İslâm Ansiklopedisi, segera setelah mulai bertugas Köprülü Mehmed Paşa menangani konflik keagamaan antara lingkungan Kadızâde Mehmed Efendi dan penganut tarekat. Setelah berkonsultasi dengan ulama, meski firman eksekusi dikeluarkan untuk para pemimpin gerakan Üstüvânî Mehmed Efendi, Türk Ahmed, dan Divâne Mustafa, hukuman ini diubah menjadi pengasingan dan ketiganya dikirim ke Siprus; dengan demikian fase kedua gerakan berakhir.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Kebakaran besar di Istanbul: terbakarnya Ağakapısı", "b9253b66"], "d": ["Menurut entri Ağakapısı di TDV İslâm Ansiklopedisi, dalam kebakaran besar yang pecah pada Juli 1660 masa Mehmed IV, Ağakapısı, markas resmi agha janisari, terbakar seluruhnya dan kemudian dibangun kembali. Kebakaran ini adalah salah satu kebakaran kota besar yang berulang kali melanda Istanbul masa itu.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Pengangkatan Köprülüzâde Fâzıl Ahmed Paşa sebagai sadrazam", "c1999b5c"], "d": ["Menurut entri Köprülüzâde Fâzıl Ahmed Paşa di TDV İslâm Ansiklopedisi, setelah wafatnya ayahnya Köprülü Mehmed Paşa, ia diangkat sebagai sadrazam pada 8 Rebîülevvel 1072 (1 November 1661). Berbeda dengan ayahnya, Fâzıl Ahmed Paşa, yang dikenal berwatak lembut, saleh, dan pelindung ulama-seniman, selama jabatan sadrazamnya yang melebihi lima belas tahun mendirikan perpustakaan dan lembaga amal di Istanbul dan wilayah yang ditaklukkan.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Pengangkatan Vânî Mehmed Efendi sebagai pendakwah Yeni Cami dan guru sultan", "7ea6aaae"], "d": ["Menurut entri Mehmed Efendi, Vânî di TDV İslâm Ansiklopedisi, Vânî Mehmed Efendi, yang dipanggil ke Istanbul dengan menjadi sadrazamnya Köprülüzâde Fâzıl Ahmed Paşa dan diperkenalkan kepada Mehmed IV, dalam waktu singkat memperoleh perhatian dekat sultan. Pada 1665 ia diangkat sebagai pendakwah Yeni Cami dan guru sultan dan menjadi salah satu ulama paling berpengaruh di istana.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Pengangkatan Merzifonlu Kara Mustafa Paşa sebagai sadrazam", "3d1e836c"], "d": ["Menurut entri Merzifonlu Kara Mustafa Paşa di TDV İslâm Ansiklopedisi, setelah wafatnya Fâzıl Ahmed Paşa ia diangkat sebagai sadrazam pada 28 Şaban 1087 (5 November 1676). Merzifonlu, yang sebagai menantu dan didikan keluarga Köprülü memiliki pengalaman panjang dalam pemerintahan negara, menjadi salah satu sadrazam paling kuat dan berpengaruh masa Mehmed IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Wafatnya Vânî Mehmed Efendi dalam pengasingan", "cda714aa"], "d": ["Menurut entri Mehmed Efendi, Vânî di TDV İslâm Ansiklopedisi, Vânî Mehmed Efendi, yang dianggap salah satu nama utama yang membuat sultan menerima ekspedisi Wina, setelah ekspedisi berakhir dengan kekalahan dijatuhkan dari kedudukan karena tekanan opini publik dan diasingkan ke kota kecil Kestel di Bursa. Ia wafat di sana pada 14 Zulkaidah 1096 (12 Oktober 1685) dan dimakamkan di pintu masuk masjid yang ia bangun sendiri.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Pengangkatan Köprülüzâde Fâzıl Mustafa Paşa sebagai sadrazam dan reformasi keuangannya", "b048570e"], "d": ["Menurut entri Köprülüzâde Fâzıl Mustafa Paşa di TDV İslâm Ansiklopedisi, Fâzıl Mustafa Paşa, yang diangkat sebagai sadrazam pada 11 Muharram 1101 (25 Oktober 1689), menata ulang tata cara pemungutan jizyah menurut asas syariat, memerangi inflasi mangır, dan memperkuat kas dengan mengalihkan sumber daya dari lembaga-lembaga istana. Ia juga memperkuat pemerintahan provinsi dengan pejabat tepercaya dan mendirikan dewan-dewan lokal serupa divan pusat.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Berlakunya sistem mâlikâne", "316b8426"], "d": ["Menurut entri Mâlikâne di TDV İslâm Ansiklopedisi, pada seperempat terakhir abad ke-17, meningkatnya biaya perang dan menyusutnya pendapatan akibat kehilangan wilayah menjerumuskan kas ke dalam krisis keuangan berat. Dalam sistem mâlikâne yang berlaku pada tahun 1106 (1695), para mültezim diberi hak pajak tetap seumur hidup sehingga insentif melindungi produksi menggantikan pemerasan jangka pendek.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Naik takhtanya Mustafa II", "b53656c7"], "d": ["Menurut entri Mustafa II di TDV İslâm Ansiklopedisi, Mustafa II, yang naik takhta pada usia tiga puluh satu tahun, menyatakan kesultanannya tanpa menunggu persetujuan sadrazam dan şeyhülislâm; upacara pengenaan pedang dilakukan beberapa hari kemudian di Eski Cami. Sultan, yang naik takhta pada masa ketika perang multi-front berlanjut setelah kekalahan Wina, menjadi sultan Utsmaniyah terakhir yang berekspedisi sendiri.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Pengangkatan Feyzullah Efendi sebagai şeyhülislâm untuk kedua kali", "1cf14cff"], "d": ["Menurut entri Feyzullah Efendi, Seyyid di TDV İslâm Ansiklopedisi, setelah naik takhtanya Mustafa II, ia diangkat sebagai şeyhülislâm untuk kedua kalinya pada 11 Şewal 1106 (25 Mei 1695). Pengaruhnya atas sultan semakin meningkat selama masa jabatan lebih dari delapan tahun ini.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Feyzullah Efendi menempatkan putra-putranya di jabatan tinggi dan menumpuknya reaksi", "a6398280"], "d": ["Menurut entri Feyzullah Efendi, Seyyid di TDV İslâm Ansiklopedisi, şeyhülislâm memperoleh dari Mustafa II firman yang belum pernah terlihat bahwa putranya Fethullah Efendi akan menjadi şeyhülislâm setelahnya dan menempatkan kerabatnya pada usia muda di jabatan tinggi. Praktik-praktik ini menimbulkan ketidakpuasan luas di antara kelas ilmiye, tentara, dan rakyat Istanbul; bergabung dengan rumor bahwa ibu kota akan dipindahkan ke Edirne, ia menyiapkan landasan Peristiwa Edirne 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Dimulainya Peristiwa Edirne", "5a106458"], "d": ["Menurut entri \"Edirne Vak'ası\" di TDV, gerakan yang dimulai dengan pemberontakan prajurit yang tidak menerima ulûfe mereka dalam waktu singkat berubah menjadi pemberontakan luas yang diikuti janisari, murid madrasah, pedagang, dan rakyat. Sasaran sebenarnya pemberontakan adalah Şeyhülislâm Feyzullah Efendi, yang dituduh campur tangan berlebihan dalam urusan negara. Kerumunan sekitar 60.000 orang berbaris dari Istanbul ke Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Kesadrazaman Nevşehirli Damad İbrahim Paşa", "8d627a6f"], "d": ["Menurut entri \"Damad İbrâhim Paşa, Nevşehirli\" di TDV, ia diangkat ke jabatan sadrazam pada 8 Cemâziyelâhir 1130 (9 Mei 1718) selama perundingan damai dengan Austria berlanjut, dan segera setelah diangkat ia berpaling ke perundingan yang akan mengakhiri perang; dua bulan kemudian Perjanjian Passarowitz ditandatangani (21 Juli 1718). Dengan ungkapan TDV 'ia ingin menangani urusan sosial dan keuangan, dan merindukan masa damai yang akan membuat orang melupakan perang-perang yang bertahun-tahun berakhir dengan kekalahan'. Ia melakukan reformasi di keuangan, menurunkan gaji prajurit, dan membentuk kelebihan penting di kas negara. Kesadrazamannya yang akan berlangsung dua belas tahun membentuk kerangka politik masa yang menyandang namanya (Era Tulip).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Pendirian Ocak Tulumbacı", "f58b0d97"], "d": ["Menurut entri \"Tulumbacı\" di TDV, atas keberhasilan Gerçek Dâvud, yang kembali dari ekspedisi Mora 1715, dengan pompa air (tulumba) dalam kebakaran Istanbul, Sadrazam Nevşehirli Damad İbrahim Paşa menugaskannya mendirikan ocak pemadam kebakaran resmi. Ocak yang didirikan di Barak Acemi Oğlanları dengan enam perwira dan lima puluh prajurit itu mencapai 150 pada 1724 dan 461 pada 1755. Dâvud tetap di kepala ocak hingga wafatnya pada 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["Penerimaan Mehmed Efendi oleh Louis XV", "0ff5b174"], "d": ["Menurut entri \"Yirmisekiz Çelebi Mehmed Efendi\" di TDV, utusan diterima secara resmi oleh Raja Prancis Louis XV di Istana Tuileries dan menyampaikan hadiah dan surat Ahmed III. Selama kunjungannya ia mengunjungi istana Versailles, Trianon, dan Marly, rumah sakit, observatorium, dan bengkel; ia mencatat apa yang dilihatnya dengan gambar.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["Kembalinya Mehmed Efendi ke Istanbul", "a09a8bba"], "d": ["Menurut entri \"Yirmisekiz Çelebi Mehmed Efendi\" di TDV, pengamatan utusan yang kembali dari kedutaan setahun di Paris memengaruhi selera arsitektur Era Tulip. Kerja sama putranya kemudian dengan İbrahim Müteferrika menyiapkan landasan pendirian percetakan Turki pertama, warisan paling abadi kedutaan itu.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Pembangunan Paviliun Sâdâbâd", "aec9c65e"], "d": ["Menurut entri \"Sâdâbâd\" di TDV, di tepi Sungai Kağıthane dibangun kompleks hiburan dan rekreasi luas yang terdiri dari paviliun, kanal, air mancur, dan pondok yang terilhami arsitektur istana Prancis. Sâdâbâd, yang menjadi tempat hiburan paling digemari masa itu, diabadikan dalam puisi penyair Nedîm. Kompleks itu sebagian besar dihancurkan selama Pemberontakan Patrona Halil 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Pasukan Rusia merebut Derbent: ekspedisi Kaspia Petrus I", "c2b269f9"], "d": ["Ketika Negara Safawi terseret ke kekacauan dalam negeri oleh invasi Afghan, Tsar Rusia Petrus I berangkat ke ekspedisi dengan tujuan merebut wilayah Iran di pesisir Kaspia; kota pesisir Derbent menyerah kepada pasukan Rusia tanpa perlawanan berarti. Menurut entri Derbent di TDV İslâm Ansiklopedisi, pendudukan ini adalah awal kekuasaan Rusia sementara yang akan berlangsung tiga belas tahun; Negara Utsmaniyah juga memanfaatkan kekacauan yang sama dan berpaling ke bagian barat Kaukasus. Pasukan telah mendarat dari Astrakhan melalui laut di Teluk Agrakhan dan dari sana berbaris di sepanjang pesisir melalui Tarku di darat; shamkhal Tarku menjamu Petrus dan menjadi bawahan Rusia.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Dihapusnya shamkhalate Tarku: pemerintahan Rusia langsung", "b0f029c6"], "d": ["Shamkhal Tarku Adil-Girey, yang menjamu Petrus pada 1722 dan menjadi bawahan Rusia, memberontak pada 1725; Yeropkin menghancurkan Tarku pada musim gugur 1725, shamkhal ditangkap dan diasingkan pada pertengahan Mei 1726 dan shamkhalate dihapus. Tarku dan sekitarnya tetap di bawah pemerintahan Rusia langsung hingga Perjanjian Ganja 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Izin mendirikan percetakan untuk İbrahim Müteferrika", "0659dd0a"], "d": ["Menurut entri \"İbrâhim Müteferrika\" di TDV, dengan firman Ahmed III dan fatwa Şeyhülislâm Yenişehirli Abdullah Efendi, pendirian percetakan Turki pertama diizinkan. Percetakan mulai beroperasi di kawasan Yavuzselim di Istanbul. Müteferrika mencetak tujuh belas karya dalam dua puluh tiga jilid hingga wafatnya pada 1747.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Selesainya buku cetak pertama Kamus Vankulu", "684700e8"], "d": ["Menurut entri \"İbrâhim Müteferrika\" di TDV, karya pertama percetakan, terjemahan Turki Sıhâhu'l-Cevherî (Kamus Vankulu), selesai pada awal 1729. Ini adalah buku pertama yang dicetak dengan huruf Arab di wilayah Utsmaniyah dan dianggap awal sejarah percetakan Turki.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Eksekusi Nevşehirli Damad İbrahim Paşa", "50c64341"], "d": ["Menurut entri \"Damad İbrâhim Paşa, Nevşehirli\" di TDV, jenazah sadrazam yang dibunuh di istana selama Pemberontakan Patrona Halil diseret di jalan-jalan Istanbul dan ditinggalkan dekat Air Mancur Ahmed III di Lapangan Sultanahmet. Kesadrazamannya selama dua belas tahun dan Era Tulip dengan demikian berakhir secara berdarah.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Mundurnya Ahmed III dari takhta, naik takhtanya Mahmud I", "a43f5d40"], "d": ["Menurut entri \"Mahmud I\" di TDV, di hadapan tekanan para pemberontak, Ahmed III mundur dari takhta setelah memperoleh jaminan untuk dirinya dan anak-anaknya dan menaikkan keponakannya Şehzade Mahmud sendiri ke takhta. Mahmud I, yang duduk di takhta dengan nasihat pamannya \"ambil urusan negara ke tanganmu sendiri, jangan percaya siapa pun\", segera berupaya mematahkan pengaruh kelompok pemberontak yang menaikkannya ke takhta.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Reformasi ocak artileri oleh Humbaracı Ahmed Paşa", "ea3a7c64"], "d": ["Menurut entri \"Humbaracı\" di TDV, perwira keturunan Prancis Ahmed Paşa, yang masuk Islam, pada masa Sadrazam Hekimoğlu Ali Paşa berupaya mereformasi organisasi humbaracı berulûfe ala Eropa. Ia membentuk struktur baru 601 orang yang terikat langsung kepada sadrazam, terdiri dari 300 bergaji dan 301 bertimar. Dengan teknologi zamannya ia membuat 100 meriam mortir dan 50.000 peluru.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Pendirian Hendesehâne (contoh pertama sekolah teknik)", "a77ed1f3"], "d": ["Menurut entri \"Mahmud I\" di TDV, Humbaracı Ahmed Paşa mendirikan Hendesehâne, yang juga disebut Humbarahâne, di Üsküdar dan memberi pendidikan militer berbasis matematika dan geometri kepada murid yang dipilih dari antara pelayan istana dan bostancı. Lembaga ini dianggap contoh pertama sekolah-sekolah teknik yang akan berkembang kemudian.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Perjanjian Ganja: Derbent dan Baku dikembalikan ke Iran", "ff19d531"], "d": ["Rusia, yang mencari aliansi dengan Iran menghadapi ancaman Utsmaniyah, dengan Perjanjian Ganja mengembalikan kota-kota pesisir Kaspia yang dikuasainya selama tiga belas tahun kepada Iran di bawah komando Nadir Khan (yang belum mengambil gelar syah). Menurut entri Derbent di TDV İslâm Ansiklopedisi, penarikan ini adalah akibat Rusia tidak ingin berjuang di dua front di selatan (Utsmaniyah dan Iran) sekaligus dan memperkuat gengsi militer Nadir yang membuka jalan naik takhtanya beberapa tahun kemudian. Tarki (Tarku) di bawah pemerintahan Rusia juga kembali ke pihak Iran dengan penarikan ini (di peta hari Ganja digunakan). Salyan dan Şâbüran di bawah pemerintahan Rusia juga beralih ke pihak Iran dengan penarikan ini (hari khusus permukiman tidak ada dalam sumber, di peta hari Ganja digunakan — pendekatan yang dinyatakan).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Naik takhtanya Nadir Syah di Padang Mugan: berakhirnya dinasti Safawi secara faktual", "4f640979"], "d": ["Menurut entri Nadir Şah di TDV İslâm Ansiklopedisi, kurultai sekitar dua puluh ribu orang yang berkumpul di Padang Mugan dengan gigih meminta ia memimpin Iran; Nadir menerima tawaran itu dengan syarat ditinggalkannya pemahaman Syiah ekstrem yang menyebabkan perang antara Safawi dan Utsmaniyah dan diterimanya mazhab Ja'fari yang moderat, dan naik takhta dengan gelar Nâdir Şah pada 24 Şewal 1148 (8 Maret 1736). Ini berarti berakhirnya dinasti Safawi yang berusia dua abad secara faktual dan berdirinya dinasti Afsyar.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Dimulainya wabah di Istanbul", "9fa82b56"], "d": ["Menurut entri \"Tâun\" di TDV, wabah yang berpengaruh di geografi Islam antara 1739-1743 juga menyerang Istanbul pada masa ini. Entri itu mencatat bahwa epidemi abad ke-18 berlangsung relatif lebih ringan dibandingkan abad-abad sebelumnya. Di antara masa-masa wabah juga disebut tahun 1713, 1719, 1728-1729, dan 1759-1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Kebakaran Hocapaşa", "321c7d0d"], "d": ["Menurut entri \"Fatma Sultan Camii\" di TDV, kebakaran Hocapaşa yang pecah pada malam hari menghancurkan Bâbıâli dan sekitarnya; diperkirakan Masjid Fatma Sultan di wilayah itu juga rusak dalam kebakaran ini. Bencana ini, salah satu kebakaran besar yang menimpa Istanbul pada masa Osman III, menimbulkan kerusakan berat di pusat perdagangan dan pemerintahan kota.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Kesadrazaman Koca Ragıp Mehmed Paşa", "a1846910"], "d": ["Ragıp Paşa, yang dikenal dengan identitasnya sebagai penyair dan diplomat, diangkat Osman III ke jabatan sadrazam (pada Oktober 1757 ia melanjutkan jabatan atas wafatnya Osman III dan menerima stempel baru dari Mustafa III). Ketika Perang Tujuh Tahun berlangsung, ia menjalankan kebijakan luar negeri seimbang yang menjauhkan Negara Utsmaniyah dari konflik di Eropa. Selama kesadrazamannya yang akan berlangsung enam tahun, ia juga memberi perhatian pada kegiatan budaya seperti mendirikan perpustakaan.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Wafatnya Ragıp Paşa", "6bc19323"], "d": ["Ragıp Paşa wafat setelah kesadrazaman enam tahun. Dengan wafatnya, kesadrazaman paling lama dan seimbang masa Mustafa III berakhir.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Gempa besar Istanbul dan runtuhnya Masjid Fâtih", "2475b4dc"], "d": ["Menurut entri \"Fâtih Camii ve Külliyesi\" di TDV, dalam gempa besar 1766 kubah utama masjid runtuh sepenuhnya dan dindingnya rusak hingga tidak dapat diperbaiki. Pembangunan kembali yang dimulai pada 1767 atas perintah Mustafa III di bawah pimpinan arsitek Sarım İbrahim Efendi dan İzzet Mehmed Bey, dengan rancangan baru yang berbeda dari rencana lama, selesai pada 1771.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Percobaan sekolah artileri berumur pendek di bawah pimpinan Baron de Tott", "4192260c"], "d": ["Menurut entri \"Mühendishâne-i Bahrî-i Hümâyun\" di TDV, kegagalan dalam Perang Utsmaniyah-Rusia 1768 memperlihatkan kebutuhan pendidikan militer teknis; sekolah artileri berumur pendek yang dibuka dengan sumbangan perwira Prancis Baron de Tott mulai beroperasi pada Oktober 1772 tetapi tidak efektif. Percobaan ini dianggap pendahulu Mühendishâne-i Bahrî-i Hümâyun yang akan didirikan pada 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selim III naik takhta", "00d046d9"], "d": ["Atas wafatnya Abdülhamid I, keponakannya Selim III naik takhta. Menurut entri Selim III di TDV İslâm Ansiklopedisi, sultan baru, yang sejak masa şehzade tertarik pada reformasi pasukan Eropa, segera setelah naik takhta mulai menyiapkan program pembaruan mendasar. Program ini dalam beberapa tahun akan dikenal dengan nama Nizâm-ı Cedîd.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Dimulainya persiapan program reformasi Nizâm-ı Cedîd", "eff78a68"], "d": ["Selim III menyiapkan program pembaruan komprehensif sesuai layihat yang dimintanya dari pembesar negara dan ahli asing. Menurut entri Nizâm-ı Cedîd di TDV İslâm Ansiklopedisi, program ini tidak terbatas pada pembentukan pasukan baru; ia berubah menjadi gerakan reformasi luas yang juga mencakup keuangan, pemerintahan provinsi, dan diplomasi. Program ini akan menemukan pendukung maupun penentang selama lima belas tahun berikutnya.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Kedutaan tetap didirikan di ibu kota-ibu kota Eropa", "2e9dc8a1"], "d": ["Selim III, untuk pertama kalinya dalam sejarah Negara Utsmaniyah, mengirim duta tetap yang akan bertugas terus-menerus ke pusat-pusat besar Eropa. Menurut entri Elçi di TDV İslâm Ansiklopedisi, langkah ini memberi diplomasi Utsmaniyah, yang sampai saat itu dijalankan hanya dengan delegasi sementara dan satu kali, organisasi yang permanen. Tugas utama kedutaan baru adalah melaporkan perkembangan politik dan militer di Eropa secara teratur ke Istanbul.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Perbendaharaan İrad-ı Cedîd didirikan", "ae5c8ce2"], "d": ["Perbendaharaan terpisah didirikan untuk menutup biaya pasukan Nizâm-ı Cedîd dan program reformasi. Menurut entri Esham di TDV İslâm Ansiklopedisi, di antara pendapatan perbendaharaan baru terdapat pengelolaan beberapa mukataa langsung oleh negara dan dibawanya penjualan esham ke bawah kendali. Pengaturan ini merupakan upaya menciptakan sumber baru di luar sistem keuangan tradisional.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Pemberontakan Kabakçı Mustafa dimulai", "b98eee17"], "d": ["Ketidakpuasan yang menumpuk terhadap Nizâm-ı Cedîd meletus dengan pemberontakan prajurit yamak di bawah pimpinan Kabakçı Mustafa. Menurut entri Kabakçı İsyanı di TDV İslâm Ansiklopedisi, para pemberontak dalam waktu singkat menguasai Istanbul dan menuntut kepala negarawan pendukung Nizâm-ı Cedîd. Pemberontakan berujung dalam beberapa hari pada diturunkannya Selim III dari takhta.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selim III diturunkan dari takhta", "ff2c30ec"], "d": ["Di bawah tekanan pemberontakan Kabakçı Mustafa, Selim III diturunkan dari takhta dengan fatwa yang diperoleh dari Şeyhülislâm. Menurut entri Selim III di TDV İslâm Ansiklopedisi, keputusan ini adalah saat berakhirnya masa reformasi delapan belas tahun secara faktual; pasukan Nizâm-ı Cedîd juga dibubarkan dalam waktu singkat. Selim mulai ditahan di Istana Topkapı.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafa IV naik takhta", "8f1ac86c"], "d": ["Segera setelah diturunkannya Selim III, keponakannya Mustafa IV dinyatakan sultan. Menurut entri Mustafa IV di TDV İslâm Ansiklopedisi, sultan baru memulai kesultanan di bawah pengaruh lingkungan anti-Nizâm-ı Cedîd yang mendukung pemberontakan. Masa singkat ini menjadi fase ketidakstabilan ketika otoritas sentral melemah sepenuhnya.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Paşa memasuki Istanbul dengan pasukannya", "0cad3dea"], "d": ["Alemdar Mustafa Paşa, âyan Rusçuk, tiba di depan Istanbul dengan pasukannya dengan tujuan menaikkan kembali Selim III ke takhta. Menurut entri Alemdar Mustafa Paşa di TDV İslâm Ansiklopedisi, masuknya ke kota disambut sendiri oleh Mustafa IV; namun dalam beberapa hari keseimbangan kekuatan dalam istana akan berubah sepenuhnya. Masuk ini memulai rantai peristiwa yang berujung pada wafatnya Selim sekaligus naik takhta baru.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selim III dibunuh", "e452f5f6"], "d": ["Pada hari Alemdar Mustafa Paşa menguasai Bâbıâli, Selim III dibunuh di istana atas perintah Mustafa IV. Menurut entri Selim III di TDV İslâm Ansiklopedisi, ini adalah keputusan yang diberikan untuk mencegah upaya menaikkan kembali seorang sultan yang diturunkan ke takhta. Wafatnya Selim berujung pada naik takhtanya Mahmud pada hari yang sama.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmud II naik takhta", "661c1974"], "d": ["Setelah dibunuhnya Selim III, Mahmud, yang tinggal sebagai satu-satunya anggota laki-laki dinasti, naik takhta dengan dukungan Alemdar Mustafa Paşa. Menurut entri Mahmud II di TDV İslâm Ansiklopedisi, sultan baru melewatkan bulan-bulan pertama kesultanannya di bawah perwalian Alemdar yang menaikkannya dan dengan upaya membangun kembali keseimbangan antara âyan dan pusat. Masa ini menjadi awal proses reformasi mendasar dua puluh tahun berikutnya.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Pasukan Sekbân-ı Cedîd didirikan", "6f9eb5e4"], "d": ["Alemdar Mustafa Paşa mendirikan pasukan baru berperlengkapan ala Eropa sebagai pengganti Nizâm-ı Cedîd yang dibubarkan. Menurut entri Sekbân-ı Cedîd di TDV İslâm Ansiklopedisi, kekuatan yang terdiri dari tiga resimen ini dipandang di mata janisari sebagai ancaman langsung dan dilenyapkan hanya beberapa bulan setelah pendiriannya dalam pemberontakan janisari.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Jatuhnya İbrâil — celah besar pertama di garis Danube", "ee519321"], "d": ["Dalam perang Rusia yang dimulai pada 1806, Benteng İbrâil di tepi utara Danube dikepung dan dibombardir pasukan Rusia di bawah komando Count Kamensky. Di dalam terdapat 4100 infanteri, 1100 penunggang kuda, dan 260 meriam; benteng menyerah kepada Jenderal Essen karena kesulitan makanan. Ujung utara garis pertahanan Danube dengan demikian terbuka.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Penyerahan Rusçuk — tepi selatan Danube juga lepas", "084062e8"], "d": ["Rusçuk bertahan menghadapi pengepungan panjang dan berdarah pasukan Rusia di bawah komando Count Kamensky; ia menyerah dengan syarat garnisun dan penduduk sipil meninggalkan kota dengan aman. Jatuhnya kota-benteng terkuat di tepi selatan Danube membalikkan jalannya perang demi keuntungan Rusia.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Ocak Eşkinci didirikan", "67c56759"], "d": ["Mahmud II mendirikan unit baru yang akan dilatih ala Eropa dengan prajurit yang dipilih dari dalam korps janisari. Menurut entri Eşkinci Ocağı di TDV İslâm Ansiklopedisi, unit mulai berlatih pada 12 Juni 1826, tetapi para janisari memandangnya sebagai akhir ocak mereka sendiri. Pemberontakan yang pecah tiga hari kemudian mengakhiri usia singkat Ocak Eşkinci juga.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Asâkir-i Mansûre-i Muhammediyye didirikan", "14b84a7e"], "d": ["Segera setelah dihapuskannya Korps Janisari, Mahmud II mendirikan tentara baru yang teratur dan terdidik ala Eropa sebagai gantinya. Menurut entri Asâkir-i Mansûre-i Muhammediyye di TDV İslâm Ansiklopedisi, tentara ini, dengan tatanan pangkat, program pelatihan, dan sistem gajinya, berbeda dari percobaan-percobaan sebelumnya dan menjadi lembaga yang permanen. Pasukan itu pada tahun-tahun berikutnya akan berubah menjadi tentara Nizamiye masa Tanzimat.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["Tarekat Bektashi ditutup", "f7d9a367"], "d": ["Bersamaan dengan dihapuskannya Korps Janisari, tarekat Bektashi, yang diketahui memiliki ikatan keagamaan dengan ocak, juga dilarang. Menurut entri Bektaşîlik di TDV İslâm Ansiklopedisi, sementara beberapa syekh tekke kecil dieksekusi, syekh dergah Hacı Bektaş diasingkan ke Amasya dan tekke-tekke diserahkan kepada pengelolaan Naqshbandi. Tarekat tetap melanjutkan pengorganisasiannya secara tersembunyi meski pukulan berat ini.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["Peristiwa kipas — dalih pendudukan", "e949001e"], "d": ["Dalam perundingan yang menegang karena utang gandum lama Prancis kepada Aljazair, Dey Hüseyin memukul konsul Prancis Deval dengan kipas di tangannya. Peristiwa yang timbul dari sengketa piutang ini dijadikan dalih resmi pendudukan yang akan dimulai tiga tahun kemudian.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Blokade Prancis atas pesisir Aljazair — pengepungan tiga tahun", "d0ba97a5"], "d": ["Setelah peristiwa kipas, Prancis memblokade pesisir Aljazair. Blokade berlangsung tiga tahun; perdagangan laut dan sumber pendapatan ocak dikeringkan dan daya perlawanannya terkikis sebelum pendudukan dimulai.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["Perjanjian Turkmenchay: beralihnya Revan dan Talysh ke Rusia", "abffcfdb"], "d": ["Ketika Perang Rusia-Iran 1826-1828 berakhir dengan kekalahan berat Iran, dengan perjanjian yang ditandatangani di Turkmenchay khanat Revan dan Nakhchivan serta wilayah Talysh di pesisir Kaspia (Lankaran, Astara) diserahkan kepada Rusia; ganti rugi perang berat juga dikenakan. Menurut entri Revan di TDV İslâm Ansiklopedisi, kehilangan ini adalah saat perbatasan Rusia-Iran di Kaukasus digambar sedemikian rupa sehingga sebagian besar tetap berlaku hingga hari ini dan juga memicu migrasi penduduk Armenia ke Revan. Dengan perjanjian ini khanat Revan (Echmiadzin, Iğdır, Norapat, Beri) dan khanat Nakhchivan (Culfa, Şerur) beralih ke Rusia.", "847d76d5"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Jatuhnya İbrâil untuk kedua kali — Tsar Nikolai di depan benteng", "eb6a8741"], "d": ["İbrâil, yang dikembalikan kepada Utsmaniyah pada 1812 dan diperkuat kembali pada 1817-1818, dikepung pada bulan April dengan 4000 penjaga dan 278 meriam di dalamnya. Penjaganya Ebûbekir Paşa membangun garis pertahanan baru; Tsar Nikolai I tiba sendiri di depan benteng pada akhir Mei. Kota diduduki Rusia, tetapi akan dikembalikan dengan Perjanjian Edirne dan diserahkan kepada kepangeranan Wallachia.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["Fez dinyatakan penutup kepala resmi", "f55be4eb"], "d": ["Mahmud II melakukan perubahan mendasar pada pakaian pegawai dan prajurit dan menyatakan fez sebagai penutup kepala resmi menggantikan serban. Menurut entri Fes di TDV İslâm Ansiklopedisi, keputusan ini diumumkan dengan hatt-ı hümâyun dan diterapkan bersama reformasi ala Barat Asâkir-i Mansûre-i Muhammediyye. Perubahan itu juga berarti diakhirinya hierarki pakaian tradisional.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Penyerahan Ahıska kepada Rusia — pusat eyalet Çıldır lepas", "e2e00b2a"], "d": ["Ahıska, yang berada di bawah pemerintahan Utsmaniyah sejak Perang Çıldır 1578 dan menjadi pusat eyalet Çıldır, ditinggalkan kepada Rusia dengan Perjanjian Edirne yang ditandatangani pada akhir perang 1828-1829. Lepasnya kota menimbulkan kesedihan mendalam di kalangan rakyat dan menjadi subjek banyak ratapan. Dengan peristiwa ini Ahılkelek, Zazalo, dan Ts'q'altbila (wilayah Ahıska–Ahılkelek) beralih ke Rusia.", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Pendaratan di Sidi Ferruch — pasukan Prancis di tanah Aljazair", "33327553"], "d": ["Setelah blokade tiga tahun, pasukan pendarat Prancis di bawah komando Comte de Bourmont mendaratkan prajurit di teluk Sidi Ferruch di barat Aljir. Pasukan yang maju ke arah kota mematahkan garis pertahanan dalam tiga minggu; pada 4 Juli Benteng Kaisar yang menguasai kota jatuh, dan keesokan harinya Dey Hüseyin menyerah.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Pengasingan Dey Hüseyin — berakhirnya Ocak Aljir secara faktual", "e122403b"], "d": ["Sesuai syarat penyerahan, dey Aljir terakhir Hüseyin dikeluarkan dari kota bersama keluarga dan hartanya dan dikirim ke Napoli. Pemerintahan ocak yang diikat kepada Selim I (Yavuz) pada 1519 dan selama tiga ratus tahun menjadi pangkalan laut Utsmaniyah terkuat di Mediterania pun berakhir.", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Penarikan pasukan Rusia dari Wallachia dan Moldavia — akhir pendudukan enam tahun", "efdb0275"], "d": ["Dalam perang Utsmaniyah-Rusia 1828-1829 Rusia menduduki Wallachia dan Moldavia, dan setelah Perjanjian Edirne juga tidak mundur hingga ganti rugi perang dibayar. Ketika ganti rugi diturunkan menjadi lima juta pada Januari 1834, pasukan Rusia mengosongkan Memleketeyn dan voivode-voivode baru diangkat untuk kedua kepangeranan. Suzerainty Utsmaniyah kembali di atas kertas, tetapi Rusia mempertahankan pengaruh yang dibangunnya dengan Règlement Organique.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Organisasi Redif-i Asâkir-i Mansûre didirikan", "15947493"], "d": ["Organisasi Redif sebagai pasukan cadangan yang akan mendukung Asâkir-i Mansûre-i Muhammediyye didirikan dengan peraturan tertanggal 8 Juli 1834. Menurut entri Redif di TDV İslâm Ansiklopedisi, di bawah pimpinan Serasker Koca Hüsrev Paşa dibentuk batalyon sekitar seribu empat ratus orang di kaza-kaza provinsi. Organisasi itu dirancang sehingga juga mendukung keamanan lokal tanpa diambil dalam dinas terus-menerus.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Kementerian Luar Negeri didirikan", "750c6c7d"], "d": ["Mahmud II menghapus jabatan Reisülküttâblık yang mengurus urusan luar negeri dan menggantinya dengan Kementerian Luar Negeri (Hariciye Nezareti). Menurut entri Hariciye Nezâreti di TDV İslâm Ansiklopedisi, Mehmed Âkif Paşa diangkat sebagai menteri pertama kementerian baru dan organisasi mulai bekerja di kediaman duta Wina Rıfat Bey. Pengaturan ini adalah awal dijalankannya kebijakan luar negeri Utsmaniyah menurut asas kementerian modern.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Meclis-i Vâlâ-yı Ahkâm-ı Adliyye didirikan", "69db056e"], "d": ["Mahmud II mendirikan Meclis-i Vâlâ-yı Ahkâm-ı Adliyye sebagai majelis tingkat tinggi tempat undang-undang dan peraturan yang akan disiapkan dibahas. Menurut entri Meclis-i Vâlâ-yı Ahkâm-ı Adliyye di TDV İslâm Ansiklopedisi, majelis mulai bekerja secara faktual pada 31 Maret 1838 dan hampir seluruh reformasi Tanzimat berikutnya disiapkan dan diawasi melalui dewan ini. Lembaga itu menjadi salah satu pusat terpenting birokrasi Utsmaniyah modern.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Serbuan Sinop", "5947e93f"], "d": ["Armada Rusia Laut Hitam di bawah komando Laksamana Nakhimov menyerbu armada Utsmaniyah yang berlabuh di Pelabuhan Sinop tanpa pernyataan perang; dua belas kapal tenggelam, lebih dari dua ribu prajurit gugur sebagai syahid, dan komandan armada Osman Paşa ditawan. Menurut entri Sinop di TDV İslâm Ansiklopedisi, dalam serbuan itu di kota juga terbakar tujuh masjid kecil, dua sekolah, 247 rumah, dan 170 toko, dan enam belas sipil Kristen dan lima Muslim tewas. Peristiwa yang bergema di opini publik Eropa sebagai 'bencana Sinop' itu menjadi pemicu langsung masuknya Inggris dan Prancis ke perang di pihak Utsmaniyah dalam beberapa bulan.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Terbitnya Tasvir-i Efkâr", "506c98e2"], "d": ["Tasvir-i Efkâr, yang diterbitkan Şinasi, mulai terbit sebagai surat kabar Turki keempat setelah Takvîm-i Vekāyi', Cerîde-i Havâdis, dan Tercüman-ı Ahvâl. Menurut entri \"Tasvîr-i Efkâr\" di TDV, surat kabar itu menjadi juru bicara gerakan Utsmani Muda pada masa Nâmık Kemal yang kemudian memegang redaksi utama.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Perkumpulan Utsmani Muda didirikan", "335fb02d"], "d": ["Para intelektual Utsmaniyah yang melarikan diri ke Eropa di bawah pimpinan Mustafa Fâzıl Paşa mengorganisasi diri dengan nama Turki Muda melalui peraturan tiga belas pasal. Menurut entri \"Yeni Osmanlılar Cemiyeti\" di TDV, kelompok itu menyebarkan tuntutan pemerintahan konstitusional dengan menerbitkan surat kabar seperti Muhbir dan Hürriyet di Paris, London, dan Jenewa.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Şûrâ-yı Devlet didirikan", "b863b306"], "d": ["Meclis-i Ahkâm-ı Adliyye dibagi dua dan Şûrâ-yı Devlet yang mengurus urusan administratif serta Dîvân-ı Ahkâm-ı Adliyye yang menangani urusan peradilan dibentuk. Menurut entri \"Şûrâ-yı Devlet\" di TDV, Midhat Paşa diangkat sebagai presiden pertama lembaga yang mengambil Conseil d'État Prancis sebagai model; tujuannya adalah pemisahan legislatif, eksekutif, dan yudikatif.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Keluarnya irade pendirian Darülfünun", "513704bf"], "d": ["Dengan irade yang disiapkan Sadrazam Âli Paşa dan Menteri Pendidikan Saffet Paşa, Darülfünun didirikan secara resmi; kuliah pertama telah dimulai sebelumnya pada 1863. Menurut entri \"Darülfünun\" di TDV, lembaga itu mulai mengajar secara faktual pada Februari 1870 di bawah direktur Hoca Tahsin Efendi dengan cabang filsafat-sastra, sains, dan hukum.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Dimulainya pekerjaan Mecelle-i Ahkâm-ı Adliyye", "8abdcbee"], "d": ["Perkumpulan Mecelle yang dibentuk di bawah pimpinan Ahmed Cevdet Paşa, presiden Dîvân-ı Ahkâm-ı Adliyye, mulai menyiapkan kitab undang-undang perdata yang bertumpu pada fikih Hanafi. Menurut entri \"Mecelle-i Ahkâm-ı Adliyye\" di TDV, bagian terakhir karya yang terdiri dari enam belas kitab dan 1851 pasal itu selesai pada 15 September 1876 dan berlaku; dianggap bentuk hukum Islam pertama yang dikodifikasi.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["\"Vatan yahut Silistre\" dipentaskan, Nâmık Kemal diasingkan", "3861284c"], "d": ["Ketika lakon bertema patriotisme karya Nâmık Kemal dipentaskan di Teater Gedikpaşa, para penonton tumpah ke jalan dengan seruan \"Hidup tanah air, hidup Kemal\". Menurut entri \"Nâmık Kemal\" di TDV, pemerintah yang gentar akan demonstrasi ini menutup surat kabar İbret dan pada 6 April 1873 mengasingkan Nâmık Kemal ke Siprus (Magosa) tanpa pengadilan.", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Abdülaziz wafat secara mencurigakan", "85816692"], "d": ["Abdülaziz, yang dipindahkan atas permintaannya sendiri ke Istana Feriye setelah diturunkan dari takhta (1 Juni 1876), ditemukan pada 4 Juni di kamarnya dengan urat pergelangan tangan terpotong. Panitia dokter sembilan belas orang, termasuk dokter kedutaan, menyusun laporan dengan ungkapan samar; kematian diumumkan pada 6 Juni di surat kabar sebagai bunuh diri. Penyelidikan yang dibuka Abdülhamid II sebaliknya sampai pada keyakinan bahwa kematian itu bukan bunuh diri melainkan pembunuhan dan para terdakwa diadili di Pengadilan Yıldız pada 1881; persoalan itu hingga kini masih diperdebatkan dalam penulisan sejarah.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Pemecatan dan pengasingan Midhat Paşa dari kesadrazaman", "b5247b06"], "d": ["Sadrazam Midhat Paşa, arsitek Kanûn-ı Esâsî, enam minggu setelah proklamasinya dicopot dari jabatan oleh Abdülhamid II dan diasingkan ke luar negeri dalam satu malam. Menurut entri Midhat Paşa di TDV İslâm Ansiklopedisi, pemecatan dikaitkan dengan ketidaknyamanan sultan atas ketentuan dalam konstitusi yang membatasi wewenangnya sendiri. Sang paşa pergi pertama ke Napoli, kemudian ke berbagai kota Eropa.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Abdulaziz b. Saud merebut kembali Riyadh dari Rashidi", "75eb8830"], "d": ["Abdulaziz muda dari dinasti Saud, yang sepuluh tahun sebelumnya pergi diasingkan ke Kuwait, menyerbu Riyadh dengan detasemen kecil dan merebut kota dengan membunuh wakil gubernur Âl-i Reşîd (Shammar). Menurut entri Riyad di TDV İslâm Ansiklopedisi, melemahnya Rashidi secara bertahap dan ketidakmampuan mengirim bala bantuan ke kota memudahkan keberhasilan serbuan ini; peristiwa itu dianggap saat berdirinya Negara Saudi Kedua yang dalam tiga puluh tahun berikutnya akan membentuk inti Arab Saudi saat ini.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["Masuknya Tentara Aksi ke Istanbul", "41c8304c"], "d": ["Tentara Aksi, yang berangkat dari Selanik dan sebagian besar terdiri dari unit-unit yang terikat pada Komite Persatuan dan Kemajuan, memasuki Istanbul untuk menumpas pemberontakan 31 Mart. Menurut entri Hareket Ordusu di TDV İslâm Ansiklopedisi, komando dipegang Mahmud Şevket Paşa dan kepala staf dijabat Kolağası Mustafa Kemal. Setelah bentrokan singkat, ketertiban di kota dipulihkan kembali.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["Pembubaran Meclis-i Mebusan Utsmaniyah terakhir", "2b709269"], "d": ["Setelah Istanbul diduduki resmi oleh pasukan Entente dan banyak anggota parlemen ditangkap, Meclis-i Mebusan tidak dapat bekerja dan dibubarkan secara resmi dengan irade Mehmed VI. Menurut entri Meclis-i Mebusan di TDV İslâm Ansiklopedisi, pembubaran ini melambangkan berakhirnya tradisi parlemen konstitusional Utsmaniyah secara faktual. Penutupan itu memperkuat kebutuhan berkumpulnya majelis nasional baru di Ankara.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["Pembukaan Majelis Agung Nasional Turki", "6eab539d"], "d": ["Setelah dibubarkannya Meclis-i Mebusan di Istanbul, para anggota parlemen berkumpul di Ankara dan membuka Majelis Agung Nasional Turki dan Mustafa Kemal Paşa terpilih sebagai ketua majelis. Menurut entri Türkiye Büyük Millet Meclisi di TDV İslâm Ansiklopedisi, majelis itu bersifat luar biasa dengan menghimpun wewenang legislatif dan eksekutif pada dirinya. Pembukaan ini adalah titik balik ketika pusat politik dan kelembagaan perjuangan nasional dipindahkan ke Ankara. Dengan peristiwa ini 124 permukiman (wilayah Turki yang tidak diduduki), termasuk Konya, Sivas, Kayseri, Eskişehir, Erzurum, Trabzon, Samsun, Diyarbakır, Van, Malatya, Denizli, dan Isparta, masuk ke pemerintahan pemerintah TBMM.", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Penaklukan benteng İzvornik (Zvornik)", "657c465a"], "d": ["Benteng İzvornik di tepi Drina ditaklukkan Utsmaniyah pada 1460. Menurut TDV İslâm Ansiklopedisi, karena kedudukannya yang menguntungkan secara administratif dan militer, ia pertama dijadikan pusat kaza, pada 1480 menjadi pusat sancak dengan nama yang sama, dan pada 1491 diperkuat dengan tembok batu dan berubah menjadi pusat administratif-dagang penting dengan enam masjid, delapan tekke, dan pemandiannya.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Wafatnya Kasım Han, naik takhtanya Danyal Han (Khanat Kasimov)", "522fd0fd"], "d": ["Dengan wafatnya pendiri khanat Kasım Han pada 873/1468, putranya Danyal menggantikan; Danyal memerintah hingga 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["Pertempuran Laut Diu — supremasi Portugis di Samudra Hindia", "1778d347"], "d": ["Armada Melik Ayaz, yang memerintah wilayah atas nama Kesultanan Gujarat dan didukung Mamluk, menderita kekalahan berat di lepas Diu menghadapi armada gubernur jenderal Portugis Francisco de Almeida, yang berupaya mendirikan pangkalan pasokan di pesisir ini. Kekalahan ini memberi Portugis supremasi laut permanen di Samudra Hindia dan mematahkan kekuatan laut Mamluk-Gujarat; ia dianggap awal ketidakseimbangan kekuatan yang membentuk latar belakang perjuangan Laut Merah-Samudra Hindia yang diambil alih Utsmaniyah setelah 1517 (pertahanan Jeddah, pengepungan Diu 1538).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["Pemberontakan Kalender Şah", "f60f6ca4"], "d": ["Dengan pengaruh kesulitan keuangan di Anatolia, ketidakpuasan atas penataan administratif baru, dan propaganda Safawi, suku-suku Turkmen besar seperti Çiçekli, Akça Koyunlu, Masadlı, dan Bozoklu serta kelompok-kelompok yang tersisa dari pemberontakan Baba Zünnûn terdahulu berkumpul di sekitar Kalender Şah dan mencapai kekuatan sekitar tiga puluh ribu orang. Para pemberontak pertama mengalahkan Beylerbeyi Rum; dengan Sadrazam Makbul İbrâhim Paşa menghimpun prajurit dan menjanjikan hak mereka, dukungan Kalender menyusut dan pemberontakan ditumpas di sekitar Elbistan, Kalender Şah dan Veli Dündar dibunuh pada Juni 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Penaklukan Şehrizor — direbutnya Benteng Zalm", "4320d9b8"], "d": ["Selama ekspedisi Nakhchivan Kanuni, Beylerbeyi Baghdad Osman Paşa telah ditugaskan menaklukkan wilayah Şehrizor; Baltacı Mehmed Paşa, yang menjadi beylerbeyi Baghdad atas wafatnya, mengepung Zalm, benteng pusat wilayah, dan merebutnya pada 22 Agustus 1554 (23 Ramadan 961). Dengan demikian cekungan Şehrizor di lereng barat Zagros masuk ke pemerintahan Utsmaniyah dan hubungan antara Baghdad dan Kurdistan dijamin; wilayah pertama dijadikan sancak dan diberikan kepada Murad Bey. Pada 1563 Beylerbeyi Muzaffer Paşa membangun Benteng Gülanber sebagai pusat eyalet baru; benteng akan dirobohkan atas perintah Syah Abbas pada 1623 dan dibangun kembali pada masa Hüsrev Paşa pada 1638.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["Penguasa Khanat Kasimov memeluk Kristen dan dicopot dari khanat", "a1a8eeb9"], "d": ["Penguasa di kepala khanat mengambil nama 'Semen (Simeon)' dan menjadi Kristen; Rusia, dengan memperhitungkan reaksi rakyat Muslim, mencopotnya dari khanat. Orang ini tak lama kemudian dinyatakan penguasa nominal di Moskow oleh Ivan yang Mengerikan dengan gelar 'adipati agung tsar dan Rusia' (1575) — persilangan paling mencolok antara Khanat Kasimov dan takhta Moskow.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["Terikatnya sancak Fezzan ke Tripolitania — Murzuk dan persimpangan kafilah Sahara", "2e6554a4"], "d": ["Sebagai hasil tekanan beylerbeylik Tripolitania, Fezzan, persimpangan kafilah Sahara, menerima ketundukan Utsmaniyah dengan pusat di Murzuk. Menurut entri Fizan di TDV İslâm Ansiklopedisi, dinasti Evlâd-ı Muhammed yang memerintah wilayah itu dibiarkan bebas dalam urusan dalam negeri dengan syarat membayar pajak teratur; Fezzan diorganisasi sebagai sancak yang terikat pada eyalet Tripoli yang direbut pada 1551. Dengan demikian perdagangan budak, emas, dan unta di garis Tripoli-Murzuk-Bornu masuk ke kendali Utsmaniyah. Pemerintahan tidak langsung ini akan jatuh ke tangan Karamanlı pada 1711 dan ke organisasi kaza langsung pada 1842.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["Masuknya Nakhchivan dan Ordubad ke pemerintahan Utsmaniyah", "24d939b3"], "d": ["Setelah Revan direbut dan dijadikan pusat beylerbeylik pada 1583, pasukan yang turun ke tenggara di sepanjang lembah Aras mengikat Nakhchivan dan Ordubad ke pemerintahan Utsmaniyah; kedua kota menjadi sancak eyalet Revan yang baru dibentuk. Menurut entri Nahcıvan di TDV İslâm Ansiklopedisi, pemerintahan Utsmaniyah permanen pertama di kota didirikan selama perang ini — dalam ekspedisi Nakhchivan 1553 kota direbut tetapi hanya dijarah dan ditinggalkan. Dengan demikian jalan pasukan antara Revan dan Tabriz terbuka dan Tabriz dapat dimasuki pada bulan September tahun yang sama. Syah Abbas akan merebut kembali Nakhchivan pada 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Pemberontakan Deli Hasan Paşa dan redanya dengan beylerbeylik Bosnia", "144f3f2d"], "d": ["Deli Hasan, saudara yang memegang kepala gerakan setelah wafatnya pemimpin Celali Karayazıcı Abdülhalim pada 1602, dengan memanfaatkan kebebasan gerak yang diberikan perang Austria yang berlanjut kepada kelompok-kelompok Celali, menyerbu Kütahya dan berbaris ke Afyonkarahisar. Pada masa ketika negara menghadapi front Austria dan Iran sekaligus, masalah diselesaikan 'dengan kemanisan': dengan memberi Deli Hasan pangkat paşa dan beylerbeylik Bosnia, gerakan pemberontakan diakhiri secara resmi pada 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["Perebutan kota Kasimov oleh pasukan Rusia, Uraz Muhammed Khan", "b3f0bd34"], "d": ["Sebagai cerminan Masa Kekacauan (Smuta) di Rusia, pasukan Rusia mengepung dan merebut kota Kâsım, membantai sebagian besar penduduknya dengan pedang. Uraz Muhammed, kepala khanat, menjadi sasaran karena mendukung Dmitri Palsu II; pada tahun berikutnya (1610) ia sendiri dibunuh dalam sebuah persekongkolan.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["Hilangnya Benteng Azak ke Kosak Don", "ba068b2f"], "d": ["Kosak Don merebut Benteng Azak, yang mereka kepung pada 21 April 1637, dua bulan kemudian; benteng yang merupakan gerbang timur laut Laut Hitam dan kunci perdagangan Don itu untuk pertama kalinya lepas dari tangan Utsmaniyah. Menurut entri Azak di TDV İslâm Ansiklopedisi, Kosak merebut benteng pada 1637, bertahan pada 1641 menghadapi pengepungan besar tiga bulan di bawah komando Deli Hüseyin Paşa, dan baru mengosongkan benteng pada 1642 dengan kedatangan Khan Krimea Mehmed Giray. Negara saat itu sibuk dengan front Baghdad; ketidakmampuan mempertahankan benteng selama lima tahun adalah retakan pertama sifat 'danau Utsmaniyah' Laut Hitam.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["Direbutnya kembali Limni dan Samothrace", "c445553b"], "d": ["Setelah Bozcaada dibebaskan pada 31 Agustus 1657, Köprülü Mehmed Paşa mengarahkan armada ke utara dan merebut kembali Limni dan Samothrace yang dikuasai Venesia selama enam belas bulan. Menurut entri Limni di TDV İslâm Ansiklopedisi, pulau jatuh ke tangan Venesia pada Juli 1656 dan direbut kembali pada November 1657. Dengan demikian blokade Venesia di mulut Selat Çanakkale patah sepenuhnya dan jalur gandum Istanbul diamankan kembali; ini adalah perolehan paling nyata tahun pertama ketika sadrazam datang dengan wewenang luar biasa.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["Hilangnya Knin ke Venesia — benteng perbatasan Dalmatia berusia 166 tahun jatuh", "252406b7"], "d": ["Dalam perang multi-front yang dibuka setelah kekalahan Wina 1683, pasukan Venesia maju ke pedalaman Dalmatia. Knin, yang dikepung jenderal Dalmatia Girolamo Cornaro, diserahkan oleh beylerbeyi Mehmed Paşa setelah pengepungan dua belas hari. Knin adalah benteng kunci garis perbatasan Dalmatia yang ditaklukkan Gazi Hüsrev Bey pada 1522 dan tetap di tangan Utsmaniyah selama 166 tahun; hilangnya membuka wilayah itu sebagian besar kepada Venesia.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["Direbutnya kembali Basra dari pendudukan Iran", "5b10c5c1"], "d": ["Basra, yang direbut Sâdık Han, saudara Kerim Han Zend, pada 1776, dikosongkan ketika perebutan takhta dimulai di Iran setelah wafatnya Kerim Han pada 2 Maret 1779; Sâdık Han kembali ke Iran dengan klaim kesultanan. Kota untuk waktu singkat tetap di tangan suku Müntefik, kemudian kembali masuk ke pemerintahan Utsmaniyah. Mantan mütesellim Süleyman Ağa, yang kembali dari Shiraz, meminta jabatan gubernur Basra dan menjadi gubernur Basra, Baghdad, dan Şehrizor dengan nama Büyük Süleyman Paşa. Perdagangan Teluk kembali ke kendali Utsmaniyah; pada tahun-tahun pendudukan sebagian perdagangan bergeser ke Kuwait dan sejak 1778 pos gurun juga dikeluarkan dari Kuwait.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["Wafatnya Timur Syah, naik takhtanya Zaman Syah (Negara Durrani)", "c3effdb2"], "d": ["Dengan wafatnya Timur Syah, yang selama lebih dari dua puluh tahun mengonsolidasikan negeri dari dalam, tiga saudara gubernur Kandahar-Herat-Kabul berebut takhta; gubernur Kabul Zaman Syah, yang memegang ibu kota, menjadi syah pada 20 Mei 1793. Krisis suksesi ini adalah awal proses perpecahan dinasti secara faktual.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — berakhirnya sistem kapu tradisional di Hawaii", "0b10e1d8"], "d": ["Enam bulan setelah wafatnya Kamehameha I, raja baru Liholiho, dengan dukungan ibunya Kaʻahumanu, dengan sengaja melanggar larangan makan terpisah antara laki-laki dan perempuan (ʻaikapu). Tindakan yang disebut 'ʻAi Noa' (makan bebas) ini mengakhiri secara resmi sistem agama-hukum kapu tradisional; kuil-kuil lama (heiau) di kepulauan dirobohkan dalam waktu singkat. Ini adalah patahan keagamaan-politik terbesar sebelum kedatangan misionaris Barat (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["Protokol London — pengakuan kemerdekaan Yunani", "4c7b4b72"], "d": ["Protokol yang ditandatangani Inggris, Prancis, dan Rusia di London melampaui otonomi yang direncanakan Perjanjian Edirne dan mengakui Yunani sebagai negara MERDEKA. Ketentuannya: semenanjung Mora, Attika, dan Eğriboz serta kepulauan Cyclades diserahkan kepada negara baru; perbatasan ditarik di garis Arta-Volos; diputuskan ganti rugi dibayar kepada Negara Utsmaniyah; bentuk pemerintahan negara ditetapkan sebagai 'monarki merdeka'. Ini adalah negara merdeka PERTAMA yang lepas dari kekaisaran dan membentuk contoh hukum kemerdekaan-kemerdekaan Balkan berikutnya. Kepulauan Cyclades (Naxos, İstendil, Santorini, Paros, Değirmenlik, Syros, Mykonos, dll.) termasuk dalam Yunani yang kemerdekaannya diakui dengan Protokol London.", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdullah b. Rashid merebut emirat Ha'il — berdirinya dinasti Shammar (Rashidi)", "fb513b8a"], "d": ["Dengan jatuhnya Dir'iyah oleh pasukan Mehmed Ali Paşa pada 1818, wilayah Jabal Shammar keluar dari kekuasaan Saudi dan keamiran tetap di tangan keluarga Ibn Ali. Abdullah b. Rashid, yang mendukung dibangunnya kembali kekuasaan Utsmaniyah, memenangkan perjuangan yang dilakukannya bersama saudaranya Ubeyd melawan keluarga Ibn Ali pada 1835, merebut emirat Ha'il dan mendirikan kekuasaan dinasti Rashidi.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Konstitusi tertulis pertama Hawaii diumumkan", "401a8a1d"], "d": ["Konstitusi tertulis lengkap pertama kerajaan diumumkan; dokumen yang membatasi wewenang raja dan membentuk majelis perwakilan ini mengubah Hawaii menjadi monarki konstitusional.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["Konstitusi Bayonet — wewenang Raja Kalākaua dipangkas", "4953363b"], "d": ["Sebuah kelompok milisi bersenjata mengancam Raja Kalākaua dan memaksanya menandatangani konstitusi baru yang sangat memangkas wewenang kerajaan; dokumen itu dikenal sebagai 'Konstitusi Bayonet' (Bayonet Constitution) dan secara faktual menempatkan takhta di bawah kendali elite pemukim kulit putih.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["Wafatnya George Tupou I, naik takhtanya George Tupou II (Tonga)", "b56e2b32"], "d": ["Dengan wafatnya raja pendiri George Tupou I, cicitnya George Tupou II naik takhta; upacara penobatan diadakan pada 17 Maret 1893 di Nukuʻalofa.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["Selandia Baru menjadi negara pemerintahan sendiri pertama yang memberi perempuan hak pilih", "0d277cde"], "d": ["Dengan Undang-Undang Pemilu baru yang ditandatangani Gubernur Lord Glasgow, Selandia Baru menjadi negara pemerintahan sendiri pertama di dunia yang memberi perempuan hak pilih dalam pemilihan parlemen.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Republik Hawaii diproklamasikan", "4346bd5d"], "d": ["Para konspirator yang menggulingkan Ratu Liliʻuokalani pada 1893 mengubah pemerintahan sementara menjadi republik resmi; Sanford Dole dinyatakan presiden. Rezim peralihan ini berlangsung hingga aneksasi AS pada 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["Perbatasan Selandia Baru diperluas mencakup Kepulauan Cook dan Niue", "d0370a33"], "d": ["Perbatasan Selandia Baru diperluas mencakup Kepulauan Cook (Rarotonga, Aitutaki, dan pulau-pulau selatan serta Kepulauan Cook utara) dan Niue; pulau-pulau ini menjadi wilayah yang terikat pada Selandia Baru.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["Wafatnya George Tupou II, naik takhtanya Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II wafat karena tuberkulosis; putrinya yang berusia 18 tahun, Sālote, dinyatakan ratu keesokan harinya dan upacara penobatan diadakan pada 11 Oktober 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["Republik Rakyat Khorezm diproklamasikan", "0a6b79f9"], "d": ["Setelah Revolusi Oktober 1917 dan digulingkannya Khan Khiva, Republik Rakyat Khorezm diproklamasikan.", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["Perjanjian Sèvres — teks pembagian kekaisaran", "64980d7b"], "d": ["Teks yang ditandatangani pemerintah Utsmaniyah dengan negara-negara Entente dan secara faktual melikuidasi kekaisaran. Ketentuannya: Thrakia Timur dan wilayah İzmir kepada Yunani; Armenia merdeka dan Kurdistan otonom direncanakan di Anatolia Timur; Suriah diserahkan kepada Prancis, Irak dan Palestina kepada Inggris sebagai mandat; Selat diserahkan kepada komisi internasional; pasukan diturunkan menjadi 50.700 orang, kapitulasi kembali, keuangan ditempatkan di bawah pengawasan Entente. Majelis Agung Nasional di Ankara SAMA SEKALI TIDAK MENGAKUI perjanjian itu dan menyatakan para penandatangannya pengkhianat tanah air; teks tidak berlaku, digantikan pada 1923 oleh Lausanne. Itulah sebabnya ia tidak memiliki padanan di peta — Sèvres secara hukum tidak pernah diterapkan.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["Tentara Merah memasuki kota Bukhara — emir terakhir Alim Khan disingkirkan dari takhta", "f8f5bfcf"], "d": ["Tentara Merah memasuki kota Bukhara pada 2 September 1920 dan emir Mangit terakhir Alim Khan disingkirkan dari takhta. Emir mundur ke timur negeri, ke Dushanbe, dan selama setengah tahun memimpin perjuangan melawan Soviet dari sana; Tentara Merah merebut Dushanbe pada 21 Februari 1921 dan emir melarikan diri lebih jauh ke timur dan dari sana ke Afghanistan. Emirat secara resmi dihapus pada 6 Oktober 1920 (lihat Republik Rakyat Soviet Bukhara).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["Republik Rakyat Soviet Bukhara diproklamasikan", "ef579627"], "d": ["Setelah Tentara Merah menghancurkan Emirat Bukhara pada 28-31 Agustus 1920 dan membuat Emir Alim Khan melarikan diri ke Bukhara Timur, Republik Rakyat Soviet Bukhara diproklamasikan di bawah pimpinan Faizullah Khojaev.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["Republik Rakyat Tannu Tuva menyatakan kemerdekaannya", "8710ea3d"], "d": ["Kemerdekaan dinyatakan di bawah pimpinan Partai Revolusioner Rakyat Tuva; pasal pertama konstitusi pertama menyatakan bahwa negara bertindak 'dalam hubungan internasional di bawah perlindungan Rusia Soviet'. Dengan peristiwa ini Kyzyl (Belotsarsk, Tannu-Tuva) beralih ke Republik Rakyat Tannu-Tuva.", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["Konstitusi baru Republik Rakyat Soviet Bukhara diterima", "fb17bf39"], "d": ["Konstitusi baru yang, berbeda dari konstitusi Rusia 1918, mengizinkan kepemilikan pribadi atas tanah/produksi dan memberi hak pilih juga kepada non-proletar diterima (kecuali kerabat emir yang digulingkan dan tuan tanah besar).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["Perubahan menjadi Republik Sosialis Soviet Khorezm", "14a1d26f"], "d": ["Negeri mengubah nama dan statusnya menjadi Republik Sosialis Soviet Khorezm; struktur administratif-hukum ditata ulang menurut sistem Soviet.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["Pemerintah Tannu Tuva mulai bertugas secara faktual", "22ea1516"], "d": ["Pemerintah yang dibentuk setelah pertemuan partai pertama pada Februari 1922 mulai bertugas secara faktual.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["Khural Agung pertama Tannu Tuva berkumpul", "80fe15f2"], "d": ["Khural Agung (Majelis Rakyat) pertama negeri itu berkumpul; ini adalah pertemuan perwakilan besar pertama dalam proses pelembagaan negara.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["Berakhirnya RSS Khorezm dan Republik Rakyat Soviet Bukhara dengan pembatasan nasional — berdirinya RSS Uzbekistan/Turkmenistan", "e8c8ab4f"], "d": ["Dengan keputusan 'pembatasan nasional' (natsionalno-territorialnoe razmezhevanie) Soviet, Republik Sosialis Soviet Khorezm dan Republik Rakyat Soviet Bukhara dihapus; wilayah mereka dibagi antara Republik Sosialis Soviet Uzbekistan dan Turkmenistan yang baru dibentuk (timur Khiva ke Uzbekistan, barat ke Turkmenistan). Entri `harizm` TDV: 'Pada 1924 bagian timur Khanat Khiva diserahkan kepada Republik Sosialis Soviet Uzbekistan dan bagian barat kepada Republik Sosialis Soviet Turkmenistan.' — hanya memberi tahun.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Dijualnya Alaiye kepada Sultan Mamluk Barsbay", "c8bd35f2"], "d": ["Alaiye, yang direbut Karamanoğlu Mecdüddin Mahmud Bey pada 1293, telah menjadi beylik tersendiri yang dikelola salah satu cabang Karamanoğulları; Ibnu Battuta pada 1333 mencatat bahwa pemerintahan berada di tangan Karamanoğlu Yusuf Bey. Karaman b. Savcı Bey pada 1427 menjual kota itu kepada Sultan Mamluk Barsbay seharga lima ribu keping emas, dan Alaiye masuk pemerintahan Mamluk. Pelabuhan kunci Mediterania ini pun menjadi penghalang dalam tangan Mamluk di jalur Utsmani menuju selatan; pada 1471 ketika Gedik Ahmed Pasya mengepung, bey terakhir Kılıcarslan menyerahkan kota.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Direbutnya Tabarka dari Genoa — berakhirnya imtiyaz karang Lomellini", "b1f33eb5"], "d": ["Setelah perjanjian Charles V dengan bey Tunis pada 1544, keluarga Lomellini dari Genoa menetap di Pulau Tabarka dan memegang imtiyaz karang selama dua ratus tahun; pulau tetap menjadi pos dagang Kristen di tengah Tunisia Utsmaniyah. Ali Paşa dari dinasti Husainiyah, ketika mengetahui upaya keluarga itu melepaskan pulau, mengirim pasukan dan merebut pulau pada 12 Juni 1741; sekitar seribu lima ratus orang Kristen dipindahkan ke Tunisia. Tabarka sejak tanggal ini masuk ke pemerintahan ocak Tunisia.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Pertempuran Piramida dan direbutnya Kairo oleh Prancis", "3ddd6b96"], "d": ["Napoleon berbaris dari Iskandariyah menyusuri Nil ke selatan dan pada 21 Juli 1798 menghadapi kavaleri Mamluk Murad Bey di Imbaba, di seberang Giza. Infanteri Prancis dalam formasi bujur sangkar mematahkan serangan kavaleri; tentara Mamluk bubar dan Kairo menyerah tanpa perlawanan dua hari kemudian. Murad Bey mundur ke Mesir Hulu dan Ibrahim Bey ke Suriah. Prancis mendirikan diwan di Kairo dan berusaha memerintah melalui para ulama; dua pemberontakan besar di Kairo pecah pada Oktober 1798 dan Maret 1800.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Pengepungan Akka oleh Napoleon — dihentikannya ekspedisi Suriah", "d2a947ad"], "d": ["Napoleon, yang ingin membubarkan pasukan yang disiapkan Utsmani untuk merebut kembali Mesir, berbaris ke Suriah pada awal 1799; ia merebut Arish pada 18 Februari, Jaffa pada Maret, dan mengepung Akka pada 18 Maret 1799. Pertahanan Cezzar Ahmed Pasya dan dukungan laksamana Inggris Sidney Smith dari laut mematahkan pengepungan selama dua bulan; karena meriam kepungan direbut di laut, tembok tidak dapat ditembus. Napoleon mundur pada Mei dan kekalahan ini menjadi titik terjauh pendudukan Prancis.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Berdirinya negara Emir Abdulkadir — pemusatan perlawanan di Aljazair barat", "9e482383"], "d": ["Perlawanan yang tercerai-berai setelah jatuhnya Aljazair berhimpun di sekitar Abdulkadir muda, putra syekh Qadiri Muhyiddin; pada 22 November 1832 di dekat Mascara para kepala suku memberikan baiat kepadanya dengan gelar 'amirul mukminin'. Bangunan yang ia dirikan bukan sekadar persekutuan suku melainkan negara yang tertata: ia memiliki percetakan uang, pabrik mesiu, sistem pajak, dan ibu kota di Tagdempt. Prancis secara resmi mengakui kekuasaannya lewat Perjanjian Tafna 1837. Abdulkadir tidak bernaung di bawah Utsmaniyah melainkan di bawah kedaulatan sultan Maroko Abdurrahman; artinya wilayah ini setelah 1832 bukan lagi bagian dari tabiiyah Utsmani. Ia menyerah pada 23 Desember 1847, dan Kesultanan Utsmani pada tahun yang sama menyatakan hak-haknya atas Aljazair telah berakhir.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Jatuhnya Konstantin — berakhirnya beylik Aljazair timur", "159fed36"], "d": ["Setelah Aljazair jatuh pada 1830, beylerbeylik timur tidak bubar: bey terakhir, Ahmed, melanjutkan pemerintahannya di Konstantin dan menyatakan bertindak atas nama Utsmaniyah. Ekspedisi pertama Prancis pada 1836 berakhir dengan kekalahan; ekspedisi kedua mengepung kota pada 6 Oktober 1837, komandan Damrémont tewas terkena tembakan meriam pada 12 Oktober, dan pada 13 Oktober tembok ditembus lalu kota direbut dari jalan ke jalan. Ahmed Bey mundur ke pegunungan dan baru menyerah pada 1848. Tanggal ini adalah berakhirnya secara de facto pemerintahan Utsmani-Turki selama tiga abad di Aljazair timur.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Penaklukan wilayah Taka dan pendirian Kassala", "cc3e0631"], "d": ["Penguasa Sudan Ahmed Pasya Abu Widan pada 1840 menyatukan wilayah Taka antara sungai Atbara dan Gash ke dalam pemerintahan Mesir dan mendirikan kota Kassala sebagai markas militer. Kota itu menjadi pusat mudiriyah yang mengawasi jalur kafilah antara Sennar dan Suakin serta zona perbatasan Habsyi.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["Pendudukan Prancis atas Mascara — hilangnya ibu kota Abdelkader", "bd363c05"], "d": ["Dengan datangnya Bugeaud ke jabatan gubernur pada 1841, strategi Prancis berubah: alih-alih bertahan di pesisir, menduduki kota-kota pedalaman satu per satu. Kolom-kolom bergerak yang berangkat dari Oran, Mostaganem, dan Medea merebut pusat-pusat negara teratur Abdelkader; Mascara, ibu kota sejati dengan percetakan uang, pabrik mesiu, dan lumbung gandumnya, adalah yang terpenting di antaranya. Emir sesudahnya melepaskan mendirikan pusat tetap dan mengubah pasukannya menjadi perkemahan nomaden yang disebut 'smala'.", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Pendudukan lembah Chelif dan Ténès — didirikannya Orléansville", "e1eeeb68"], "d": ["Untuk dapat mengejar Abdelkader, Prancis pada April 1843 mendirikan kota baru bernama Orléansville di tengah lembah Chelif; pada tahun yang sama pelabuhan Ténès di pesisir juga diduduki. Dengan demikian koridor pedalaman antara Aljir dan Oran masuk ke kendali Prancis dan perlawanan di Pegunungan Dahra terkepung. Pada 16 Mei tahun yang sama perkemahan nomaden Abdelkader 'smala' ditemukan secara kebetulan dan dicerai-beraikan.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Pendirian kamp berbenteng Sidi Bel Abbès", "fb33ec29"], "d": ["Bugeaud pada 12 Juni 1843 memberi perintah kepada Jenderal Bedeau untuk mendirikan kamp berbenteng dengan parit dan tembok di Sidi Bel Abbès; pembangunan dimulai pada 18 Juni dan pada November tahun yang sama satu batalion Legiun Asing menetap di sini. Kamp itu menjadi pangkalan permanen yang mengendalikan dataran pedalaman antara Oran dan Tlemcen.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["Beralihnya Nedroma dan jalur perbatasan Maroko ke kendali Prancis", "61d821f3"], "d": ["Setelah mundurnya Abdelkader ke Maroko pada 1843, Nedroma di barat laut Tlemcen dan pesisir Traras masuk ke kendali Prancis. Pertempuran Isly 14 Agustus 1844 mengalahkan pasukan Maroko dan perbatasan antara kedua negara ditarik dengan Konvensi Lalla Maghnia 18 Maret 1845; Nedroma tetap di sisi Aljazair garis ini.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Jatuhnya Laghouat — terbukanya gerbang Sahara", "b161b32c"], "d": ["Jenderal Pélissier mengepung Laghouat pada 21 November 1852 dengan pasukan enam ribu orang dan pada 4 Desember kota jatuh dengan serbuan berdarah. Laghouat adalah kota oasis yang menguasai lintasan antara Tell dan Sahara; jatuhnya membuka kemajuan Prancis ke jalur kafilah gurun dan menyiapkan dikenakannya pajak pada konfederasi Mzab dalam satu tahun.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Pencaplokan wilayah Bogos (Keren) oleh Mesir", "b2ab83ce"], "d": ["Werner Munzinger Pasya, gubernur provinsi 'Sudan Timur dan Pesisir Laut Merah' yang didirikan Khedive Ismail di pantai barat Laut Merah, pada 1872 menyatukan wilayah Bogos yang dihuni bangsa Bilen beserta pusatnya, Keren, ke dalam Mesir. Ini merupakan kemajuan Mesir yang paling langgeng di tepi dataran tinggi Habsyi dan memulai sengketa perbatasan dua belas tahun dengan Habsyi.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Aneksasi Kesultanan Darfur ke Mesir — Zübeyr Paşa memasuki El-Fasher", "f41268ed"], "d": ["Zübeyr Rahmet Paşa, yang menjadi kuat berkat perdagangan gading dan budak, membubarkan pasukan Fur di Manawashi pada 25 Oktober 1874 dengan pasukan yang diperlengkapi senapan Remington; Sultan İbrâhim tewas dalam pertempuran. Zübeyr memasuki El-Fasher tanpa pertempuran pada 2 November dan pemerintahan dinasti Keira yang berlangsung sejak 1603 berakhir secara faktual. Darfur dengan demikian digabungkan ke provinsi-provinsi Sudan Mesir Kavalalı; namun perlawanan keluarga Keira di pegunungan berlanjut hingga 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Aneksasi oasis Mzab (Ghardaïa)", "9372959f"], "d": ["Kota-kota Ibadi Mzab pada 1852 menerima membayar pajak kepada Prancis tetapi mempertahankan pemerintahan dalam negerinya; tiga puluh tahun kemudian, pada 1882, wilayah itu dianeksasi langsung ke tanah Prancis dan Ghardaïa diikat ke pemerintahan militer. Dengan demikian sabuk otonom terakhir Sahara utara juga berakhir secara hukum.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Pengeboman Iskandariyah dan pendaratan Inggris", "18d57bf8"], "d": ["Ketika gerakan perwira di bawah pimpinan Urabi Pasya menguasai khedive, Inggris campur tangan dengan dalih keamanan jalur Suez. Armada Laksamana Seymour membombardir benteng pantai Iskandariyah pada 11-12 Juli 1882; setelah kebakaran dan penjarahan di kota, pasukan Inggris mendarat pada 15 Juli. Kesultanan Utsmani tidak mampu mencegah operasi ini di salah satu provinsinya yang secara hukum berada di bawah kedaulatannya, dan juga tidak menjawab ajakan untuk ikut serta dalam intervensi. Dengan demikian langkah pertama pendudukan yang akan berlangsung tiga puluh dua tahun telah diambil.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Pertempuran Tel el-Kebir — bubarnya tentara Urabi", "8e38fecf"], "d": ["Wolseley mendaratkan pasukannya di Ismailiyah melalui Terusan Suez lalu berbaris menembus gurun, dan menyerbu parit-parit Mesir di Tel el-Kebir saat fajar 13 September 1882; pertempuran selesai dalam satu jam. Urabi menyerah keesokan harinya dan kavaleri Inggris memasuki Kairo pada hari yang sama. Sejak tanggal ini urusan keuangan, militer, dan luar negeri Mesir secara de facto berada di bawah pengawasan Inggris; kedaulatan Utsmani secara hukum berlanjut hingga 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Konvensi Marsa (La Marsa) — rampungnya protektorat Tunisia", "71338640"], "d": ["Perjanjian Bardo (Qasr as-Said) 12 Mei 1881 menyerahkan urusan luar negeri Tunisia kepada Prancis tetapi membiarkan pemerintahan dalam negeri di tangan bey; dua tahun kemudian Konvensi Marsa yang ditandatangani 8 Juni 1883 menyerahkan pula reformasi keuangan dan administrasi di bawah pengawasan Prancis dan menuntaskan protektorat. Kesultanan Utsmani tetap mempertahankan klaim kedaulatannya atas Tunisia dan tidak pernah mengakui pendudukan itu, tetapi tidak mampu mengambil langkah balasan nyata. Dengan demikian Tunisia, ocak Utsmani sejak 1574, resmi masuk protektorat Prancis.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Bencana Shaykan — musnahnya pasukan Hicks Pasya", "a0e08986"], "d": ["Hicks Pasya, perwira Inggris pensiunan yang memimpin pasukan Mesir sekitar sepuluh ribu orang yang dikirim dari Kairo, maju tanpa air dan tanpa pemandu di gurun Kordofan lalu dikepung pasukan Mahdi di Shaykan pada 5 November 1883, dan tentara itu nyaris seluruhnya dibinasakan. Kekalahan ini mematahkan tulang punggung pemerintahan Mesir di Sudan: dalam sebulan Darfur dan Bahr el-Ghazal menyerah, dan seluruh Kordofan jatuh ke tangan Mahdi. Jalan menuju jatuhnya Khartoum bermula dari sini.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Beralihnya Darfur ke pasukan Mahdi — penyerahan Slatin Paşa", "6d8992d4"], "d": ["Gubernur jenderal Darfur Slatin Paşa sejak 1882 menghadapi pemberontakan Mahdist suku Rizeigat; menganggap kekalahan prajuritnya diakibatkan keKristenannya, ia secara terbuka menjadi Muslim pada 1883 dan mengambil nama Abdülkādir. Setelah musnahnya pasukan Hicks Paşa di Kordofan pada November 1883, perlawanan kehilangan artinya dan ia menyerah kepada Emir Madibbo pada 23 Desember 1883. Pos-pos kecil Mesir di Darfur juga dalam waktu singkat mengikuti jalan yang sama; pemerintahan Turki-Mesir sepuluh tahun berakhir. Dengan peristiwa ini Jabal Marra (Darfur) beralih ke pemerintahan Negara Mahdi.", "bd700253"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Beralihnya Zeila dan pantai Somali ke pemerintahan Inggris", "1d649502"], "d": ["Ketika pemberontakan Mahdi meruntuhkan garnisun Mesir di Sudan dan Laut Merah, Kairo terpaksa mengosongkan pos-pos terpencilnya di pantai Habsyi. Pemerintahan Inggris di Aden mendaratkan pasukan di Zeila dan Berbera pada 1884; tahun berikutnya perjanjian perlindungan ditandatangani dengan para kepala suku Somali dan Somaliland Britania didirikan. Zeila, yang sejak 1559 terikat pada eyalet Habsyi, pun lepas.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Penyerahan garnisun Fasher kepada Mahdist", "68f0760d"], "d": ["Setelah penyerahan Slatin pada 23 Desember 1883, garnisun Mesir di Benteng Fasher masih melawan. Garnisun yang kehilangan sumur dalam pengepungan tujuh hari menyerah pada 15 Januari 1884; senjata diletakkan dan benteng jatuh ke tangan Mahdist.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Perjanjian Hewett (Adwa) — penyerahan Bogos kepada Habsyi", "0de1b701"], "d": ["Ketika pemberontakan Mahdi mengepung garnisun-garnisun Mesir di Sudan, Inggris menandatangani perjanjian dengan Yohannes IV di Adwa pada 3 Juni 1884 untuk memperoleh bantuan Habsyi. Pasal kedua perjanjian itu mengembalikan Bogos kepada Habsyi, dengan imbalan Habsyi membantu evakuasi garnisun yang terkepung melalui Massawa. Dengan demikian Keren keluar dari pemerintahan Mesir selama dua belas tahun; lima tahun kemudian wilayah itu akan dimasukkan ke Eritrea Italia.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Direbutnya kembali Dongola — dimulainya ekspedisi menyusuri Nil", "f63aa14f"], "d": ["Setelah Italia dikalahkan di Adwa, Inggris menggerakkan tentara Mesir ke selatan menyusuri Nil di bawah komando Kitchener. Seiring jalur kereta api maju di gurun, masalah logistik teratasi dan provinsi Dongola direbut kembali pada 23 September 1896. Pemerintahan Mahdi sebelas tahun berakhir di sini; ekspedisi akan berlanjut dua tahun lagi hingga Omdurman.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Pertempuran Omdurman — runtuhnya negara Mahdi", "28dff7b2"], "d": ["Tentara Inggris-Mesir pimpinan Kitchener, yang dilengkapi artileri dan senapan mesin, pada 2 September 1898 menghancurkan pasukan Khalifah Abdullah et-Taaisyi di depan Omdurman dalam beberapa jam. Keesokan harinya Khartoum dimasuki dan bendera dikibarkan di istana tempat Gordon dibunuh tiga belas tahun sebelumnya. Ibu kota negara Mahdi jatuh; Khalifah tewas dalam operasi pengejaran pada akhir 1899. Pergantian kekuasaan secara de facto terjadi pada tanggal ini — sedangkan 19 Januari 1899 adalah perjanjian yang membangun kerangka hukum pemerintahan. Dengan kekalahan negara Mahdi ini, Darfur (El-Fasher, Nyala, Geneina, Kutum, dll.) beralih ke Kesultanan Darfur yang didirikan kembali oleh Ali Dinar.", "ad27827a"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["Perjanjian Kondominium — pemerintahan bersama Inggris-Mesir atas Sudan", "8033c688"], "d": ["Perjanjian yang ditandatangani di Kairo empat bulan setelah Omdurman menempatkan Sudan di bawah pemerintahan bersama kedua negara dengan nama 'Sudan Anglo-Mesir': dua bendera akan dikibarkan bersama, dan gubernur jenderal diangkat oleh khedive dengan persetujuan Inggris. Dalam praktik pemerintahan sepenuhnya di tangan Inggris. Kesultanan Utsmani tidak menjadi pihak dan tidak mengakui perjanjian itu dengan alasan hak atas Sudan melalui Mesir adalah miliknya; tetapi secara de facto ia tersisih. Dengan perjanjian ini wilayah Sudan di selatan paralel ke-22 (Dongola, Khartoum, Sennar, Kordofan, pesisir Suakin, dll.) beralih ke pemerintahan bersama Inggris-Mesir (Sudan Anglo-Mesir).", "097331bb"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Pendaratan Italia di Tobruk — pendudukan pertama di Tripolitania", "44780018"], "d": ["Italia menyatakan perang pada 29 September 1911 dan armadanya memblokade pantai pada 25-26 September. Operasi darat pertama dilakukan di Tobruk pada 8 Oktober: garnisun kecil Utsmani mundur ke pedalaman dan pelabuhan diduduki tanpa pertempuran. Tobruk adalah pelabuhan Utsmani yang paling dekat dengan perbatasan Mesir; jatuhnya membuka sayap timur Barqa dan memudahkan pasukan Italia berbaris ke barat menyusuri pantai.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Menyerahnya kota Tripoli kepada Italia", "785091ad"], "d": ["Tripoli menyerah pada 9 Oktober 1911 setelah dibombardir tiga hari. Pasukan Utsmani memilih mundur ke Aziziya dan Gharyan untuk mengorganisasi perlawanan di pedalaman alih-alih mempertahankan kota; perlawanan yang diikuti Enver dan Mustafa Kemal Bey ini mengurung Italia di jalur pantai hingga akhir perang. Jadi, meskipun kota jatuh, pedalaman provinsi tetap berada di bawah kendali Utsmani.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Lepasnya Derna akibat pendaratan Italia", "f014c741"], "d": ["Setelah Tobruk, giliran Derna, pelabuhan kedua Barqa; kota itu diduduki pada 16 Oktober 1911. Dataran tinggi di sekitar Derna adalah kawasan dengan kepadatan tarekat Sanusiyah tertinggi, dan para mujahid yang berhimpun atas seruan jihad Syekh Ahmed Syarif menahan Italia terkepung di sekitar pelabuhan. Pendudukan tetap terbatas pada kota dan tidak pernah meluas ke pedalaman.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Pendaratan Italia di Benghazi — hilangnya pusat sancak Barqa", "f9183c40"], "d": ["Benghazi, pusat Barqa, diduduki pada 21 Oktober 1911 lewat pendaratan keempat dan terpenting di pantai. Dengan demikian, tiga pekan setelah pernyataan perang, Italia menguasai semua pelabuhan besar provinsi Tripolitania (Tripoli, Tobruk, Derna, Benghazi), tetapi tidak berhasil memasuki pedalaman dari satu pun. Sisa satu tahun perang berlalu dengan serangan-serangan tanpa hasil dari keempat titik pantai itu ke arah dalam.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Dekret aneksasi sepihak Italia", "cfe3f9c2"], "d": ["Saat perang masih berlangsung, Italia pada 5 November 1911 mengeluarkan dekret yang menyatakan telah mencaplok Tripolitania dan Barqa. Kesultanan Utsmani tidak mengakuinya dan perang berlanjut setahun lagi; aneksasi baru memperoleh keabsahan hukum melalui Perjanjian Ouchy 18 Oktober 1912. Karena itu dekret ini tidak mengubah warna Utsmani di peta — kepemilikan hukum tetap pada Utsmani hingga 1912, dan kendali Italia ditampilkan sebagai pendudukan yang diarsir.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Direbutnya Köprühisar dan persiapan pendirian Yenişehir", "39abff03"], "d": ["Dengan jatuhnya benteng-benteng lintasan antara Bursa dan İznik, diletakkan dasar markas depan yang akan mengepung kedua kota.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Pendirian Yenişehir", "d3275837"], "d": ["Permukiman garnisun Utsmaniyah reguler pertama didirikan untuk mengelola pengepungan Bursa dan İznik; Orhan Gazi lahir di sini.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Pengepungan pertama İznik dan penaklukan Marmaracık", "cdca2349"], "d": ["İznik untuk pertama kalinya dikepung tetapi tidak dapat direbut (penaklukan definitif 1331); benteng Marmaracık di dekatnya direbut pada saat itu.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Ekspedisi pasukan Katalan ke Anatolia", "4fd940d5"], "d": ["Kompi Katalan yang disewa Bizantium untuk menghentikan kemajuan Turki meraih keberhasilan sementara tetapi tidak bertahan; dengan penarikan mereka, kemajuan beylik-beylik uç dipercepat.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal masuk Islam dan bergabung dengan Utsmaniyah", "ca0d86e1"], "d": ["Köse Mihal, tekfur Harmankaya, memeluk Islam dan bergabung dengan Osman Gazi bersama bentengnya dan anak buahnya; ia menjadi komandan Utsmaniyah asal Bizantium yang pertama.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey mengambil alih pemerintahan secara de facto", "6dadbefc"], "d": ["Karena usia lanjut dan sakitnya Osman Gazi, komando dan pengelolaan de facto pengepungan Bursa dan ekspedisi-ekspedisi beralih kepada putranya Orhan Bey (naik takhta secara resmi pada 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Direbutnya Mudanya", "0a623368"], "d": ["Mudanya, pelabuhan Bursa, direbut sehingga hubungan kota dengan laut terputus; pengepungan Bursa memasuki tahap pencekikan.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Penaklukan Akyazı dan Pulau İmralı", "d041b0c8"], "d": ["Akyazı di utara Sakarya direbut; dengan direbutnya Pulau İmralı, Utsmaniyah untuk pertama kalinya bertetangga dengan Pulau Marmara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Penaklukan Gemlik (Kios) dan Armutlu", "682d3bac"], "d": ["Hubungan laut terakhir Bursa pun diputus sehingga kota itu disiapkan untuk menyerah pada 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca merebut Kandıra dan sekitarnya", "341bb97e"], "d": ["Akça Koca, salah satu uç beyi Orhan Gazi, ketika menyerbu wilayah İzmit dari markasnya di barat Danau Sapanca, merebut Kandıra dan sekitarnya menjelang 1326. İzmit masih di tangan Bizantium; kota itu baru akan jatuh pada 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Bergabungnya Yalova dan Karamürsel", "133cb07a"], "d": ["Yalova dan sekitarnya di pesisir selatan Teluk İzmit jatuh ke tangan Turki pada tahun ini; jalur pesisir diberikan oleh Orhan Bey kepada Karamürsel Gazi sebagai timar.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca merebut Aydos dan benteng Samandıra", "ce4daa8a"], "d": ["Setelah direbutnya Kandıra, Akça Koca bersama Konuralp dan Gazi Abdurrahman merebut benteng Aydos di sekitar Kartal, lalu benteng Samandıra di utaranya; wilayah Samandıra diberikan kepadanya sebagai milik. Akça Koca wafat di dekat Kandıra pada 1328; wilayah uç beylik itu diberikan kepada Şehzade Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Aliansi Utsmaniyah-Aydın-Saruhan", "9df6bb74"], "d": ["Tiga beylik bergerak bersama melawan Bizantium; armada Umur Bey dari Aydınoğulları melelahkan Bizantium di front kedua dengan serbuannya ke pesisir Thrakia.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Pernikahan Orhan Gazi – Theodora: aliansi Bizantium", "9b67a590"], "d": ["Orhan Gazi, yang mendukung Kantakouzenos dalam perebutan takhta Bizantium, menikahi putrinya Theodora; aliansi ini memungkinkan pasukan Utsmaniyah mengenal Rumelia dari dekat.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Direbutnya Ankara", "49bf1f6d"], "d": ["Ankara, yang diperintah para ahi, masuk ke pemerintahan Utsmaniyah; jalan Anatolia Tengah terbuka. Tempat-tempat lain yang bergabung pada tanggal yang sama: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Kemajuan di Thrakia pada masa Süleyman Paşa: Malkara, İpsala, dan Tekirdağ", "fb31cf02"], "d": ["Setelah kepala jembatan di Gelibolu didirikan, Süleyman Paşa maju ke utara dari semenanjung dan merebut dataran antara pesisir Marmara dan muara Maritsa selangkah demi selangkah. Malkara, İpsala, dan Rodosçuk (Tekirdağ) dengan demikian membentuk koridor tak terputus yang menghubungkan Gelibolu dan lembah Maritsa. Tanpa koridor ini tidak mungkin berbaris ke Edirne; kemajuan yang terhenti dengan wafatnya sang şehzade secara mendadak pada 1357 akan dilanjutkan oleh Lala Şahin dan Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Penculikan Şehzade Halil", "b52ac3d7"], "d": ["Halil, putra bungsu Orhan Gazi, diculik oleh bajak laut Foça; krisis tebusan menyibukkan hubungan Utsmaniyah-Bizantium selama bertahun-tahun.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Terputusnya jalur bantuan Edirne: benteng Çorlu, Lüleburgaz, Babaeski, dan Keşan", "8e8ad485"], "d": ["Şehzade Murad, yang kembali memulai operasi penaklukan setelah Halil diselamatkan, mengirim para akıncı hingga depan Istanbul untuk mengisolasi Edirne dari bantuan luar. Benteng Çorlu, Lüleburgaz, dan Babaeski di jalan Istanbul-Edirne serta Keşan di persimpangan jalan Thrakia Selatan direbut. Penyerahan Edirne datang setelah lingkaran pengepungan ini lengkap.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Direbutnya Dimetoka — terbukanya lembah Maritsa", "b59aee83"], "d": ["Dimetoka, benteng kunci lembah Maritsa, direbut; jalan menuju penaklukan Edirne pun terbuka. Berbaris ke Edirne tidak mungkin sebelum koridor yang membentang ke utara dari Gelibolu selesai; karena itu benteng ini dalam urutan penaklukan Rumelia mendahului Edirne. Kota itu untuk sementara menjadi markas Rumelia para sultan. Pasukan yang merebut Dimetoka kemudian, bersama benteng-benteng kecil seperti Kuleli Burgaz (Pythion), menguasai seluruh kawasan Maritsa Tengah.", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Hilangnya Gelibolu (Perang Salib Savoia)", "00e7e415"], "d": ["Armada Amadeus dari Savoia, sepupu kaisar Bizantium, merebut Gelibolu dan menyerahkannya kepada Bizantium; kepala jembatan Utsmaniyah di Rumelia dikelola dari seberang selat selama sepuluh tahun. Permukiman lain yang lepas pada tanggal yang sama: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Pertempuran Çirmen — kendali lembah Maritsa", "cd738d8d"], "d": ["Pasukan para bey Serbia dicerai-beraikan dalam serangan malam; para bey lokal Serbia/Bulgaria di Makedonia dan Rodopi satu per satu mulai membayar upeti kepada Utsmaniyah — bukan penaklukan langsung, melainkan awal gelombang vasalisasi. Dalam riwayat Utsmaniyah, pertempuran ini juga diceritakan dengan nama «Sırpsındığı» dan tahun 1364, sebagai serangan malam Hacı İlbey terhadap pasukan Salib yang datang merebut kembali Edirne; TDV menyatakan bahwa tanggal itu keliru dan kedua kisah itu mengenai pertempuran yang sama.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Penaklukan Filibe dan Eski Zağra", "e780c9ae"], "d": ["Filibe (Plovdiv) di hulu lembah Maritsa dan Eski Zağra (Stara Zagora) di utaranya direbut; kekaisaran Bulgaria diikat dengan upeti. Jalur Tatarpazarcığı dan İhtiman antara Filibe dan Sofia tetap di tangan para bey lokal yang menjadi vasal setelah Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bizantium vasal: Yohanes V dalam pasukan Murad I (akibat kemenangan Çirmen 1371)", "13ffe568"], "d": ["Menurut TDV, setelah kemenangan Çirmen (Maritsa) pada 26 September 1371, Kekaisaran Bizantium mengakui kekuasaan Utsmaniyah dan menjadi negara vasal dengan menerima kewajiban membayar upeti dan berdinas dalam pasukan Utsmaniyah. Dengan kewajiban ini Kaisar Yohanes V bergabung dengan pasukan Murad I pada 1373; putranya Andronikos IV, yang ia tinggalkan di Istanbul pada saat itu, memberontak melawan ayahnya bersama Şehzade Savcı Bey di Bursa.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Direbutnya kembali Gelibolu", "5f96c0a5"], "d": ["Andronikos IV, yang memperoleh dukungan Utsmaniyah dalam perebutan takhta Bizantium, sebagai imbalannya mengembalikan Gelibolu; jembatan antara Rumelia dan Anatolia dibangun kembali. Tempat-tempat lain yang bergabung pada tanggal yang sama: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Mas kawin Germiyan: bergabungnya Kütahya", "d6a6fe61"], "d": ["Dalam pernikahan Devletşah Hatun, putri Germiyanoğlu Süleyman Şah, dengan Yıldırım Bayezid, Kütahya, Simav, Tavşanlı, dan Eğrigöz beralih ke Utsmaniyah sebagai mas kawin — contoh klasik ekspansi tanpa perang. Tempat-tempat lain yang bergabung pada tanggal yang sama: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Pembelian wilayah Hamîd: bergabungnya Isparta", "4a1b6047"], "d": ["Hamîdoğlu Hüseyin Bey menjual sebagian beyliknya (Akşehir-Beyşehir-Isparta) kepada Murad I dengan imbalan uang tunai; sisa wilayah Hamid akan dianeksasi oleh Yıldırım pada 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Penaklukan Serez", "d4d28b60"], "d": ["Serez, kunci Makedonia Timur, direbut; Selanik masuk lingkaran pengepungan. Garis Köstendil-Petriç-Nevrokop-Drama antara Sofia dan Serez belum bergabung langsung pada tanggal ini; secara berurutan menjadi vasal antara 1370-an dan 1383, dan di bawah pemerintahan langsung setelah 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Penaklukan Sofia", "96d5f01f"], "d": ["Lintasan barat Pegunungan Balkan dibawa ke bawah kendali; karena Serez sudah dikuasai sejak 1383, wilayah Thrakia-Makedonia pada tanggal ini membentuk satu kesatuan tak terputus.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Penaklukan Niš", "77f5d632"], "d": ["Dengan direbutnya Niš, kunci lembah Morava, despotat Serbia terancam secara langsung.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Penyerahan pertama Selanik", "96010ee9"], "d": ["Setelah blokade panjang, kota itu menyerah (pada 1403 akan dikembalikan kepada Bizantium, dan pada 1430 ditaklukkan secara definitif). Tempat-tempat lain yang bergabung pada tanggal yang sama: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidname Utsmaniyah-Genoa — pembaruan perjanjian 1352", "be11d17a"], "d": ["Dengan para utusan Genoa dari Pera, perjanjian dagang 1352 peninggalan masa Orhan Gazi diperbarui; pajak antara kedua negara, perlakuan terhadap tawanan, dan perdagangan bebas ditetapkan kembali. Ini dianggap ahidname persahabatan dan perdagangan pertama yang diketahui secara resmi antara Utsmaniyah dan Genoa — bukan aliansi militer, melainkan perjanjian yang sepenuhnya bersifat dagang.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Ekspedisi Çandarlı Ali Paşa ke Bulgaria: direbutnya Şumnu dan Rusçuk", "2781c3a9"], "d": ["Benteng-benteng Kekaisaran Bulgaria di sepanjang Danube diambil dalam satu ekspedisi; jangan dikacaukan dengan kekalahan di Bileça di Bosnia pada tahun yang sama — itu adalah keberhasilan serentak di front terpisah. Tırnova dan Vidin masih merupakan pusat Bulgaria terakhir yang bertahan.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Kekalahan Bileća", "89ba0a64"], "d": ["Pasukan akıncı yang bergerak ke Bosnia disergap dan dimusnahkan di Bileća; kemunduran besar pertama di Balkan ini membesarkan hati aliansi yang menuju Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Aneksasi beylik-beylik Anatolia Barat: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Tiga beylik bergabung dalam satu ekspedisi: Manisa, pusat Saruhanoğulları; Aydın, pusat Aydınoğulları (termasuk benteng Atas İzmir, tetapi pelabuhan/benteng bawah masih di tangan Ksatria St. Jean — hingga 1402); Muğla-Milas, pusat Menteşeoğulları, termasuk jalur pesisir Datça-Bodrum-Marmaris-Fethiye. Pesisir Aegea untuk pertama kalinya bersatu di satu tangan. Tempat-tempat lain yang bergabung pada tanggal yang sama: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Aneksasi wilayah Teke: bergabungnya Antalya", "fdbeee5c"], "d": ["Wilayah Teke di pesisir Mediterania bergabung ke wilayah Utsmaniyah. Tekeoğulları adalah cabang yang memisah dari Hamîdoğulları: Feleküddin Dündar Bey menyerahkan Antalya yang ditaklukkannya kepada saudaranya Yûnus Bey, dan sekitar 1321 lahirlah sebuah beylik tersendiri. Karena itu Antalya dan sekitarnya di peta setelah 1321 ditampilkan dengan warna Tekeoğulları, bukan Hamîdoğulları. Beylik ini didirikan kembali setelah Perang Ankara dan baru dilikuidasi secara definitif pada 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Penaklukan Üsküp", "9e5a1af5"], "d": ["Pusat Makedonia Vardar direbut; Üsküp menjadi salah satu pusat uç utama Rumelia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Aneksasi Kastamonu", "876330ba"], "d": ["Cabang Kastamonu dari Candaroğulları dilikuidasi; cabang Sinop berlanjut sebagai vasal. Tempat-tempat lain yang bergabung pada tanggal yang sama: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Jatuhnya Tırnova — aneksasi Bulgaria", "ff666977"], "d": ["Ibu kota kekaisaran Bulgaria jatuh; Bulgaria masuk ke pemerintahan langsung Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Benteng Lofça (Lovech) beralih ke Utsmaniyah", "a55e87a0"], "d": ["Lofça, salah satu benteng Tsar Bulgaria İvan Şişman, bergabung ke wilayah Utsmaniyah bersama provinsi-provinsi Şişman lainnya dalam ekspedisi 1393 ketika Tırnova jatuh. Sumber tidak tegas: penaklukan itu «diperkirakan» terjadi pada tahun ini.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Bergabungnya Dobruja", "478e36f2"], "d": ["Wilayah Dobruja yang membentang hingga delta Danube bergabung. Tempat-tempat lain yang bergabung pada tanggal yang sama: Silistre, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Turunnya ke Thessalia", "8bec60dd"], "d": ["Dataran Thessalia yang berpusat di Yenişehir (Larissa) dibawa ke bawah pemerintahan Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1394-01-01:1":{"b": ["Pengepungan ketat Istanbul dimulai (blokade sejak ~1387)", "0068bc04"], "d": ["Yıldırım Bayezid menahan Istanbul dalam blokade berselang selama sepuluh tahun; kota itu baru selamat berkat mendekatnya Timur.", "504fcb33"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Pertempuran Rovine — ekspedisi Wallachia", "343ae7a9"], "d": ["Setelah pertempuran berdarah dengan voivode Wallachia Mircea yang hasilnya diperdebatkan, Wallachia setuju membayar upeti kepada Utsmaniyah; tatanan vasalase di utara Danube pun terbentuk.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Penaklukan Nikopolis", "b9791717"], "d": ["Setelah Pertempuran Rovine 1395 melawan Wallachia, Yıldırım Bayezid merebut benteng Nikopolis di tepi Danube; sebagian kronik anonim Bulgaria menyatakan penaklukan terjadi pada 3 Juni 1395. Tanggal penaklukan tidak tunggal dalam sumber-sumber: entri Pertempuran Nikopolis dalam TDV İslâm Ansiklopedisi menulis bahwa Bayezid merebut Silistre dan Nikopolis dalam ekspedisi Danube tahun 1394. Benteng itu akan dikepung dalam Perang Salib terkenal 1396, tetapi tidak jatuh. Tempat-tempat lain yang bergabung pada tanggal yang sama: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Benteng Nikopolis beralih ke Utsmaniyah", "327012c9"], "d": ["Setelah serbuan Rovine, Yıldırım Bayezid merebut Nikopolis; Tsar Bulgaria İvan Şişman, yang menetap di sana sebagai vasal Utsmaniyah, disingkirkan. Dalam atlas Nikopolis dicatat beralih dari Kekaisaran Bulgaria ke Utsmaniyah pada hari ini.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Pembangunan Anadolu Hisarı", "aa259b00"], "d": ["Untuk mendukung blokade Istanbul, Güzelcehisar (Anadolu Hisarı) dibangun di sisi Anatolia Selat — langkah permanen pertama kendali atas selat.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Aneksasi Vidin", "ee1ae44b"], "d": ["Setelah kemenangan Nikopolis, kepangeranan Bulgaria terakhir, Vidin, juga dianeksasi.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Aneksasi pertama Karaman", "3cf07876"], "d": ["Dengan kemenangan Akçay, wilayah Karamanoğlu untuk pertama kalinya bergabung dengan Utsmaniyah (akan didirikan kembali pada Masa Fetret).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Bergabungnya pesisir Canik: Samsun", "af9c40fa"], "d": ["Dalam kekosongan yang muncul akibat tertawannya Kadı Burhâneddin oleh Karayülük Osman Bey dari Akkoyunlu, Yıldırım Bayezid lebih dulu mengikat wilayah Canik di pesisir Laut Hitam ke pemerintahan Utsmaniyah. Samsun dan sekitarnya dengan demikian menjadi pelabuhan Laut Hitam pertama bagi dinasti. Garis Sivas-Tokat-Kayseri di pedalaman akan bergabung dua minggu kemudian, dengan terurainya Negara Kadı Burhâneddin secara de facto.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Direbutnya Malatya", "7cb6ae16"], "d": ["Malatya di perbatasan Mamluk direbut — salah satu langkah yang meningkatkan ketegangan dengan Timur.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur merebut Malatya dan menyerahkannya kepada Karayülük Osman — setelah Timur mundur, Dulkadıroğulları merebutnya kembali", "ad2ce7d8"], "d": ["Yıldırım Bayezid, setelah merebut Malatya pada 1399, menyerahkannya kepada Dulkadıroğlu Nasreddin Mehmed dan kembali ke Bursa. Timur, yang memasuki Anatolia pada 1400, merebut lebih dulu Sivas dan Elbistan, lalu Malatya; kota dan sekitarnya dijarah dan pengelolaannya diserahkan kepada Karayülük Osman yang bersama Timur. Setelah Timur meninggalkan wilayah itu, Dulkadıroğulları kembali menguasai Malatya; dengan demikian kekuasaan Utsmaniyah berakhir sebelum Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Süleyman Çelebi – perjanjian dengan Bizantium: pengembalian Selanik", "cc503cc2"], "d": ["Süleyman Çelebi, yang menguasai Rumelia pada masa Fetret, bersepakat dengan Bizantium dan negara-negara Latin dan menyerahkan Selanik serta pesisir Laut Hitam hingga Misivri kepada Bizantium (TDV fetret-devri: Perjanjian Gelibolu, Februari 1403) — di peta İğneada, Rezve, dan Ahtapolu beralih ke Bizantium; di peta Selanik keluar dari Utsmaniyah pada tanggal ini.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Kekalahan laut Gelibolu (Venesia)", "b71d4d68"], "d": ["Armada Venesia mengalahkan armada Utsmaniyah secara telak di depan Gelibolu; peristiwa ini menunjukkan batas-batas pelayaran Utsmaniyah masa awal.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Pemberontakan Düzmece Mustafa", "0ec43138"], "d": ["Mustafa Çelebi, yang mengaku putra Yıldırım, memproklamasikan kesultanan di Rumelia dengan dukungan Bizantium; Murad II menumpas pemberontakan itu pada 1422 dan mengeksekusi saingannya.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Pengepungan Istanbul oleh Murad II", "4b9d9fba"], "d": ["Sebagai balasan atas dukungan Bizantium kepada Düzmece Mustafa, Murad II mengepung Istanbul; pengepungan dicabut ketika saudaranya Küçük Mustafa dibangkitkan untuk memberontak di Anatolia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Penyerahan Selanik kepada Venesia", "bfa6c4a0"], "d": ["Gubernur Bizantium di bawah tekanan Utsmaniyah menyerahkan kota kepada Venesia; persaingan Utsmaniyah-Venesia yang akan berlangsung tujuh tahun pun dimulai.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Aneksasi kembali beylik-beylik Anatolia Barat: Menteşe dan Aydın", "aca30a48"], "d": ["Dua beylik Aegea yang didirikan kembali pada Masa Fetret dimasukkan secara definitif ke wilayah Utsmaniyah pada masa Murad II. Menurut entri Menteşeoğulları di TDV, Murad II merebut wilayah Menteşe pada 827 (1424) dan memenjarakan dua saudara yang memimpin beylik. Menurut entri Aydınoğulları, Beylerbeyi Anatolia Hamza Bey menangkap Cüneyd Bey yang kembali membangkang dan mengeksekusinya bersama keluarganya (829/1425-26), dan wilayah Aydın beralih ke Utsmaniyah. Ksatria St. Jean, yang memegang benteng pelabuhan İzmir sejak 1344, kehilangannya kepada Timur pada 1402 dan wilayah itu kembali ke kendali Aydınoğlu; dengan aneksasi ini wilayah itu pun bergabung ke Utsmaniyah. Wilayah Teke (Antalya) bukan pokok entri ini: Tekeoğulları telah dilikuidasi tersendiri pada 1423. Germiyan akan bergabung pada 1429 dengan wasiat.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Aneksasi Germiyan dengan wasiat", "9eb86b77"], "d": ["Bey Germiyan, Yakub II, yang wafat tanpa anak, mewariskan negerinya kepada Utsmaniyah melalui wasiat — contoh aneksasi tanpa perang yang masuk buku pelajaran. Tempat-tempat lain yang bergabung pada tanggal yang sama: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Penaklukan definitif Selanik", "bc021768"], "d": ["Kota yang berada di bawah pemerintahan Venesia itu direbut dengan serbuan; pelabuhan besar kedua Rumelia menjadi Utsmaniyah secara pasti. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kesendire (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Penyerahan Yanya", "ee45cb52"], "d": ["Yanya (Ioannina), pusat Epirus, menyerah dengan perjanjian.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Direbutnya Semendire yang pertama", "c11ca17d"], "d": ["Ibu kota despotat Serbia direbut melalui pengepungan tiga bulan dan Serbia untuk pertama kalinya dianeksasi (akan dikembalikan dengan Perjanjian Edirne-Szeged 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Pengepungan Beograd (gagal)", "3e05f425"], "d": ["Pengepungan besar pertama Beograd yang berlangsung enam bulan tidak membuahkan hasil; benteng itu tetap menjadi kunci penghalang kemajuan Utsmaniyah selama delapan puluh tahun.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Kekalahan Zlatica — 'Ekspedisi Panjang'", "97df1466"], "d": ["Pasukan yang dibawa Hunyadi ke Balkan di tengah musim dingin melewati Niš dan Sofia hingga mencapai Zlatica; pertahanan Utsmaniyah nyaris tidak bertahan. Suasana kekalahan ini membawa perdamaian Edirne-Szeged ke meja perundingan.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Perjanjian Edirne-Szeged", "0aa4e0de"], "d": ["Perdamaian sepuluh tahun: despotat Serbia dikembalikan, Danube diterima sebagai perbatasan. Pelanggaran perjanjian dalam hitungan bulan atas hasutan Paus membawa pada bencana Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Pengembalian Semendire dan benteng-benteng Serbia kepada Serbia", "cda3cf9e"], "d": ["Ketentuan Perjanjian Edirne-Szeged dilaksanakan: pada 15 Agustus 1444 Murad II mengembalikan Semendire bersama dua puluh empat bentengnya yang penting dan wilayah Serbia lain yang diduduki kepada Đurađ Branković (TDV semendire); Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy), dan Priştine (TDV pristine) juga diserahkan kepada Serbia. Vidin tidak termasuk pengembalian karena bukan wilayah Serbia — itulah sumber kehilangan wilayah barat laut yang terlihat di sekitar kemenangan Varna; beberapa bulan kemudian perjanjian itu sendiri sudah batal dengan kekalahan Varna.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Rumeli Hisarı selesai — 'Pemotong Selat'", "480e8a76"], "d": ["Dengan benteng yang selesai dalam pembangunan luar biasa cepat yang menurut sumber berlangsung empat lima bulan, kendali Selat sepenuhnya beralih ke Utsmaniyah; jalur bantuan dari Laut Hitam ke Istanbul tertutup. Dianggap langkah nyata pertama pengepungan.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Pengepungan Istanbul dimulai", "8af50742"], "d": ["Pasukan menempati posisi di depan tembok; dalam pengepungan yang akan berlangsung 54 hari, meriam raksasa untuk pertama kalinya digunakan secara sistematis terhadap tembok sebuah ibu kota.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Kapal-kapal diturunkan ke Tanduk Emas melalui darat", "4f2ba07c"], "d": ["Sekitar 70 kapal dari armada yang tidak dapat memasuki Tanduk Emas yang ditutup rantai diseret melintasi punggung bukit Galata dengan luncuran berminyak dan diturunkan ke Tanduk Emas dalam satu malam; pertahanan terbagi menjadi dua front.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Penaklukan Athena", "4f0f1bb2"], "d": ["Kadipaten Athena berakhir; panji Utsmaniyah dikibarkan di Akropolis. Tempat-tempat lain yang bergabung pada tanggal yang sama: İstefe (Thebai), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Aneksasi Serbia (jatuhnya Semendire)", "75fd0a62"], "d": ["Semendire, ibu kota despotat Serbia, menyerah; Serbia menjadi sebuah sancak Utsmaniyah.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Penaklukan Mora", "7d5a3c18"], "d": ["Despotat Mora dilikuidasi; semenanjung (kecuali benteng-benteng Venesia) masuk ke pemerintahan Utsmaniyah.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Bergabungnya Sinop", "e03c2739"], "d": ["Candaroğlu menyerahkan Sinop tanpa perang; jalan ke ekspedisi Trabzon terbuka. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kastamonu, Bartın, Safranbolu. Entri Candaroğulları di TDV juga menyebut Bolu, Eflani, dan Tosya di antara wilayah beylik Candaroğlu yang dianeksasi pada 1461; dalam atlas ketiga tempat ini juga dicatat beralih dari Candaroğlu ke Utsmaniyah pada hari ini.", "4ef62060"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Runtuhnya Kerajaan Bosnia — ekspedisi Bosnia Fâtih", "5362e3f2"], "d": ["Ketika raja Bosnia terakhir Stjepan Tomašević (1461-1463) menolak membayar upeti dengan bersandar pada dukungan Barat, ia dianggap tidak lagi menjadi penguasa vasal, dan pasukan di bawah Sultan Mehmed Fâtih melikuidasi Kerajaan Bosnia dalam satu ekspedisi. Raja ditangkap dan dieksekusi, kerajaan lenyap, dan sancak Bosnia didirikan di wilayah itu. Namun runtuhnya kerajaan tidak sama dengan penaklukan Bosnia. Pemerintahan Utsmaniyah sudah ada di dataran itu selama lima belas tahun — Hodidjed dan dataran Saray diambil pada 1448, uç beylik Îsâ Bey didirikan di tengah kerajaan. Penaklukan tidak selesai pada 1463: Foça pada 1465, Livno pada 1469, Kadipaten Herzegovina pada 1483, banovina Srebrenik pada 1512, sedangkan Yayça dan Banja Luka di utara baru dapat direbut pada 1528 setelah Mohács — orang Hongaria setelah 1463 mendirikan sebuah banovina yang bertahan enam puluh lima tahun di utara Bosnia. Tempat yang berpindah tangan secara langsung pada tanggal ini adalah Travnik; Yayça pada tanggal ini beralih bukan ke Utsmaniyah melainkan ke Hongaria.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Aneksasi definitif Karaman", "f1dcecaa"], "d": ["Wilayah inti Karamanoğulları bergabung secara definitif; pertikaian internal berlanjut hingga 1470-an. Tempat-tempat lain yang bergabung pada tanggal yang sama: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Penaklukan Eğriboz", "5c97daf3"], "d": ["Eğriboz (Negroponte), pangkalan utama Venesia di Aegea, jatuh.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Aneksasi Alanya, Anamur, dan Silifke (İçel)", "a0b9d461"], "d": ["Jalur pesisir İçel yang terikat pada Karamanoğulları (seluruh Mediterania antara Antalya dan Mersin) bergabung melalui ekspedisi laut Gedik Ahmed Paşa; Alanya penting dengan galangan strategisnya peninggalan masa Seljuk.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Aneksasi Novgorod oleh Moskow", "bed87170"], "d": ["Adipati Agung Ivan III menurunkan lonceng simbolis majelis rakyat (veche) di Novgorod, mengganti para pejabat lokal dengan gubernurnya sendiri, dan secara de facto mengikat kota itu ke Moskow; Novgorod tidak lagi menjadi republik merdeka. Wilayah Novgorod membentang dari Laut Baltik hingga Laut Putih dan Pegunungan Ural. Dalam atlas Novgorod dicatat beralih dari Republik Novgorod ke Moskow pada hari ini.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Perjanjian Istanbul — Albania dan İşkodra", "b09652f7"], "d": ["Perang Utsmaniyah-Venesia selama 16 tahun berakhir; İşkodra dan pesisir Albania tetap di tangan Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Limni, Sisam, Bozbaba (Ay Strati).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Pendaratan di Otranto", "7916b89d"], "d": ["Pasukan Utsmaniyah yang mendarat di pesisir Apulia (Pulya) mengepung dan merebut benteng Otranto; karena kota dimasuki dengan pertempuran, sebagian tokoh yang melawan dieksekusi dan sebagian ditawan. Tradisi gereja mengenang yang tewas sebagai sekitar 800 'syuhada Otranto'; TDV mengaitkan pembesaran angka ini dengan propaganda gereja. Hanya benteng di ujung semenanjung Salento dan lingkungan sempitnya yang dikuasai; wilayah Kerajaan Napoli lainnya di garis Taranto-Brindisi-Lecce tidak lepas — kepala jembatan menuju Italia ini akan bertahan satu tahun.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Pengosongan Otranto", "37371bb0"], "d": ["Dengan wafatnya Sultan Mehmed Fâtih (3 Mei 1481), garnisun Otranto yang tidak lagi berharap bala bantuan baru mengosongkan benteng melalui kesepakatan di hadapan pengepungan putra mahkota Napoli Alfonso; kepala jembatan Utsmaniyah satu-satunya di Italia itu pun hilang setahun kemudian.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Penaklukan Modon dan Koron", "38b608c4"], "d": ["Modon dan Koron, 'dua mata' Venesia di Mora, direbut.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Penaklukan Durrës", "1f231b98"], "d": ["Selama perang Utsmaniyah-Venesia 1499-1503, pasukan di bawah komando Mehmed Bey merebut Durrës, pelabuhan besar Albania terakhir Venesia di Adriatik. Setelah İşkodra (1479) dan Vlora (1417), dengan penaklukan ini jalur pesisir Albania seluruhnya masuk ke kendali Utsmaniyah.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Bergabungnya Anatolia Timur", "e0cb8f8f"], "d": ["Setelah Çaldıran, Diyarbakır dan sekitarnya bergabung; beylik-beylik Kurdi diikat kepada Utsmaniyah melalui İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Penaklukan Benteng Varadin (Petrovaradin)", "abf392a5"], "d": ["Pasukan yang berangkat dalam ekspedisi Mohács menyeberang dari Beograd ke tanah Hongaria; lebih dulu pinggiran luar Varadin direbut, kemudian benteng jatuh setelah pengepungan empat belas hari. Kanuni memerintahkan agar desa-desa di jalan tidak dibakar, karena tempat-tempat itu kini dianggap tanah Utsmaniyah.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Penyerahan Buda setelah Mohács — dua raja untuk takhta Hongaria", "9d3568a0"], "d": ["Kunci-kunci kota diserahkan kepada sultan pada 11 September 1526 ketika pasukan Utsmaniyah yang berbaris ke Buda setelah kemenangan Mohács tiba; namun Kanuni tidak mempertahankan Buda dan menarik pasukannya. Di Hongaria yang tanpa raja, para bangsawan memilih dua raja berbeda: János Szapolyai pada 10 November 1526, dan Ferdinand I dari Habsburg pada 17 Desember 1526. Ferdinand merebut Buda pada Agustus 1527. Menetapnya Szapolyai di Buda sebagai raja di bawah perlindungan Utsmaniyah akan terjadi dengan ekspedisi 1529 (lihat entri 1529), dan pemerintahan langsung Utsmaniyah akan didirikan pada 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai dipilih sebagai raja Hongaria — Utsmaniyah mengakui kerajaannya dengan syarat menjadi vasal", "32bc6baf"], "d": ["Sebagian bangsawan memilih János Szapolyai, voivode Transilvania, untuk takhta Hongaria yang kosong karena wafatnya raja di Mohács; Szapolyai dimahkotai di Székesfehérvár. Utsmaniyah, yang mengosongkan Buda, mengakui kerajaan Szapolyai dengan syarat menjadi vasal mereka agar wilayah itu tetap menjadi penyangga. Di peta, tempat-tempat yang terikat pada Szapolyai tampak menjadi vasal Utsmaniyah sejak tanggal ini.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinand I dinyatakan raja Hongaria — Hongaria Barat dan Utara ke mahkota Habsburg", "b3910a2f"], "d": ["Archduke Habsburg Ferdinand, bersandar pada pernikahan saudara perempuannya dengan Lajos II, menuntut hak atas takhta Hongaria dan dinyatakan raja oleh sebagian bangsawan. Dengan demikian Hongaria terbagi antara dua raja; bagian barat dan utara mengakui Ferdinand. Para bangsawan Kroasia juga memilihnya secara terpisah pada awal 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Pertikaian dua raja: Esztergom ke perlindungan Habsburg, Szeged ke Szapolyai", "da92dee5"], "d": ["Esztergom, yang berpindah tangan antara dua raja sejak 1526, masuk ke perlindungan Habsburg setelah uskup agung pindah ke utara dengan arsip dan perbendaharaannya. Dari tahun yang sama hingga 1541, Szeged tetap di bawah kedaulatan Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Penduduk Pécs beralih ke pihak Szapolyai", "3fc4e7f2"], "d": ["Pécs, yang memperoleh imtiyaz dari Ferdinand pada 1528, tak lama kemudian beralih ke pihak Szapolyai; Raja János tinggal di kota untuk beberapa waktu pada 1533. Dengan jatuhnya Buda pada 1541, kota itu kembali ke pihak Ferdinand.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Penaklukan Tripoli", "8c659986"], "d": ["Tripoli direbut dari Ksatria Saint Jean; pesisir tengah Afrika Utara menjadi Utsmaniyah. Tempat-tempat lain yang bergabung pada tanggal yang sama: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Penaklukan Timișoara", "e9fd4995"], "d": ["Wilayah Banat direbut dan Beylerbeylik Timișoara didirikan.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Penaklukan definitif Tunisia", "7bbd11bc"], "d": ["Tunisia, yang berada di bawah kendali Spanyol-Hafsiyah, masuk secara definitif ke pemerintahan Utsmaniyah; garis Afrika Utara pun lengkap. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kayrevan, Gabes, Sfaks.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Penaklukan Kanije", "0c7b6aa3"], "d": ["Kanije direbut dalam Perang Panjang; pertahanan Tiryâki Hasan Paşa pada tahun berikutnya menjadi legenda.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Ekspedisi Uyvar dimulai — Fâzıl Ahmed Paşa berbaris dari Edirne menuju Austria", "306a86db"], "d": ["Ketika Austria menyerang Transilvania dan merebut benteng Székelyhíd dan Kolozsvár, Istanbul memutuskan ekspedisi melawan Habsburg. Wazir Agung Köprülüzâde Fâzıl Ahmed Paşa berangkat dari Edirne pada 13 April 1663. Di Beograd datang permintaan damai dari Austria, tetapi dalam dua pertemuan di Osijek syarat-syarat Utsmaniyah ditolak. Dalam musyawarah di Buda, sasaran pun ditetapkan Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Penaklukan Uyvar", "ce289470"], "d": ["Uyvar (Nové Zámky), benteng kunci Hongaria Utara, direbut; ungkapan 'sekuat seorang Turki di depan Uyvar' masuk ke dalam bahasa-bahasa Eropa. Setelah Uyvar, Nitra dan Léva juga menyerah setelah perlawanan singkat; keduanya direbut kembali oleh De Souches pada musim semi 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Direbutnya kembali Mora", "9b6460f1"], "d": ["Mora, yang diserahkan kepada Venesia di Karlowitz, direbut kembali dalam satu ekspedisi. Tempat-tempat lain yang bergabung pada tanggal yang sama: Balyabadra (Patras), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Kehilangan Beograd yang kedua — pengepungan Pangeran Eugen", "6a194354"], "d": ["Setelah kekalahan Varadin dan hilangnya Timișoara, Pangeran Eugen mengepung Beograd; ketika pasukan bantuan yang datang menyelamatkan kota juga dikalahkan, benteng menyerah. Kota yang telah direbut kembali pada 1690 setelah Karlowitz itu pun lepas lagi dan garis pertahanan Danube runtuh. Beograd baru dapat direbut kembali dua puluh dua tahun kemudian dengan Perjanjian Beograd 1739. Permukiman lain yang lepas pada tanggal yang sama: Semendire. Atlas juga mencatat wilayah Hisarcık (Grocka) dan Yagodina (Jagodina) untuk Habsburg pada hari ini (hari tingkat wilayah; hari tingkat tempat tidak ada dalam sumber, pendekatan yang dinyatakan); sedangkan Mehádia beralih ke Habsburg pada tanggal 27 Agustus 1717 (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Jatuhnya Özi", "90a67a6c"], "d": ["Özi (Ochakov), benteng kunci di utara Laut Hitam, jatuh ke tangan Rusia dalam serbuan berdarah; penduduk kota dibantai dengan pedang.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Perjanjian Bukares — hilangnya Bessarabia", "932da4d6"], "d": ["Dengan perjanjian yang mengakhiri perang Rusia 1806-1812, wilayah di timur Prut (Bessarabia) diserahkan kepada Rusia. Permukiman lain yang lepas pada tanggal yang sama: Akkirman, Kili, Hotin, Bender, İsmail. Atlas juga menganggap Kişinev (Chișinău), Bălți, Kahul (Cahul), dan Orhei di dalam Bessarabia telah beralih dari Moldavia (vasal Utsmaniyah) ke Rusia pada hari yang sama. Soroka (Soroca) juga beralih ke Rusia pada hari yang sama.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Perjanjian Edirne", "b3a8fe4c"], "d": ["Pada akhir perang ketika pasukan Rusia memasuki Edirne, delta Danube hilang; otonomi/kemerdekaan Yunani diakui secara de facto. Permukiman lain yang lepas pada tanggal yang sama: İbrail, Anapa, Ahıska. Meski perjanjian mengembalikan tanah, ia tidak segera mengakhiri pendudukan: Wallachia-Moldavia dan Silistre tetap berada di bawah administrasi Rusia sebagai jaminan sampai ganti rugi perang dibayar — itulah sebabnya di peta tempat-tempat ini tampak masih diduduki setelah 1829.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Dekret otonomi untuk Serbia — knez turun-temurun dan syarat garnisun", "6a5d901d"], "d": ["Hatt-ı hümâyun yang dikeluarkan sesuai ketentuan Perjanjian Edirne tentang Serbia mengakui Miloš Obrenović sebagai knez turun-temurun dan menjadikan Serbia kepangeranan otonom yang bebas dalam urusan dalam negeri dan terikat pada Utsmaniyah dalam urusan luar. Ketentuannya: kedudukan knez diwariskan dari ayah ke anak, pajak tahunan dibayar tetap, majelis Serbia membentuk pemerintahan dalam negerinya sendiri, gereja otonom; sebagai imbalannya garnisun Utsmaniyah tetap berada di benteng Beograd, Semendire, Šabac, Böğürdelen, dan Fethülislâm. Struktur ganda ini bertahan hingga penarikan garnisun pada 1867. Di peta, kota Beograd pada tanggal ini bergabung ke Serbia otonom; benteng Kalemegdan ditampilkan di bawah garnisun Utsmaniyah hingga 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Penyerahan Siprus ke administrasi Inggris", "423da3ee"], "d": ["Sebagai imbalan aliansi melawan ancaman Rusia, administrasi Siprus diserahkan kepada Inggris; secara hukum tetap wilayah Utsmaniyah. Permukiman lain yang lepas pada tanggal yang sama: Lefkoşa, Magosa, Girne, Limasol, Larnaka (Tuzla), Baf, Güzelyurt (Morphou), Akrotiri, Episkopi, Dikelya (Dhekelia); yakni seluruh pulau.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Penyerahan Thessalia kepada Yunani", "ac614d24"], "d": ["Sesuai keputusan Kongres Berlin, Thessalia dan sekitar Narda diserahkan kepada Yunani. Permukiman lain yang lepas pada tanggal yang sama: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia). Dengan penyerahan ini Golos (Volos), Kalabaka, dan Kardiçe (Thessalia) beralih ke Yunani.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Bergabungnya Rumelia Timur dengan Bulgaria", "ee43f137"], "d": ["Provinsi otonom Rumelia Timur dihubungkan dengan Bulgaria melalui kudeta; Bâbıâli menerima fait accompli itu. Dengan penyatuan ini seluruh Rumelia Timur (Eski Zağra, Tatarpazarcığı, İslimye, Hasköy, Burgaz, Aydos, Elhova) beralih ke Kepangeranan Bulgaria.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Pertempuran Domokos", "9c6f29a5"], "d": ["Dalam Perang Utsmaniyah-Yunani 1897, pasukan meraih kemenangan menentukan di Domokos; perolehan wilayah tetap terbatas karena tekanan diplomatik.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Otonomi untuk Kreta", "2e764881"], "d": ["Meski Perang Utsmaniyah-Yunani berakhir dengan kemenangan Utsmaniyah, Inggris, Rusia, Prancis, dan Italia pada 18 Desember 1897 mengumumkan otonomi Kreta; pulau itu akan menjadi provinsi netral dan otonom di bawah kedaulatan Utsmaniyah. Setelah 6 November 1898 bendera Turki tidak lagi dikibarkan di Kandiye dan Kisamo; dengan Pangeran George, putra raja Yunani, mulai bertugas sebagai komisaris luar biasa pada 22 Desember 1898, Kreta secara de facto keluar dari pemerintahan Utsmaniyah (secara resmi terpisah pada 1913). Permukiman lain yang lepas pada tanggal yang sama: Kandiye (Girit), Hanya.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Kemerdekaan Bulgaria dan aneksasi Bosnia", "393feaa4"], "d": ["Dalam kekacauan Masa Konstitusional, Bulgaria memproklamasikan kemerdekaannya dan Austria-Hongaria menganeksasi Bosnia-Herzegovina. Dengan proklamasi ini seluruh wilayah Kepangeranan Bulgaria (Varna, Şumnu, Rusçuk, Burgaz, İslimye, dll.) menjadi Kerajaan Bulgaria yang merdeka.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Direbutnya kembali Edirne", "536e5599"], "d": ["Dalam Perang Balkan II, pasukan menyeberangi Maritsa dan merebut kembali Edirne tanpa perang. Tempat-tempat lain yang bergabung pada tanggal yang sama: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Kemenangan Kut al-Amara", "98b972bc"], "d": ["Komandan divisi Inggris yang terkepung di Kut menyerah bersama 13 ribu prajuritnya — salah satu kemenangan Utsmaniyah terbesar dalam Perang Dunia I.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Hilangnya Baghdad", "2c18a816"], "d": ["Baghdad Utsmaniyah yang telah berusia 383 tahun beralih ke tentara Inggris. Permukiman lain yang lepas pada tanggal yang sama: Kerbelâ.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Hilangnya Yerusalem", "94067617"], "d": ["Yerusalem Utsmaniyah yang telah berusia 401 tahun diserahkan tanpa dapat dipertahankan.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Hilangnya Damaskus", "ed177b68"], "d": ["Dengan runtuhnya front Palestina, Damaskus dikosongkan; pemerintahan Utsmaniyah empat abad di Suriah berakhir. Permukiman lain yang lepas pada tanggal yang sama: Hama, Humus.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Penyerahan Madinah", "76b505f6"], "d": ["Tujuh puluh dua hari setelah gencatan senjata, perlawanan Fahreddin Paşa, 'Macan Gurun', berakhir atas perintah sultan; unit Utsmaniyah terakhir di Hijaz meletakkan senjata.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Pendudukan İzmir", "e32e5e77"], "d": ["Tentara Yunani mendarat di İzmir; perlawanan yang dimulai dengan peluru pertama menyulut sumbu Perjuangan Nasional. Aydın diduduki pada 27 Mei 1919 (entri terpisah).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Pendudukan resmi Istanbul", "a8e98ada"], "d": ["Pasukan Entente menduduki Istanbul secara resmi, Meclis-i Meb'ûsan dibubarkan; para anggota parlemen menuju Ankara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Perjanjian Kars", "bb32d4e0"], "d": ["Antara TBMM dan republik-republik Kaukasus, perbatasan timur digambar dalam bentuknya yang sekarang.", "fe736259"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Pasukan Saudi-Wahhabi merebut emirat Ha'il — pemerintahan di tangan keluarga Ibn Ali dari suku Abde", "2d29ceb9"], "d": ["Ketika pasukan Negara Saudi Pertama merebut emirat Ha'il, pemerintahan kota berada di tangan keluarga Ibn Ali dari suku Abde dari kabilah Shammar. Keluarga ini memerintah Ha'il hingga Abdullah b. Rashid mengambil alih keamiran pada 1835; dinasti Rashidi baru didirikan pada tanggal itu. Di atlas Ha'il hingga kini tampak tak bertuan hingga 1836, padahal sumber memberi emir kota pada 1820 dengan namanya.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Beralihnya pulau-pulau Kvarner ke Kerajaan Italia Napoleon, dan Boka Kotorska ke pemerintahan Rusia", "c5e411c8"], "d": ["Setelah Perjanjian Pressburg, pulau-pulau Kvarner — berbeda dengan Dalmatia — diikat bukan langsung ke Prancis melainkan ke Kerajaan Italia Napoleon; mereka baru masuk ke Provinsi Illyria pada 1809. Di Boka Kotorska pemerintahan Austria berakhir dan pemerintahan Rusia didirikan antara 1806-1807; Boka baru beralih ke Prancis pada 1807. Kedua perbedaan ini tidak dapat dipenuhi dengan satu jendela 'Prancis' atlas.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Beralihnya Dalmatia ke pemerintahan Prancis — penerapan Perjanjian Pressburg", "00bfe4f6"], "d": ["Perjanjian Pressburg 26 Desember 1805 memaksa Austria melepaskan Istria, Dalmatia, dan semua pulau Adriatik. Prancis mengambil alih pemerintahan secara faktual pada Februari 1806; Zadar tetap menjadi pusat proveditor umum dan jabatan ini dijalankan oleh Vicenzo Dandolo dari Venesia antara 1806-1810. Dalmatia bergabung ke Provinsi Illyria setelah Perjanjian Schönbrunn 1809. Pemerintahan Austria pertama yang berlangsung sejak 1797 dengan demikian berakhir — di atlas masa ini hingga kini tampak sebagai Austria tanpa putus.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Austria merebut kembali Provinsi Illyria dan Dalmatia — berakhirnya pemerintahan Napoleon", "1b2ac942"], "d": ["Pada akhir 1813 pasukan Habsburg merebut kembali wilayah di selatan Sava dan organisasi perbatasan lama didirikan kembali; pasukan Austria memasuki Istria pada Oktober 1813. Karlovac sejak tanggal itu menjadi bagian Kerajaan Illyria Austria. Masa pemerintahan Prancis di Dalmatia juga tertutup pada 1813. Keterikatan wilayah itu pada Austria disahkan secara resmi dengan Perdamaian Paris 1814 dan keputusan Kongres Wina 1815. Dengan operasi ini Villach, Tarvisio, Gorizia, Gradisca, dan Pula (Provinsi Illyria) kembali ke Austria pada akhir 1813.", "bf1e49a8"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["Perebutan kembali Dimyat dari Prancis — pengosongan benteng Lesbe", "06b1e7b0"], "d": ["Sebuah pasukan di bawah İbrâhim Paşa dari tentara Sadrazam dikirim ke Dimyat. Pada pagi 14 Mei, ketika serbuan ke benteng Lesbe yang melindungi Dimyat sudah disiapkan, terlihat bahwa benteng itu telah dikosongkan oleh Prancis dan garnisunnya mundur; dua benteng kecil yang bergantung padanya juga direbut. Dimyat menjadi kota muara Nil kedua yang lepas dari kendali Prancis setelah Reşîd yang jatuh pada April.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Penyerahan Kairo dari Prancis — kapitulasi Belliard", "7a11bb5e"], "d": ["Selama operasi bersama Utsmani dan Inggris terhadap Mesir, Jenderal Belliard, komandan pasukan Prancis di Kairo, menandatangani kapitulasi. Bersama Kairo, Suez yang direbut Prancis pada November 1798 juga lepas dari kendali Prancis. Penutupan pendudukan akan selesai dua bulan kemudian di Iskandariyah, sedangkan evakuasi dari negeri itu berlanjut hingga Oktober.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Penyerahan Iskandariyah dari Prancis — kapitulasi Menou", "cd50663c"], "d": ["Jenderal Menou, panglima Tentara Timur, terkepung di Iskandariyah pada 17 Agustus; pada 21 Agustus Inggris merebut benteng Marabout di dekat kota, dan pada 31 Agustus Menou menandatangani kapitulasi tentara. Kepulangan pasukan Prancis ke Prancis dimulai pada 2 September. Dengan demikian pendudukan yang dimulai dengan pendaratan di Iskandariyah pada Juni 1798 berakhir di kota tempat ia bermula.", "22e807c1"]},
"OLAYLAR_ORTADOGU_0919:1801-01-01:0":{"b": ["Suku-suku sekitar Tâif masuk ke pengaruh Wahhabi — Türabe dan Hurma memisahkan diri dari Kesyarifan Mekah", "d3b644be"], "d": ["Suku-suku sekitar Tâif yang terikat pada Syarif Mekah Gālib masuk ke pengaruh Wahhabi pada 1801; emir Dir'iyah menyerahkan mereka ke pemerintahan syekh Badui Osman el-Mudâyifî, ipar sekaligus musuh sang Syarif. Oasis Türabe dan Hurma di timur juga beralih ke pihak Saudi pada rangkaian ini. Ini adalah pendahulu direbutnya Tâif dan kemudian Mekah oleh Wahhabi pada Februari 1803.", "4fe448d3"]},
"OLAYLAR_ORTADOGU_0919:1816-01-01:0":{"b": ["Garnisun Mesir mundur dari Türabe, Bîşe, dan Rânye di Hijaz selatan", "72b87aa1"], "d": ["Pada bulan-bulan setelah Tosun Paşa berdamai dengan Wahhabi dan kembali ke Kairo pada November 1815, timbul kekacauan di Hijaz selatan; garnisun Kavalalı Mehmed Ali Paşa terpaksa mundur dari Bîşe, Rânye, dan Türabe. Berangkatnya İbrâhim Paşa dari Kairo pada Agustus 1816 untuk ekspedisi baru menyusul mundurnya ini. Siapa yang memerintah Türabe hingga jatuhnya Dir'iyah (1818) tidak tertulis dalam sumber.", "90e76189"]},
"OLAYLAR_ORTADOGU_0919:1819-08-13:0":{"b": ["Garnisun Mesir mundur dari Süleymiye di Harj dan mencapai Menfûha — Najd selatan tanpa pemimpin", "2743f70d"], "d": ["Setelah kehancuran Dir'iyah, pos Mesir yang ditempatkan İbrâhim Paşa di Süleymiye di Harj, sebelum berangkat atas perintah mundur sang Paşa, membunuh empat syekh Dilem dalam sebuah jamuan dan dikepung oleh suku Badui. Garnisun yang diselamatkan itu mencapai Menfûha pada 13 Agustus 1819 dan pawai ke Qasim dimulai. Di Najd selatan tidak tersisa otoritas pusat; upaya keluarga Saud tidak membuahkan hasil hingga 1824.", "fc53fbd1"]},
"OLAYLAR_P0043A:1456-01-01:0":{"b": ["Şehirköy kembali ke kekuasaan Utsmani — wafatnya Đurađ Branković", "e37156d1"], "d": ["Şehirköy, yang direbut tentara Salib pada 1443 dan ditinggalkan kepada Serbia oleh II. Murad setelah Perjanjian Edirne-Segedin 1444, kembali ke kekuasaan Utsmani dengan wafatnya Despot Serbia Đurađ Branković pada 1456. Pada tahun yang sama dan karena sebab yang sama Niş juga masuk ke administrasi Utsmani secara pasti; garis lembah Nišava yang terbuka ke jalan Sofia dengan demikian lengkap. Perjanjian itu ditandatangani untuk jangka sepuluh tahun, dan setelah Varna (1444) serta Kosovo II (1448), umur Despotat hanya sepanjang hidup Branković.", "4b6ec617"]},
"OLAYLAR_P0043B:1514-03-20:0":{"b": ["Yavuz Sultan Selim berangkat dari Edirne untuk Ekspedisi Çaldıran", "1f7921f7"], "d": ["Yavuz Sultan Selim, yang menunjuk putranya Şehzade Süleyman di Manisa sebagai wakilnya di İstanbul, berangkat dari Edirne untuk ekspedisi yang ia atur terhadap Negara Safawi. Tentara melintasi Anatolia lewat garis Sivas-Erzincan-Erzurum dan akan bertemu pasukan Şah İsmail di Çaldıran pada akhir Agustus.", "430f5ccc"]},
"OLAYLAR_P0043KIRIM:1526-01-01:0":{"b": ["Kızıkermen (Gazi Kerman) dan tepi kanan Dnieper masuk ke bawah kendali langsung Utsmani", "56a28224"], "d": ["Benteng Kızıkermen dan tepi kanan Dnieper, yang dikuasai Khanat Krimea sejak pertengahan abad ke-15, pada tanggal ini masuk ke bawah kendali langsung Negara Utsmani; benteng itu berubah menjadi pos terdepan Utsmani di ujung utara stepa. Berbeda dengan wilayah Khanat Krimea di sekitar Bahçesaray dan Or Kapı, administrasi Kızıkermen langsung di tangan Utsmani.", "a0eaba40"]},
"OLAYLAR_P0043KIRIM:1776-12-03:0":{"b": ["Prozorovski menduduki Or Kapı — pasukan Rusia tetap di Orkapı hingga aneksasi", "afdfe804"], "d": ["Ketika Jenderal Prozorovski, yang bergerak untuk menaikkan Şâhin Giray ke takhta Krimea, tiba di garis Perekop, Devlet Giray, kaymakam, dan bangsa Tatar telah mundur dari kota; Prozorovski menduduki benteng Or dan garis Perekop tanpa perang. Rusia menetap di Or Kapı dan tinggal di sana hingga aneksasi Krimea pada 1783.", "2c53b49b"]},
"OLAYLAR_P0043KIRIM:1791-07-26:0":{"b": ["Pendudukan Anapa oleh Rusia (pengepungan ketiga)", "e6a7d6d5"], "d": ["Benteng Anapa yang dibangun di bawah Ferah Ali Paşa pada 1781 dikepung Rusia tiga kali selama perang; pada akhir pengepungan ketiga, ia diduduki pada 26 Juli 1791. Pendudukan itu bersifat sementara — karena perbatasan lama di Kaukasus diterima dengan Perjanjian Yaş (1792), benteng dikembalikan kepada Negara Utsmani.", "6f3b16fa"]},
"OLAYLAR_P0043KIRIM:1828-06-24:0":{"b": ["Penyerahan Anapa oleh Osman Paşa kepada Rusia", "3ccbdd1d"], "d": ["Pada fase pembukaan Perang Utsmani-Rusia 1828-29, Anapa dikepung dan pasukan Utsmani di benteng di bawah komando Osman Paşa menyerah kepada Rusia pada 24 Juni 1828. Kali ini penyerahan bersifat permanen: dengan Perjanjian Edirne yang ditandatangani tahun berikutnya (14 September 1829), Anapa dan Kaukasus secara resmi lepas dari kekuasaan Utsmani.", "d49b4078"]},
"OLAYLAR_P0044:1556-01-01:0":{"b": ["Turgut Reis menjadi beylerbeyi Trablusgarp — eyalet meluas ke Tobruk dan Derne di timur", "160fa43c"], "d": ["Setelah penaklukan Trablusgarp pada 1551, Turgut Reis datang ke Trablusgarp dengan gelar beylerbeyi pada Cemâziyelevvel 963 (Maret 1556). Selama masa jabatannya yang berlangsung sembilan tahun, ia berupaya membangun dan membentengi eyalet, membawa administrasi Utsmani hingga Fizan di selatan, dan memperluas batas ke timur dengan merebut Tobruk dan Derne di pesisir Berka. Dengan demikian eyalet Trablusgarp mencakup jalur pantai hingga perbatasan Mesir.", "44cf4583"]},
"OLAYLAR_P0044:1556-01-01:1":{"b": ["Kekaisaran Moskow merebut Astrahan — Volga Hilir masuk ke kendali Rusia", "d02abd83"], "d": ["Pada 1556 Kekaisaran Moskow juga merebut Astrahan, sebuah langkah yang, dalam ungkapan TDV, 'akan membawa akibat yang sangat penting di masa depan'; dengan pendudukan Khanat Astrahan, Volga Hilir masuk ke kendali Rusia. Khan Krimea Devlet Giray ingin mencegah pendudukan ini tetapi tidak berhasil. Utsmani menjawab perkembangan ini dengan ekspedisi Astrahan pada 1569; tetapi karena tidak berhasil menguasai kawasan Volga Hilir, mereka menyerahkan perjuangan melawan Kekaisaran Moskow kepada khan Krimea.", "7e08ba29"]},
"OLAYLAR_P0044:1556-07-16:0":{"b": ["Penaklukan Kostayniçe dan Novi — dua benteng garis Una", "2093e452"], "d": ["Kostayniçe, yang dikepung Malkoç Bey pada musim panas 1556, dipertahankan oleh kapten Pankracije Lusthaller dengan lebih dari 60 prajurit; benteng diserahkan hanya sehari setelah pengepungan dimulai, pada 16 Juli, dan Lusthaller dituduh menjual benteng. Tak lama kemudian Novi juga direbut dan dibakar; dengan demikian dua benteng terpenting di Una jatuh ke tangan Utsmani dalam sekali pukul. Pada tahun yang sama di Wina didirikan Dewan Perang Istana (Hofkriegsrat) yang mengelola pertahanan serhad dari pusat.", "b985cbdf"]},
"OLAYLAR_P0044:1574-01-01:0":{"b": ["Mâku beralih ke Utsmani — Mahmûdî İvaz Bey ditugaskan membangun benteng", "5932ad38"], "d": ["Pada tahun 1574 Negara Utsmani menugaskan İvaz Bey, pemimpin suku Kurdi Mahmûdî, untuk merebut Mâku dari bangsa Iran dan membangun benteng di sana. Benteng di ujung timur eyalet Van ini memegang tempat penting dalam peristiwa yang terjadi di kawasan itu pada masa Utsmani.", "bd663d7c"]},
"OLAYLAR_P0044:1840-01-01:0":{"b": ["Uang kertas Utsmani pertama (kâime) diterbitkan", "d2e5e192"], "d": ["Dalam pencarian pendapatan bagi keuangan negara pada tahun-tahun pertama Tanzimat, atas usul Ârif Hikmet Bey yang kelak menjadi şeyhülislâm, penerapan kâime, bentuk yang disempurnakan dari sistem esham, diterima. Kâime pertama senilai total 160.000 lira (32.000 kese) diterbitkan dengan tulisan tangan tanpa menunggu dicetak karena kebutuhan uang yang mendesak, kemungkinan pada Juni 1840, pada masa Menteri Keuangan Sâib Paşa. Masa edar kertas-kertas yang berstatus uang tunai ini delapan tahun, bunganya 12,5% per tahun; tidak ada jaminannya, hanya bunganya yang dijamin dari pendapatan bea cukai İstanbul. Rakyat tidak menyambut baik uang yang tidak biasa itu, dan kâime tulisan tangan segera menjadi sasaran pemalsu.", "1f5f905c"]},
"OLAYLAR_P0047:1511-08-10:0":{"b": ["Perebutan Malaka oleh Portugis", "e1556746"], "d": ["Malaka, yang didirikan pada 1390-an, telah menjadi pelabuhan tersibuk di kawasan itu dalam perdagangan laut antara Tiongkok, India, dan Barat, serta pusat Kesultanan Malaka, dan menjadi pusat utama penyebaran Islam ke pulau-pulau sekitarnya. Afonso de Albuquerque dari Portugal merebut kota itu pada 10 Agustus 1511; kota dijarah, dan masjid-masjid, makam dinasti, serta bangunan batu lainnya dihancurkan agar batunya dipakai membangun benteng. Malaka di bawah Portugis tak mampu mempertahankan keunggulan dagangnya yang lama; para pedagang muslim beralih ke pelabuhan Kesultanan Aceh di Sumatra. Atas serangan Portugis yang menetap di Malaka terhadap Aceh, sultan Aceh Alâeddin Riâyet Şah meminta bantuan Kanûnî Sultan Süleyman pada 1565.", "bfb60150"]},
"OLAYLAR_P0048:1592-01-01:0":{"b": ["Pernyataan kesetiaan Şâhverdi, penguasa Luristan, kepada Şah Abbas", "85791f94"], "d": ["Şâhverdi, penguasa Luristan yang pada 1589 tunduk kepada Utsmani dan menjadi bawahan beylerbeyi Bagdad, menurut penuturan sejarawan Safawi İskender Bey Münşî terpaksa menyatakan kesetiaan kepada mahkota Safawi pada tahun 1000 (1591-92). Sumber yang sama menulis bahwa pada tahun-tahun ini ia bolak-balik di antara kedua pihak, mengganggu para gubernur Hemedan dan melancarkan serbuan ke Burûcird, dan bahwa pada tahun 1002 (1593-94) Şah Abbas menduduki Hürremâbâd dan mengangkat seorang gubernur untuk kota itu. TDV İslâm Ansiklopedisi sebaliknya menempatkan penyatuan penuh Luristan, yang pada 1590 dihubungkan dengan administrasi Utsmani lewat Perjanjian İstanbul, kepada Safawi pada tahun 1603. Kedua tradisi memberi tanggal yang berbeda; butir ini menunjukkan pernyataan kesetiaan menurut tradisi Safawi, sedangkan butir 1603 menunjukkan kehilangan yang pasti. Di peta, dengan butir ini tidak ada perubahan pemilik: Luristan tampak di pihak Utsmani hingga 1603.", "d15b2c77"]},
"OLAYLAR_P0048:1603-01-01:0":{"b": ["Peralihan pasti Luristan kepada Safawi", "4c5cf67b"], "d": ["Luristan, yang dihubungkan dengan administrasi Utsmani lewat Perjanjian İstanbul (Ferhad Paşa) 1590, dihubungkan sepenuhnya dengan Safawi oleh Şah I. Abbas pada 1603. Sejarawan Safawi İskender Bey Münşî sebaliknya menulis bahwa Hürremâbâd telah diduduki Şah Abbas lebih awal, pada tahun 1002 (1593-94), dan seorang gubernur Safawi diangkat untuk kota itu; perbedaan antara kedua tradisi ini belum terselesaikan. Pada tahun yang sama benteng Utsmani Nihâvend di utara Luristan juga jatuh ke tangan Şah Abbas; gubernur Hemedan Hasan Han meratakan benteng itu.", "3e110da7"]},
"OLAYLAR_P0049:1303-09-01:0":{"b": ["Kompi Katalan memasuki dinas Bizantium — awal ekspedisi Anatolia", "6623e7db"], "d": ["Kekaisaran Bizantium, yang kehilangan wilayah di hadapan beylik-beylik Turki di Anatolia Barat, menerima pasukan Katalan sekitar 6500 orang di bawah komando Roger de Flor sebagai tentara bayaran. Menurut artikel Bizans TDV, pasukan itu datang membantu kekaisaran pada 1303 dan pada tahun berikutnya menyelamatkan Alaşehir yang dikepung Germiyanoğulları. Namun kompi itu segera mulai menjarah tempat-tempat yang dilaluinya; Bizantium memindahkannya ke Trakia dan pada 1305 membunuh Roger de Flor.", "87b98a94"]},
"OLAYLAR_P0049:1538-11-27:0":{"b": ["Penguasa Hadramut dan Şihr mengakui kekuasaan Utsmani — kepulangan Hadım Süleyman Paşa dari ekspedisi India", "b5cb9363"], "d": ["Hadım Süleyman Paşa, yang kembali dari pengepungan Diu, singgah di Pelabuhan Şihr pada 27 November 1538; ketika penguasa Hadramut dan Şihr menerima kekuasaan Utsmani, ia melanjutkan ke Aden. Hadramut diorganisasi sebagai sancak yang bergantung pada Yaman, tetapi para pemimpin suku Kesîrî tetap memegang administrasi di kawasan itu. Ketundukan ini berlangsung hingga penarikan Utsmani dari Yaman pada 1635.", "cff04bbb"]},
"OLAYLAR_P0049:1555-05-29:0":{"b": ["Beylik Megrelya (Dadyan) ditinggalkan di zona pengaruh Utsmani", "ea54e8ea"], "d": ["Dengan ketentuan Perjanjian Amasya yang membagi Georgia, beylik Dadyan (Megrel dan Svanet) di Georgia Barat ditinggalkan di zona pengaruh Utsmani bersama İmereti dan Güryel. Di peta, Zugdidi, pusat Megrelya, sejak hari ini tampak sebagai beylik yang tunduk kepada Utsmani; pernyataan ketaatan yang sebenarnya akan datang pada 1578.", "1724aa10"]},
"OLAYLAR_P0049:1578-08-09:0":{"b": ["Atabeg Ahıska masuk ke administrasi Utsmani — Altunkale, Hırtıs, dan Ahılkelek", "024bb326"], "d": ["Segera setelah Lala Mustafa Paşa mengalahkan pasukan pelopor Safawi di Çıldır, wilayah yang berada di tangan atabeg Georgia juga beralih ke administrasi Utsmani. Dedis İmedi, yang menguasai Altunkale dan sekitarnya, bersama putra-putranya menyatakan ketaatan; sancak beyi Ardahan merebut Çıldır dan Tümük, sedangkan pasukan Utsmani lain merebut Hırtıs dan Ahılkelek. Sebuah sancak masing-masing ditinggalkan untuk Menûçihr dan saudaranya, sisa negeri atabeg dihubungkan dengan administrasi langsung. Ahıska sesudah itu akan menjadi pusat eyalet Çıldır yang baru dibentuk; Menûçihr, yang datang ke İstanbul, masuk Islam dan mengambil nama Mustafa, akan ditempatkan sebagai kepala eyalet ini pada 1 Juli 1579.", "23731679"]},
"OLAYLAR_P0049:1579-07-26:0":{"b": ["Kılıç Ali Paşa membangun Benteng Faş (Poti) — pangkalan Utsmani di muara Rioni", "f729ba95"], "d": ["Kaptan-ı derya Kılıç Ali Paşa membangun Benteng Faş di tempat sungai Rioni (Faş) bermuara ke Laut Hitam pada 26 Juli 1579.", "13606f9d"]},
"OLAYLAR_P0049:1587-01-01:0":{"b": ["Eyalet Gori didirikan — administrasi Utsmani langsung di barat Kartli", "9a7c8bc5"], "d": ["Pada 1578 para bey Georgia di kawasan Gori dan Muhran telah menaati Utsmani. Pada 1587 eyalet Gori didirikan di barat Kartli dan kawasan itu dihubungkan dengan administrasi Utsmani langsung. Benteng Gori, yang lepas pada pemberontakan Simon dari Georgia, direbut kembali pada 1601; administrasi Utsmani berakhir pada 1603 dengan ekspedisi Şah Abbas.", "7ee17c2b"]},
"OLAYLAR_P0049:1595-01-01:0":{"b": ["Serbuan Mihail si Berani ke benteng-benteng Tuna — Rusçuk dibakar, İbrâil direbut, Silistre dijarah", "d0b83f6a"], "d": ["Voyvoda Eflak Mihail si Berani, yang bergabung dengan Liga Suci, pada musim dingin 1594-95 menyerbu benteng dan kota di tepi Tuna yang berada di bawah administrasi langsung Utsmani. Menurut artikel Rusçuk TDV, pada Februari 1595 ia tidak mampu merebut benteng tetapi menduduki kota dan membakarnya. Menurut artikel İbrâil, ia merebut İbrâil di tepi kiri Tuna dan kota itu tetap di tangannya hingga 1601; artikel III. Murad juga menulis bahwa tentara Eflak membakar benteng İbrâil dan mencapai Silistre. Menurut catatan tahrir yang disebut dalam artikel Silistre, tentara Eflak melintasi Tuna pada musim semi 1595 dan menjarah Silistre; benteng kota dihancurkan dan lama tidak dapat digunakan. Pada musim panas yang sama Koca Sinan Paşa akan berangkat ekspedisi ke Eflak.", "c115852f"]},
"OLAYLAR_P0049:1603-01-01:0":{"b": ["Şah Abbas merebut kembali Tiflis — berakhirnya administrasi Utsmani di Kartli dan Kakheti", "a6995ea8"], "d": ["Şah I. Abbas merebut kembali Tiflis dari Utsmani pada 1603 dan memproklamasikan Kartli sebagai khanat; di Kakheti pun ditegakkan administrasi Safawi. Dengan demikian administrasi Utsmani di Georgia Timur, yang dimulai dengan ekspedisi Lala Mustafa Paşa pada 1578, berakhir; Tiflis baru akan jatuh kembali ke tangan Utsmani pada 1723.", "e37dcbfc"]},
"OLAYLAR_P0049:1640-01-01:0":{"b": ["Benteng Faş (Poti) dihancurkan oleh pasukan İmereti, Guria, dan Megrelya", "3c3d4ed7"], "d": ["Benteng Faş diratakan pada 1640 oleh pasukan İmereti yang diikuti para pangeran Guria dan Megrelya. Kehadiran Utsmani di muara Rioni terputus hingga benteng dibangun kembali pada 1724.", "2bb31f58"]},
"OLAYLAR_P0049:1711-04-09:0":{"b": ["Ekspedisi Prut dimulai — dalam Perang Utsmani-Rusia 1710-1711, tentara berangkat dari İstanbul", "3161364b"], "d": ["Serangan Rusia ke wilayah Utsmani, pelanggaran Tsar Petro terhadap ketentuan Perjanjian İstanbul 1700, dan dorongan Khan Krimea Devlet Giray telah membawa III. Ahmed untuk menyatakan perang terhadap Rusia. Menurut artikel III. Ahmed TDV, perang yang kemudian disebut Ekspedisi Prut ini secara nyata dimulai dengan keberangkatan tentara Utsmani dari İstanbul pada 9 April 1711. Tentara di bawah Baltacı Mehmed Paşa bergabung dengan pasukan Krimea dan maju menuju sungai Prut; ekspedisi akan berakhir pada Juli dengan terkepungnya tentara Rusia di tepi Prut.", "49618c54"]},
"OLAYLAR_P0049:1724-03-01:0":{"b": ["Pembangunan kembali Benteng Faş (Poti) dimulai", "0afbc4b0"], "d": ["Dengan keputusan 23 Desember 1723, pembangunan kembali Benteng Faş yang runtuh dimulai pada Maret 1724; pembangunan selesai pada 1729.", "e9e6b3d8"]},
"OLAYLAR_P0049:1724-05-06:0":{"b": ["Kawasan Hoy, Kapan, dan Karadağ kembali masuk ke administrasi Utsmani", "c52c94d1"], "d": ["Selama ekspedisi Iran yang dimulai pada 1723, Hoy bersama kawasan Kapan dan Karadağ kembali masuk ke administrasi Utsmani pada 6 Mei 1724 dan dicatat dalam tahrir Utsmani pada 1728. Atlas menganggap Kotur, 40 km di barat daya Hoy, juga beralih dari Safawi ke Utsmani pada hari ini (rantai diwarisi dari Hoy: Uluerler 2015, Turkish Studies 10/5, hlm. 6; hari khusus untuk Kotur tidak ada dalam sumber — pendekatan yang dinyatakan).", "eb5141eb"]},
"OLAYLAR_P0049:1733-08-17:0":{"b": ["Nâdir memasuki Şemâhî — pusat Şirvan lepas dari Utsmani", "778a4988"], "d": ["Nâdir memasuki Şemâhî, yang jatuh ke bagian Utsmani bersama bagian tengah Şirvan berdasarkan Muahedesi İstanbul 24 Juni 1724, pada 17 Agustus 1733. Administrasi Utsmani di Kaukasus sesudahnya dengan cepat runtuh; Gence dan Tiflis lepas pada 1735.", "4ab61a36"]},
"OLAYLAR_P0049:1787-07-27:0":{"b": ["Ultimatum kepada duta Rusia — langkah terakhir menuju Perang Utsmani-Rusia 1787-1792", "cb389693"], "d": ["Ketegangan yang berlanjut sejak aneksasi Krimea oleh Rusia pada 1783 putus ketika diketahui bahwa konsulat Rusia di Iskandariyah menghasut para bey kölemen di Mesir melawan Utsmani. Menurut artikel I. Abdülhamid TDV, Reîsülküttâb Süleyman Feyzi Efendi memberikan ultimatum tujuh pasal kepada duta Rusia di İstanbul pada 27 Juli 1787. Keputusan perang diambil tanpa menunggu jawaban Rusia dan diumumkan dalam beberapa pekan; sasaran perang adalah merebut kembali Krimea.", "04debfa8"]},
"OLAYLAR_P0049:1809-11-27:0":{"b": ["Pasukan Rusia merebut Benteng Faş (Poti) — muara Rioni lepas", "c1241b5a"], "d": ["Selama perang Utsmani-Rusia 1806-1812, serangan Rusia pada Mei 1809 gagal; namun benteng diserahkan kepada Rusia pada 27 November 1809.", "84e0aac2"]},
"OLAYLAR_P0049:1812-12-19:0":{"b": ["Berdasarkan Perjanjian Bükreş, Benteng Faş (Poti) dikembalikan kepada Utsmani", "6a3a8a0a"], "d": ["Berdasarkan Perjanjian Bükreş 1812, Benteng Faş diserahkan kepada Negara Utsmani pada 19 Desember 1812.", "d59bceb8"]},
"OLAYLAR_P0049:1828-06-26:0":{"b": ["Benteng Faş (Poti) jatuh ke tangan Rusia untuk kedua kalinya — tetap di Rusia dengan Perjanjian Edirne", "682d58f0"], "d": ["Pada awal perang Utsmani-Rusia 1828-1829, Benteng Faş diserahkan kepada Rusia pada 26 Juni 1828. Dengan Perjanjian Edirne 14 September 1829, Poti bersama Ahıska, Ahılkelek, dan Anapa diserahkan kepada Rusia.", "364c160c"]},
"OLAYLAR_P0049:1915-07-25:0":{"b": ["Inggris menduduki Nâsıriye — front Efrat", "669b979e"], "d": ["Pasukan Inggris yang maju dari Basra menyusuri Efrat mengalahkan pasukan Utsmani pada 24 Juli 1915 dan menduduki Nâsıriye keesokan harinya. Basra telah jatuh pada November 1914; Nâsıriye tetap di tangan Utsmani sekitar delapan bulan lagi.", "bd125229"]},
"OLAYLAR_P0049:1919-04-12:0":{"b": ["Pendudukan Kars oleh Inggris — Pemerintah Kaukasus Barat Daya dibubarkan", "9004afc9"], "d": ["Sesuai ketentuan Gencatan Senjata Mondros tentang penarikan ke perbatasan 1914, tentara Utsmani telah mengosongkan Kars. Rakyat kawasan itu mendirikan Dewan Islam Kars pada 5 November 1918 terhadap serangan Armenia dan Georgia, dan dengan kongres Januari 1919 mengubahnya menjadi Cenûb-ı Garbî Kafkas Hükûmet-i Muvakkate-i Milliyesi. Menurut artikel Kars TDV, Inggris menduduki Kars pada 12 April 1919 dan membubarkan pemerintahan ini, menangkap anggotanya dan mengirim mereka ke pengasingan, serta menyerahkan kendali kota kepada bangsa Armenia.", "06392190"]},
"OLAYLAR_P0049:1919-04-29:0":{"b": ["Pendudukan Antalya oleh Italia", "328331da"], "d": ["Setelah Gencatan Senjata Mondros, ketika negara-negara Entente menempati zona pendudukan di Anatolia, Italia mengarah ke Anatolia barat daya. Menurut artikel Antalya TDV, kota dan sekitarnya diduduki Italia pada 29 April 1919 dengan bersandar pada ketentuan gencatan senjata. Pendudukan itu akan berlangsung sekitar dua tahun.", "41127caf"]},
"OLAYLAR_P0049:1920-02-11:0":{"b": ["Pembebasan Maraş — Prancis mengosongkan kota", "a57d884e"], "d": ["Maraş, yang diduduki Inggris pada 22 Februari 1919, diserahkan kepada Prancis pada 29 Oktober 1919 berdasarkan kesepakatan kedua negara. Sikap bangsa Armenia dalam pasukan Prancis dan penurunan bendera Turki di benteng membangkitkan perlawanan rakyat; di kota dibentuk Müdâfaa-i Hukuk Cemiyeti dan Kuvâ-yi Milliye. Menurut artikel Kahramanmaraş TDV, pada akhir pertempuran Prancis mengosongkan kota pada 11 Februari 1920 dan mulai mundur ke arah İslâhiye, dan Maraş dibebaskan pada 11-12 Februari. Kota itu dianugerahi medali İstiklâl pada 1925.", "d3bff1ef"]},
"OLAYLAR_P0049:1920-04-11:0":{"b": ["Pembebasan Urfa — garnisun Prancis meninggalkan kota", "c889488c"], "d": ["Di Urfa, yang diduduki Inggris pada Maret 1919 dan sekitar tujuh bulan kemudian oleh Prancis, rakyat bangkit melawan pasukan pendudukan pada 7 Februari 1920. Menurut artikel Şanlıurfa TDV, setelah pertempuran dua bulan Prancis setuju mengosongkan Urfa dengan syarat perjanjian pada 10 April 1920 dan keluar dari kota keesokan harinya.", "88526a6f"]},
"OLAYLAR_P0049:1920-09-28:0":{"b": ["Operasi Front Timur dimulai — Kâzım Karabekir melancarkan serangan terhadap Armenia", "151678df"], "d": ["Ketika Perjanjian Sevr menyerahkan Erzurum, Trabzon, Van, Bitlis, dan Bingöl kepada Armenia dan serangan Armenia di kawasan meningkat, pemerintah TBMM mengizinkan operasi pada 20 September 1920. Menurut artikel Kâzım Karabekir TDV, Karabekir, Komandan Front Timur (Şark Cephesi), memberi perintah serangan kepada pasukannya yang menguasai celah gunung Soğanlı dan memulai operasi timur pada 28 September. Sarıkamış, Göle, dan Kağızman direbut; operasi akan berlanjut sebulan kemudian dengan pembebasan Kars.", "add8f41a"]},
"OLAYLAR_P0049:1920-10-30:0":{"b": ["Pembebasan Kars — Front Timur memasuki Kars", "4e578071"], "d": ["Menurut artikel Kars TDV, Kâzım Karabekir Paşa memasuki Kars pada 30 Oktober 1920, dan kota itu dibebaskan dari administrasi Armenia yang kendalinya ditinggalkan Inggris pada 1919. Artikel Karabekir menekankan bahwa ini adalah pembebasan kedua Kars: kota itu pertama kali direbut dari bangsa Armenia pada April 1918. Front Timur maju dan merebut Gümrü pada 7 November; perang berakhir dengan Perjanjian Gümrü pada 3 Desember 1920.", "1841f6d3"]},
"OLAYLAR_P0049:1920-11-07:0":{"b": ["Perebutan Gümrü — Front Timur maju ke pedalaman Armenia", "cfddf791"], "d": ["Pasukan Kâzım Karabekir Paşa, yang melanjutkan operasi setelah pembebasan Kars, merebut Gümrü pada 7 November 1920. Perundingan dengan bangsa Armenia yang menyetujui gencatan senjata dilakukan di Gümrü, dan perang berakhir dengan Perjanjian Gümrü yang ditandatangani pada 3 Desember 1920.", "4c34b9ce"]},
"OLAYLAR_P0049:1920-11-12:0":{"b": ["Perebutan Iğdır", "6e952d2e"], "d": ["Lima hari setelah merebut Gümrü, pada 12 November 1920, Front Timur juga merebut Iğdır. Iğdır diserahkan kepada Turki dengan Perjanjian Gümrü 3 Desember 1920.", "f96469bd"]},
"OLAYLAR_P0049:1921-02-09:0":{"b": ["Akhir pertahanan Antep — kota ditinggalkan kepada Prancis setelah bertahan sepuluh bulan", "e080af8b"], "d": ["Antep, yang dimasuki Inggris pada 17 Desember 1918, ditinggalkan kepada Prancis pada 5 November 1919; perlawanan pertama di garis Antep-Kilis dipimpin Şâhin Bey. Menurut artikel Gaziantep TDV, rakyat kota melawan pasukan Prancis dari 1 April 1920 hingga 7 Februari 1921; ketika perlawanan patah, pasukan pembela mundur dan Prancis menguasai kota pada 9 Februari. TBMM telah memberikan gelar gazi kepada kota yang bertahan sepuluh bulan melawan pendudukan itu tiga hari sebelumnya, pada 6 Februari 1921. Antep akan dikosongkan pada 25 Desember 1921 setelah Perjanjian Ankara.", "086ee824"]},
"OLAYLAR_P0049:1921-02-23:0":{"b": ["Pembebasan Ardahan dan Artvin", "b9e50d5e"], "d": ["Setelah Perjanjian Gümrü, Front Timur mengarah ke bagian elviye-i selâse yang berada di tangan Georgia. Menurut artikel Ardahan TDV, pada akhir perjuangan melawan pasukan gerilya Georgia dan Armenia, sancak Ardahan bersama Artvin dibebaskan pada 23 Februari 1921. Artikel Kâzım Karabekir menulis bahwa dengan langkah ini wilayah elviye-i selâse di luar kaza Çürüksu, Acara, dan Batum direbut kembali.", "1ee51ba4"]},
"OLAYLAR_P0049:1921-03-16:0":{"b": ["Perjanjian Moskow — TBMM dan Rusia Soviet menetapkan perbatasan timur", "78d46573"], "d": ["Perjanjian Moskow ditandatangani antara pemerintah TBMM dan Rusia Soviet pada 16 Maret 1921. Menurut artikel Kars TDV, dengan perjanjian ini dan hasil pengaturan perbatasan Perjanjian Kars 13 Oktober 1921, Kars tetap berada dalam batas negara Turki yang baru. Menurut artikel Ahıska, dengan perjanjian ini Ahıska dihubungkan dengan vilayet Tiflis dari Republik Sosialis Soviet Georgia. Perbatasan timur akan dipastikan oleh Perjanjian Kars yang ditandatangani tujuh bulan kemudian dengan republik-republik Kaukasus Selatan. Dengan perjanjian ini Batum dan Acara (Hulo, Sarp, Murvaneti, Makhalak'auri) ditinggalkan kepada Georgia Soviet.", "7951b57b"]},
"OLAYLAR_P0049:1921-06-01:0":{"b": ["Italia mulai mengosongkan Antalya", "f7a4eaa7"], "d": ["Menurut artikel Antalya TDV, pendudukan Italia yang berlangsung sejak 29 April 1919 berakhir ketika Italia mulai mengosongkan kota pada 1 Juni 1921. Antalya dan sekitarnya dengan demikian terbebas dari pendudukan tanpa menunggu hasil militer Perjuangan Nasional.", "ffd82d73"]},
"OLAYLAR_P0050:1527-01-01:0":{"b": ["Dewan Cetin — bangsawan Kroasia memilih Ferdinand dari Habsburg sebagai raja Kroasia setelah Mohaç", "55fc9d7e"], "d": ["Ketika takhta kosong dengan wafatnya II. Lajos, raja Hongaria-Kroasia, di Mohaç, bangsawan Kroasia berkumpul di Cetin pada 31 Desember 1526 dan pada hari tahun baru menyatakan Ferdinand, arsiduke Austria, sebagai raja. Dalam ungkapan TDV, bangsa Kroasia melakukan pemilihan ini terlepas dari bangsawan Hongaria; dokumen pemilihan bersandar pada alasan tidak memisahkan diri dari negara Kristen di hadapan serbuan Utsmani. Dengan demikian benteng-benteng Kroasia yang bertetangga dengan Bosnia Utsmani terikat pada mahkota dinasti Habsburg; menurut TDV, ketika Habsburg mulai menata kawasan perbatasan Kroasia pada 1530-an, pusat utama garis ini adalah Bihaç.", "5e7c69d8"]},
"OLAYLAR_P0050:1527-01-01:1":{"b": ["Administrasi Utsmani singkat atas Bihaç — setelah jatuhnya Mohaç dan Yayça", "fd4118fe"], "d": ["Setelah kemenangan Mohaç, Utsmani merebut Yayça, pusat zona penyangga Hongaria di Bosnia, dan Banaluka. Menurut artikel Bihaç TDV, setelah direbutnya Benteng Yayça pada tahun yang mengikuti Mohaç, Bihaç untuk waktu singkat kembali ke administrasi Utsmani. Sumber tidak menulis kapan dan bagaimana benteng itu lepas; TDV hanya menyebutkan bahwa pada 1530-an, ketika menata kawasan perbatasan Kroasia, Habsburg menjadikan Bihaç yang berada di tangan orang Kristen sebagai pusat utama. Penaklukan Bihaç yang permanen akan terwujud pada 1592 dengan ekspedisi Beylerbeyi Bosnia Hasan Paşa.", "3421f09a"]},
"OLAYLAR_P0050:1814-01-28:0":{"b": ["Berakhirnya administrasi Prancis di Dubrovnik — pasukan Austria memasuki kota bekas pembayar upeti Utsmani", "38d42444"], "d": ["Menurut TDV, Republik Dubrovnik yang berada di bawah perlindungan Utsmani sejak 1365 diakhiri oleh Prancis dengan merebut kota pada 27 Mei 1806. Pada musim dingin 1813-1814 rakyat kota bangkit melawan Prancis; pada 3 Januari 1814 mayor jenderal Austria Milutinović, yang datang ke Gruž dengan dua batalion Kroasia, mengepung garnisun; setelah pengeboman empat hari, garnisun Prancis mengirim utusan kepada sang jenderal. Pada fajar 28 Januari pasukan Austria dan Inggris berbaris dari Gruž ke kota; pada 31 Januari administrasi Austria sementara mulai bekerja di kawasan itu. Bergabungnya kota ke wilayah Austria dipastikan pada Kongres Wina 1815.", "bb94e4af"]},
"OLAYLAR_P0050:1882-03-06:0":{"b": ["Proklamasi Kerajaan Serbia — kepangeranan bawahan Utsmani lama berubah menjadi kerajaan", "7d90e712"], "d": ["Kepangeranan Serbia, yang meraih kemerdekaan pada 1878 dan pada tahun yang sama juga merebut Niş yang berada di tangan Utsmani, diubah menjadi kerajaan pada masa Milan Obrenović. Dengan pasal pertama undang-undang yang dikeluarkan di Belgrade, kepangeranan diproklamasikan sebagai Kerajaan Serbia dan Pangeran Milan menjadi raja dengan nama Milan I; undang-undang itu diterbitkan pada hari yang sama di surat kabar resmi Srpske novine. Dengan demikian Serbia, yang hingga 1878 adalah kepangeranan yang bergantung pada Utsmani, mengambil tempatnya di Balkan dengan gelar kerajaan. Dengan proklamasi ini seluruh Kepangeranan Serbia (Belgrade, Niş, Yagodina, İvranye, Leskofça, Ürküp, Şehirköy, dll.) menjadi Kerajaan Serbia.", "a2849d70"]},
"OLAYLAR_P0050:1920-07-01:0":{"b": ["Administrasi mandat sipil Inggris didirikan di Palestina — akhir pemerintahan militer di wilayah yang diambil dari Utsmani", "c0d7b76a"], "d": ["Dengan direbutnya Gaza dan kemudian Yerusalem oleh Jenderal Allenby pada 1917, kekuasaan Utsmani empat ratus tahun di Palestina berakhir, dan Yerusalem tetap di bawah pemerintahan militer Inggris antara 1917 dan 1920. Konferensi San Remo 1920 menyerahkan Palestina kepada mandat Inggris; sejak Juli 1920 Inggris mendirikan administrasi mandat sipil di kawasan itu dan mulai memerintah negeri itu melalui seorang komisaris tinggi. Komisaris tinggi Herbert Samuel berada di puncak administrasi sipil. Pemberontakan Arab dan bentrokan Yahudi-Arab yang dimulai pada tahun yang sama akan menandai seluruh masa mandat. Dengan peristiwa ini Tiberias (Palestina) beralih ke administrasi mandat sipil Inggris.", "bc1ec892"]},
"OLAYLAR_P0050:1922-03-15:0":{"b": ["Kerajaan Mesir diproklamasikan — Sultan Ahmed Fuâd mengambil gelar raja", "c6ad08d1"], "d": ["Inggris pada 18 Desember 1914 secara sepihak menghapus hak kedaulatan Negara Utsmani atas Mesir dan menempatkan negeri itu di bawah perlindungannya. Setelah perang, ketika perundingan antara Inggris dan Mesir tidak membuahkan hasil, Inggris pada 28 Februari 1922 kembali dengan pernyataan sepihak menyatakan Mesir sebagai negara merdeka. Sultan Ahmed Fuâd mengambil gelar raja (melik) pada 15 Maret 1922 dan monarki diproklamasikan di Mesir. TDV menganggap kemerdekaan ini bersifat formal; konstitusi tatanan kerajaan akan berlaku pada 19 April 1923.", "f9b00023"]},
"OLAYLAR_P0051:1480-01-01:0":{"b": ["Lepasnya benteng Hacıbey (Kaçibey) dari tangan Lituania", "382b51e3"], "d": ["Pelabuhan Kaçibey di pesisir barat laut Laut Hitam telah dibentengi oleh adipati agung Lituania Vytautas pada awal abad ke-15. Pada 1480 benteng lepas dari tangan Lituania dan mengambil nama Hacıbey. Pesisir itu pada akhir abad ke-15 masuk ke kendali Khanat Krimea yang tunduk pada Utsmani; penghubungan kawasan itu dengan organisasi administratif Utsmani secara langsung terjadi pada 1538.", "cea3442c"]},
"OLAYLAR_P0051:1570-01-01:0":{"b": ["Gramota IV. Ivan kepada Kazak Don — catatan tepercaya pertama Orda Kazak Don", "16c0732e"], "d": ["Informasi tentang keberadaan Kazak di Don dimulai sejak pertengahan abad ke-16. Menurut ensiklopedia militer Rusia, senioritas Orda Kazak Don dihitung dari 1570: pada tahun itu Tsar IV. Ivan mengirim gramota kepada Kazak yang hidup di Donets Utara, meminta mereka membantu Ivan Novosiltsev yang dikirim sebagai utusan lewat Azak kepada sultan Utsmani, dan menjanjikan imbalan. Ini adalah catatan tepercaya pertama tentang pengabdian Kazak Don kepada negara Moskow. Pusat utama Kazak mula-mula Razdory Atas, kemudian Çerkassk.", "3ce37828"]},
"OLAYLAR_P0051:1585-01-01:0":{"b": ["Moskow mendirikan garnisun terdepan di Voronezh menghadapi stepa", "89c941fe"], "d": ["Pada akhir abad ke-16, Sloboda Ukraina masa kini dan daerah aliran atas Don adalah stepa liar yang sepi, tempat bangsa Tatar melintas dalam serbuan ke Moskow. Pemerintah Moskow mendirikan serangkaian garnisun terdepan di stepa ini; Voronezh didirikan sebagai salah satunya pada 1585. Benteng ini, bersama Belgorod dan Kursk, menjadi mata rantai pertama garis pertahanan selatan Moskow pada dekade-dekade berikutnya.", "ceb11b6b"]},
"OLAYLAR_P0051:1596-01-01:0":{"b": ["Moskow mendirikan Belgorod, Oskol, dan Kursk sebagai garnisun terdepan di stepa", "4ff3e225"], "d": ["Pemerintah Moskow memajukan perbatasan selatan terhadap serbuan Krimea dan pada 1596 mendirikan Belgorod, Oskol, dan Kursk sebagai titik garnisun di stepa liar. Belgorod sejak tanggal ini menjadi kota benteng dan menjadi pusat garis pertahanan Belgorod sepanjang 300 kilometer yang akan membentang pada abad berikutnya.", "50cb899c"]},
"OLAYLAR_P0052:1884-01-01:0":{"b": ["Sancak Siirt dipindahkan dari Diyarbekir ke vilayet Bitlis — kaza Eruh dan desa Şırnak juga dihubungkan dengan Bitlis", "3922d040"], "d": ["Ketika beralih dari sistem eyalet ke sistem vilayet setelah Tanzimat, sancak Siirt yang tetap bergantung pada vilayet Diyarbekir dipindahkan ke vilayet Bitlis pada 1884. Menurut artikel Şırnak TDV, tanah tempat Şırnak masa kini berada dengan demikian juga berada dalam kaza Eruh yang bergantung pada sancak Siirt vilayet Bitlis. Pada saat itu Şırnak adalah desa kecil kaza Eruh; namanya tampak dalam catatan menjelang akhir abad XIX, sedangkan statusnya sebagai pusat kaza baru terjadi pada tahun-tahun awal Republik. Tanah-tanah ini telah bergabung ke Utsmani pada 1514 setelah Ekspedisi Çaldıran dan diadministrasikan dalam sancak Siirt eyalet Diyarbekir.", "1539b089"]},
"OLAYLAR_P0053:1624-01-01:0":{"b": ["Mosul dan Kirkuk jatuh ke tangan Safawi — setelah jatuhnya Bagdad", "86e176c8"], "d": ["Şah Abbas, yang merebut Bagdad pada akhir peristiwa yang dimulai dengan pemberontakan Bekir Subaşı, mengirim komandannya Karçakay Han dengan pasukannya ke Mosul dan Kirkuk. Gubernur Mosul Çerkez Ahmed Paşa hanya dapat mempertahankan kota beberapa hari; seperti Kirkuk, Mosul jatuh ke kekuasaan Iran dan Kāsım Han ditunjuk sebagai gubernur. Ketika Sipahi Küçük Ahmed, yang memimpin pasukan pelopor Hâfız Ahmed Paşa, tampak di depan Mosul, Kāsım Han meninggalkan kota dan mundur ke Bagdad, tetapi dengan operasi balasan Şah Abbas Mosul kembali jatuh ke tangan Safawi pada 1624.", "81474bd6"]},
"OLAYLAR_P0053:1625-01-01:0":{"b": ["Pembebasan Mosul dari Safawi — ekspedisi Bagdad Hâfız Ahmed Paşa", "1f9ca4a1"], "d": ["IV. Murad mengirim tentara di bawah Vezîriâzam Hâfız Ahmed Paşa ke Bagdad. Ketika tentara berada di sekitar Diyarbekir, pasukan pelopor Beylerbeyi Karaman Çerkez Hasan mengejar para pendukung Iran yang berkumpul di Altınköprü hingga Kirkuk dan menguasai kawasan termasuk Kirkuk; Safawi kali ini pun tidak dapat menahan Mosul untuk waktu lama. Hâfız Ahmed Paşa pada awal September tiba pertama di Mosul, kemudian di Kirkuk, dan mengepung Bagdad pada 13 November 1625; pengepungan tidak membuahkan hasil dan Bagdad tetap di tangan Safawi. Artikel Kirkuk TDV sebaliknya mengaitkan direbutnya kembali kota dari Safawi dengan Hüsrev Paşa pada 1630.", "ad32f3ae"]},
"OLAYLAR_P0053:1630-03-16:0":{"b": ["Hüsrev Paşa membangun kembali Benteng Gülanber di Şehrizor — beylerbeyilik Şehrizor", "9511853c"], "d": ["Sadrazam Hüsrev Paşa, yang berangkat ke ekspedisi Bagdad, setelah lama tinggal di Mosul karena hujan lebat mengarah ke Şehrizor. Pembangunan kembali Benteng Gülanber, yang dirobohkan atas perintah Şah Abbas pada invasinya, dimulai; Şehrizor dijadikan lagi pusat beylerbeyilik dan Arnavud Mustafa Paşa ditinggalkan di benteng sebagai beylerbeyi. Hüsrev Paşa menundukkan suku-suku di kawasan itu, merebut Benteng Mihriban, dan pada 5 Mei 1630 menimbulkan kerugian berat pada tentara Safawi di dekat benteng ini.", "ff2c7cea"]},
"OLAYLAR_P0055:1369-01-01:0":{"b": ["Timurtaş Bey merebut Kızılcaağaç Yenicesi (Elhova) dan Yanbolu di lembah Tunca", "2c2aebea"], "d": ["Selama operasi I. Murad terhadap Bulgaria dan Bizantium, Kara Timurtaş Bey dikirim ke lembah Tunca; ia merebut Kızılcaağaç Yenicesi dan Yanbolu serta kembali ke Edirne dengan banyak rampasan.", "e2ca7962"]},
"OLAYLAR_P0055:1371-09-26:0":{"b": ["Kepangeranan Dejanović (Kostadin-ili) menjadi vasal Utsmani", "54b8dd6c"], "d": ["Ketika negara Serbia pecah dengan kekalahan Meriç (Çirmen), dua bersaudara Jovan dan Konstantin Dejanović mendirikan kepangeranan mereka sendiri yang berpusat di Velbujd (kemudian bernama Köstendil) dan mencakup İştip, Ustrumca, Doyran, dan kawasan Köprülü. Dengan wafatnya Jovan tak lama kemudian, Konstantin mengakui kekuasaan I. Murad dan menjadi vasal Utsmani; kepangeranan hidup semi-merdeka dengan ikatan ini. Ketika Konstantin gugur di barisan Yıldırım Bayezid di Rovine pada 1395, negerinya masuk ke administrasi Utsmani tanpa perang dan menjadi sancak dengan nama Kostadin-ili.", "25fd68b1"]},
"OLAYLAR_P0055:1412-01-01:0":{"b": ["Despot Serbia Stefan Lazarević merebut Şehirköy (Pirot)", "87e1ecb3"], "d": ["Ketika perjuangan antara Mûsâ Çelebi, yang menguasai Rumeli pada Masa Fetret, dan saudaranya Çelebi Mehmed berlanjut, Despot Serbia Stefan Lazarević merebut benteng Şehirköy yang terletak di jalan antara Niş dan Sofia, dan mempertahankannya terhadap serangan Mûsâ Çelebi. Pada tahun berikutnya dengan wafatnya Mûsâ, Çelebi Mehmed secara resmi menyerahkan benteng kepada vasalnya Stefan; Utsmani baru merebut kembali Şehirköy pada 1428 setelah wafatnya Lazarević.", "f50a8066"]},
"OLAYLAR_P0055:1538-01-01:0":{"b": ["Herseknovi (Castelnuovo) direbut oleh Andrea Doria", "a8276ff1"], "d": ["Andrea Doria, komandan armada sekutu yang bersatu melawan Utsmani, merebut benteng Herseknovi (Castelnuovo) di pesisir Adriatik, di selatan Dalmatia. Pada tahun yang sama di Dalmatia bangsa Venesia juga merebut beberapa kota yang berada di tangan Utsmani, dan pasukan Utsmani membalas dengan benteng-benteng lain. Benteng direbut kembali setahun kemudian; karena kedaulatan Utsmani secara hukum berlanjut, masa selingan ini ditunjukkan di peta dengan lapisan pendudukan yang diarsir.", "a9462728"]},
"OLAYLAR_P0055:1539-08-10:0":{"b": ["Perebutan kembali Herseknovi (Castelnuovo) oleh Barbaros Hayreddin Paşa", "1e5b49ae"], "d": ["Utsmani, yang setelah kemenangan Preveze juga meraih keunggulan di Mediterania Tengah, mengarah ke benteng Nova (Castelnuovo) di pesisir Adriatik yang direbut Andrea Doria setahun sebelumnya. Pada akhir operasi yang dijalankan bersama oleh Barbaros Hayreddin Paşa dan Bey Bosnia Gazi Hüsrev Bey, benteng direbut kembali dan pendudukan berakhir.", "29e2c28b"]},
"OLAYLAR_P0055:1798-12-25:0":{"b": ["Ekspedisi Mesir Hulu Desaix — divisi Prancis mencapai Minye, Asyut, dan Girga", "8ff8e4fe"], "d": ["Ketika Napoleon berada di Kairo, divisi Jenderal Desaix mengejar pasukan Mamluk dan maju ke selatan di lembah Nil: tiba di Minye pada 21 Desember 1798, di Asyut pada hari Natal, dan di Girga pada 29 Desember. Dengan pawai ini yang mencapai Aswan pada Februari 1799, lembah antara Kairo dan Aswan masuk ke kendali Prancis.", "96ddd684"]},
"OLAYLAR_P0055:1799-02-18:0":{"b": ["Napoleon menduduki Arîş — awal ekspedisi Suriah", "69dc52ce"], "d": ["Tentara Prancis yang menduduki Mesir merebut Arîş di pesisir Sinai ketika berbaris ke Suriah.", "8feb359c"]},
"OLAYLAR_P0055:1799-12-28:0":{"b": ["Perebutan kembali Arîş dari Prancis", "c25e48a7"], "d": ["Arîş, yang diduduki Napoleon pada Februari 1799, direbut kembali oleh tentara Sadrazam Yûsuf Ziyâ Paşa pada akhir Desember tahun yang sama.", "3bde687a"]},
"OLAYLAR_P0056:1739-08-28:0":{"b": ["Kekalahan Stavuçani dan penyerahan Hotin kepada Rusia (Perang Utsmani-Rusia 1736-1739)", "657d82d2"], "d": ["Dalam ekspedisi 1739, tentara utama Rusia di bawah komando Marsekal Münnich melintasi wilayah Polandia dan memasuki Boğdan, dan menimbulkan kekalahan berat pada tentara Serasker Veli Paşa di Stavuçani dekat Hotin. Segera setelah pertempuran ini benteng Hotin menyerah kepada Rusia dan pasukan Rusia memasuki Yaş pada awal September. Namun karena Austria membuat perdamaian terpisah, perang berakhir dengan Perjanjian Belgrade yang ditandatangani pada bulan yang sama.", "2e7457b9"]},
"OLAYLAR_P0056:1769-01-01:0":{"b": ["Tentara Rusia melintasi Dniester dan memasuki Boğdan (Perang Utsmani-Rusia 1768-1774)", "938bd834"], "d": ["Sekitar enam bulan setelah deklarasi perang, tentara utama Rusia berkumpul di Podolia di bawah komando Pangeran Golitsin. Atas seruan metropolit Boğdan Dositey untuk menempatkan Moldova di bawah perlindungan Rusia, Golitsin melintasi Dniester dan mencoba merebut Hotin sebelum berbaris ke Yaş. Percobaan pertama ini gagal, tentara kembali ke Podolia karena kekurangan perbekalan; Hotin baru jatuh pada September 1769.", "df52a8ec"]},
"OLAYLAR_P0056:1788-01-01:0":{"b": ["Tentara Ukraina Rusia melintasi Dniester di Mogilev dan memasuki Boğdan (Perang Utsmani-Rusia 1787-1792)", "822c7361"], "d": ["Dalam perang yang dimulai dengan deklarasi perang Utsmani pada 1787, Rusia membentuk dua tentara: tentara Potemkin mengepung Özi, sedangkan tentara Ukraina Rumyantsev akan mengancam Bender antara Dniester dan Bug serta menjaga hubungan dengan Austria. Rumyantsev memisahkan satu kolom untuk mendukung bangsa Austria yang mengepung Hotin, dan dengan pasukan utamanya melintasi Dniester di Mogilev dan memasuki Boğdan. Dengan demikian dimulailah cabang Boğdan dari operasi Rusia yang akan meluas hingga İsmail dan Tuna.", "7c701213"]},
"OLAYLAR_P0056:1806-11-23:0":{"b": ["Tentara Rusia melintasi Dniester tanpa deklarasi perang dan mulai menduduki Memleketeyn (Perang Utsmani-Rusia 1806-1812)", "2094a4d9"], "d": ["Pada Oktober 1806 Jenderal Michelson diperintahkan menduduki Boğdan dan Eflak; perang belum diumumkan secara resmi. Pasukan Rusia mulai melintasi Dniester dan para komandan benteng Hotin, Bender, Akkirman, dan Kili menyerahkan benteng mereka tanpa pertempuran. Hanya komandan İsmail yang tidak tunduk pada bujukan Rusia. Deklarasi perang Bâbıâli datang setelah pendudukan ini.", "c770c2b4"]},
"OLAYLAR_P0056:1806-11-30:0":{"b": ["Perebutan Akkirman oleh Rusia (1806)", "25aed8d6"], "d": ["Seminggu setelah tentara Rusia melintasi Dniester tanpa deklarasi perang, Akkirman direbut oleh pasukan Pangeran Kantakuzino; bangsa Tatar di kota meninggalkan kota. Akkirman diserahkan kepada Rusia bersama Besarabia dengan Perjanjian Bükreş 1812.", "1e7e3f9e"]},
"OLAYLAR_P0056:1806-12-25:0":{"b": ["Miloradovich memasuki Bükreş — pendudukan Rusia atas Eflak", "62e4a8e1"], "d": ["Ketika tentara Rusia memasuki Boğdan, Mustafa Paşa, komandan Rusçuk, mengirim pasukan ke Bükreş dan pasukan itu menguasai kota. Detasemen Jenderal Miloradovich mengeluarkan mereka dari kota; pasukan Utsmani mundur ke Yergöğü. Bükreş sejak tanggal ini tetap di bawah pendudukan Rusia hingga Perjanjian Bükreş 1812.", "217aa20b"]},
"OLAYLAR_P0056:1810-06-10:0":{"b": ["Penyerahan Silistre kepada Rusia", "d687d04b"], "d": ["Silistre, yang bertumpu pada pengepungan Bagration pada musim gugur 1809, dikepung kembali dalam ekspedisi 1810 atas perintah panglima Kamenski. Pekerjaan pengepungan yang dimulai pada akhir Mei berlangsung beberapa hari dan benteng menyerah dengan syarat garnisun keluar dengan bebas. Pada hari-hari yang sama Pazarcık direbut dengan serbuan dan Hezargrad jatuh. Rusia menahan Silistre setahun; pada musim semi 1811 Kutuzov meledakkan tembok dan meninggalkan benteng.", "56cdb224"]},
"OLAYLAR_P0056:1810-10-01:0":{"b": ["Penyerahan Niğbolu dan Kule (Turnu) kepada Rusia tanpa perlawanan", "e297a862"], "d": ["Setelah Rusçuk dan Yergöğü menyerah, panglima Kamenski berbaris ke barat menyusuri sungai untuk merebut benteng-benteng Tuna hingga perbatasan Serbia. Niğbolu dan Kule di tepi seberang menyerah tanpa perlawanan; detasemen Rusia merebut Plevne, Lofça, dan Selvi serta meruntuhkan benteng-bentengnya. Rusia menahan Niğbolu enam bulan dan meninggalkannya dengan meledakkan benteng pada April 1811.", "f77715d7"]},
"OLAYLAR_P0056:1811-07-04:0":{"b": ["Pertempuran Rusçuk dan mundurnya Kutuzov ke tepi kiri Tuna setelah meruntuhkan Rusçuk", "6af4bf85"], "d": ["Perdana menteri yang berangkat dari Şumnu pada awal Juni menyerang tentara Rusia di depan Rusçuk, kalah, dan mundur ke posisi berbentengnya di selatan. Meskipun menang dalam pertempuran ini, Kutuzov menganggap tetap tinggal di Rusçuk berbahaya; ia meruntuhkan benteng pertahanan kota dan memindahkan seluruh pasukannya ke tepi kiri Tuna. Perdana menteri merebut kembali Rusçuk yang dikosongkan. Dengan demikian cengkeraman Rusia di kota yang diterima Kaminski pada 26 September 1810 setelah pengepungan berdarah berlangsung sembilan bulan. Menurut catatan TDV, sebelum pergi Kutuzov memerintahkan peledakan benteng pertahanan di sekitar kota dan benteng abad pertengahan; dalam kebakaran yang timbul, dua belas dari tiga puluh delapan masjid jami yang ada di kota pada 1810 dan dua dari delapan mescid hancur seluruhnya. Pada musim gugur tahun yang sama, melintasnya tentara Utsmani di Tuna akan berujung pada pengepungan Slobozia.", "3b247b6b"]},
"OLAYLAR_P0056:1828-05-07:0":{"b": ["Korps Infanteri ke-6 Rusia melintasi Prut dan memasuki Memleketeyn (Perang Utsmani-Rusia 1828-1829)", "9d9aaaad"], "d": ["Setelah deklarasi perang Rusia, tentara Marsekal Wittgenstein memulai operasi. Korps Infanteri ke-6 melintasi Prut dan memasuki Boğdan serta Eflak; pelopornya di bawah komando Jenderal Geismar mengarah ke Eflak Kecil. Beberapa hari kemudian Korps ke-7 mengepung İbrail; Korps ke-3 bersiap melintasi Tuna antara İsmail dan Reni. Memleketeyn akan tetap di bawah pendudukan Rusia hingga 1834.", "cba5d549"]},
"OLAYLAR_P0056:1829-06-30:0":{"b": ["Penyerahan Silistre kepada Diebitsch — pendudukan Rusia yang akan berlangsung hingga 1836", "55e28ab1"], "d": ["Pada awal ekspedisi 1829, panglima Rusia yang baru, Diebitsch, memilih Silistre sebagai sasaran pertama. Garnisun melawan dengan gigih pekerjaan pengepungan yang dipimpin Jenderal Schilder; Diebitsch meninggalkan sebagian pasukannya di pengepungan dan berbaris ke belakang perdana menteri. Pengepungan berlanjut dan benteng menyerah. Rusia menahan Silistre hingga 1836 bahkan setelah perang usai.", "4c1a9e8e"]},
"OLAYLAR_P0056:1836-01-01:0":{"b": ["Rusia mengosongkan Silistre", "4fe2afaf"], "d": ["Setelah Perjanjian Edirne 1829, Rusia tidak mengosongkan Silistre dan menahan benteng hingga 1836. Setelah tentara Rusia mundur, gubernur Selim Paşa membangun sebuah masjid besar berkubah tunggal di tengah kota yang setengah hancur.", "39444f60"]},
"OLAYLAR_P0056:1853-07-03:0":{"b": ["Tentara Rusia melintasi Prut dan mulai menduduki Memleketeyn (Eflak-Boğdan) — jalan menuju Perang Krimea", "77862041"], "d": ["Ketika tuntutan Menshikov dalam sengketa tempat-tempat suci di Yerusalem ditolak oleh Bâbıâli, Tsar I. Nikolai memerintahkan pendudukan beylik-beylik Tuna yang tunduk pada Utsmani 'sebagai jaminan hingga Turki memenuhi tuntutan kami yang sah'. Pelopor tentara di bawah komando Pangeran Gorchakov melintasi Prut dan dua belas hari kemudian memasuki Bükreş; setelahnya pasukan utama menyebar ke beylik dalam tiga kolom. Pendudukan yang dilakukan tanpa deklarasi perang ini menyebabkan krisis diplomatik di Eropa dan pada Oktober 1853 deklarasi perang Utsmani; Rusia baru mengosongkan beylik pada musim panas 1854 di bawah tekanan Austria.", "04443242"]},
"OLAYLAR_P0057:1442-01-16:0":{"b": ["Müşa'şa'î menetap di Havîza — pemerintahan Müşa'şa' dimulai di Huzistan", "674d0173"], "d": ["Muhammed b. Felâh, yang muncul dengan klaim Mehdî, setelah bertahan di antara suku-suku Meâdî, berhasil menetap di Havîza yang berada di bawah kendali Timurid pada tahun berikutnya. Kota itu menjadi pusat dinasti Müşa'şa'î yang akan berkuasa di Huzistan.", "53937c8f"]},
"OLAYLAR_P0057:1508-05-02:0":{"b": ["Şah İsmâil menghubungkan Havîza — Müşa'şa'î menjadi gubernur bawahan Safawi", "7e245f4d"], "d": ["Şah İsmâil membunuh sebagian anggota dinasti Müşa'şa' yang dituduhnya zindik dan menghubungkan kawasan Havîza dengan administrasinya sendiri. Para pemimpin Müşa'şa' sesudahnya melanjutkan keberadaan mereka sebagai gubernur bawahan Safawi.", "ee776160"]},
"OLAYLAR_P0057:1534-01-01:0":{"b": ["Benteng Pasin, Şüregel, dan Oltu direbut dari Safawi — antara Erzurum dan Kars", "68f297aa"], "d": ["Selama Ekspedisi Irakeyn Kanûnî Sultan Süleyman, benteng-benteng Pasin, Şüregel, dan Oltu antara Erzurum dan Kars direbut dari Safawi.", "06909003"]},
"OLAYLAR_P0057:1557-04-02:0":{"b": ["Özdemir Paşa merebut pelabuhan Masavva'", "4cc1d4ad"], "d": ["Özdemir Paşa, beylerbeyi Eyalet Habeş, setelah merebut kepulauan Dehlek, merebut kota Masavva' di pesisir seberang pada 2 April 1557; setelah itu Arkîko juga masuk ke administrasi Utsmani. Dengan demikian pelabuhan utama Habasyah yang terbuka ke Laut Merah jatuh ke tangan Utsmani.", "7c5e89f0"]},
"OLAYLAR_P0057:1793-01-31:0":{"b": ["Bergabungnya County Nice ke Prancis", "a140cab2"], "d": ["Setelah bergabungnya Savoy pada November 1792, Konvensi Nasional Prancis mengesahkan bergabungnya County Nice milik Kerajaan Sardinia ke Prancis pada 31 Januari 1793; kawasan itu menjadi departemen Alpes-Maritimes. Nice dikembalikan kepada Sardinia dengan Perjanjian Paris I tertanggal 30 Mei 1814 setelah kekalahan Napoleon.", "b313c90b"]},
"OLAYLAR_P0057:1917-01-09:0":{"b": ["Pertempuran Refah — kavaleri Inggris-Anzac merebut posisi Mağrunteyn dan Refah", "5053c8ef"], "d": ["Divisi Berkuda Anzac Pasukan Ekspedisi Mesir yang melintasi Sînâ, brigade Korps Unta Imperial, dan brigade yeomanry Inggris menyerang posisi Utsmani yang diduduki dengan tabya di Mağrunteyn, sekitar satu kilometer di selatan Refah. Setelah pertempuran sengit, terobosan bangsa Selandia Baru dan pasukan unta meruntuhkan pertahanan Utsmani; posisi itu dan Refah di dekatnya direbut dan pasukan Inggris mencapai perbatasan Palestina.", "7f90289f"]},
"OLAYLAR_P0057:1918-03-12:0":{"b": ["Operasi musim dingin Kâzım Karabekir: Hasankale (Pasinler) direbut kembali bersama Erzurum", "27df4879"], "d": ["Pasukan Utsmani di bawah Kâzım Karabekir Paşa, yang memulai operasi di timur setelah runtuhnya tentara Rusia, merebut kembali Erzincan, Erzurum, dan Hasankale di timur Erzurum meskipun kondisi musim dingin yang berat; kemajuan mencapai Kars pada 25 April 1918.", "80a72c73"]},
"OLAYLAR_P0057:1919-01-23:0":{"b": ["Pendudukan Eskişehir oleh Inggris", "8e349037"], "d": ["Setelah Gencatan Senjata Mondros, negara-negara Entente mulai menguasai simpul-simpul kereta api Anatolia. Menurut artikel Eskişehir TDV, kota diduduki Inggris pada 23 Januari 1919. Pasukan Inggris mengosongkan Eskişehir pada 20 Maret 1920.", "5bb8774d"]},
"OLAYLAR_P0057:1919-05-11:0":{"b": ["Pendaratan Italia di pesisir Anatolia Barat Daya — Marmaris, Bodrum, Kuşadası", "15d6fb7a"], "d": ["Italia, yang menarik diri dari Konferensi Perdamaian Paris untuk memprotes sikap sekutunya yang pro-Yunani, mendaratkan pasukan di pesisir barat daya setelah Antalya. Menurut TDV, Marmaris mengalami pendudukan Italia pada 5 Mei, Bodrum pada 11 Mei, dan Kuşadası pada 13 Mei. Pada hari-hari yang sama bangsa Yunani juga mendarat di Fethiye; persaingan kedua negara atas Anatolia Barat menyiapkan jalan menuju pendudukan İzmir.", "82266143"]},
"OLAYLAR_P0057:1919-05-26:0":{"b": ["Pasukan Yunani memasuki Manisa dan Aydın", "a4230775"], "d": ["Tentara Yunani yang mendarat di İzmir pada 15 Mei dalam waktu singkat menyebar ke pedalaman. Menurut artikel Manisa TDV, pasukan Yunani memasuki kota pada 26 Mei 1919; menurut artikel Aydın, Aydın diduduki keesokan harinya, 27 Mei. Pendudukan Manisa akan berlangsung hingga September 1922.", "514ead8b"]},
"OLAYLAR_P0057:1919-06-28:0":{"b": ["Pendudukan Burdur oleh Italia — mundurnya kompi yang mengarah ke Isparta", "874e9d6d"], "d": ["Italia, yang menduduki Antalya, maju ke wilayah pedalaman. Menurut artikel Isparta TDV, pasukan Italia menduduki Burdur pada 28 Juni dan pada 15 Agustus mengarah ke Isparta dengan satu kompi tentara. Ketika rakyat Isparta menolak tawaran penyerahan senjata dan menyatakan akan melawan, Italia mundur keesokan harinya.", "35806188"]},
"OLAYLAR_P0057:1919-06-30:0":{"b": ["Pembebasan singkat Aydın dan pendudukan ulang pada 4 Juli", "753c739f"], "d": ["Pasukan nasional diorganisasi di sekitar Ödemiş, Nazilli, dan Aydın melawan pendudukan Yunani. Menurut artikel Aydın TDV, kota yang diduduki pada 27 Mei 1919 dibebaskan untuk waktu singkat pada 30 Juni, tetapi pada 4 Juli kembali mengalami pendudukan Yunani. Kota itu sesudahnya tetap di bawah pendudukan hingga 7 September 1922.", "a0031b01"]},
"OLAYLAR_P0057:1919-07-23:0":{"b": ["Pendudukan Muğla oleh Italia", "a4f5a926"], "d": ["Italia memperluas pendudukannya di pesisir barat daya ke wilayah pedalaman. Menurut artikel Muğla TDV, kota mengalami pendudukan Italia pada 23 Juli 1919. Pendudukan Muğla berlangsung hingga 5 Juli 1921.", "b77c243c"]},
"OLAYLAR_P0057:1919-10-15:0":{"b": ["Dimulainya administrasi militer Prancis di Trakia Barat", "5801e6de"], "d": ["Trakia Barat, yang berada di tangan Bulgaria yang kalah dalam Perang Dunia Pertama, ditempatkan di bawah kendali negara-negara Entente selama perundingan perdamaian berlangsung. Menurut artikel Trakia Barat TDV, kawasan itu diduduki pasukan Prancis pada 15 Oktober 1919; Müdâfaa-i Hukuk Cemiyeti Trakia Barat memindahkan pusatnya ke Gümülcine pada masa ini. Administrasi Prancis berlangsung hingga kawasan itu diserahkan kepada Yunani pada Mei 1920 dengan keputusan San Remo.", "58f44e3a"]},
"OLAYLAR_P0057:1920-03-20:0":{"b": ["Inggris mengosongkan Eskişehir", "6820e164"], "d": ["Eskişehir, yang berada di bawah pendudukan Inggris sejak Januari 1919, dikosongkan oleh Inggris pada 20 Maret 1920 menurut artikel Eskişehir TDV. Beberapa bulan kemudian, pada Juni 1920, kota menjadi pusat Front Barat yang dibentuk TBMM.", "5f817d34"]},
"OLAYLAR_P0057:1920-06-22:0":{"b": ["Serangan musim panas Yunani — pendudukan Akhisar, Soma, Balıkesir, dan Alaşehir", "f096d2b4"], "d": ["Dengan sekutu memberi izin kepada tentara Yunani untuk maju melewati garis Milne, serangan besar Yunani dimulai di Anatolia Barat. Menurut artikel Millî Mücadele TDV, pasukan Yunani yang bergerak dalam tiga kolom pada 22 Juni merebut Akhisar, Kırkağaç, Soma, dan Balıkesir. Di selatan, Alaşehir diduduki pada 26 Juni dan Nazilli pada 3 Juli.", "bb4b4b94"]},
"OLAYLAR_P0057:1920-07-08:0":{"b": ["Pendudukan Bursa oleh Yunani", "7c2b32a1"], "d": ["Kolom utara serangan musim panas mengarah ke Marmara setelah Balıkesir. Menurut artikel Bursa dan Millî Mücadele TDV, Bursa mengalami pendudukan Yunani pada 8 Juli 1920. Penghinaan terhadap makam-makam para penguasa Utsmani pertama menimbulkan reaksi besar di seluruh negeri.", "2f040dcd"]},
"OLAYLAR_P0057:1920-07-20:0":{"b": ["Pendudukan Trakia Timur oleh tentara Yunani — Edirne dan Kırklareli", "9eb3bda1"], "d": ["Yunani, sebelum Perjanjian Sevr ditandatangani, mulai merebut Trakia Timur secara nyata juga. Menurut artikel Millî Mücadele TDV, tentara Yunani merebut seluruh Trakia pada 20 Juli; perkembangan ini mendorong padişah di İstanbul untuk memanggil Dewan Kesultanan dua hari kemudian. Kırklareli mengalami pendudukan pada 26 Juli, dan Edirne juga masuk ke administrasi Yunani pada bulan yang sama.", "4c68dd1f"]},
"OLAYLAR_P0057:1920-07-28:0":{"b": ["Tentara Merah memasuki Nahçıvan", "6dcb9005"], "d": ["Inggris, yang memasuki kawasan itu pada awal 1919, membubarkan Republik Aras dan meninggalkan Nahçıvan pada musim panas tahun yang sama. Menurut artikel Nahçıvan TDV, Tentara Merah memasuki Nahçıvan pada 28 Juli 1920 dan menyerahkan administrasi kepada kaum komunis, dan Republik Sosialis Soviet Nahçıvan didirikan. Status kawasan itu ditetapkan pada 1921 dengan perjanjian yang ditandatangani di Kars sebagai satuan otonom yang bergantung pada Azerbaijan.", "bc49ebba"]},
"OLAYLAR_P0057:1920-08-29:0":{"b": ["Pendudukan Uşak oleh Yunani", "74ad2713"], "d": ["Tentara Yunani melanjutkan kemajuannya untuk memaksakan Perjanjian Sevr, yang tidak diakui Ankara. Menurut artikel Uşak dan Millî Mücadele TDV, setelah Gediz, Uşak juga diduduki pada 29 Agustus 1920. Mustafa Kemal Paşa telah memeriksa pasukan Kuvâ-yi Milliye di kota itu sekitar sebulan sebelum pendudukan ini.", "b7c70a40"]},
"OLAYLAR_P0057:1920-10-25:0":{"b": ["Pendudukan İnegöl dan Yenişehir oleh Yunani", "4a0460e7"], "d": ["Pasukan Yunani di Bursa mulai maju ke timur, ke arah Eskişehir. Menurut artikel Millî Mücadele TDV, İnegöl dan Yenişehir direbut pada 25 Oktober 1920. Ketika dipahami bahwa kemajuan Yunani tidak dapat dihentikan dengan pasukan milisi, front barat diorganisasi ulang berdasarkan tentara reguler.", "53e977e3"]},
"OLAYLAR_P0057:1921-01-01:0":{"b": ["Berakhirnya pendudukan Italia atas Burdur (tahun)", "609123c8"], "d": ["Burdur, yang diduduki Italia pada 28 Juni 1919, mengalami pendudukan Italia singkat antara 1919-1921 menurut artikel Burdur TDV. Sumber tidak memberikan hari pengosongan; di peta pendudukan berakhir pada awal tahun 1921. Italia sepenuhnya mundur dari zona pendudukannya di Anatolia pada musim panas 1921.", "0ac33ff9"]},
"OLAYLAR_P0057:1921-03-23:0":{"b": ["Serangan kedua tentara Yunani — pendudukan Bilecik, Afyon, dan Adapazarı", "9ae146e2"], "d": ["Tentara Yunani, yang mendaratkan pasukan baru di İzmir setelah kekalahan İnönü Pertama, kembali melancarkan serangan sebelum tenggat yang diakui Konferensi London habis. Menurut artikel Millî Mücadele TDV, bangsa Yunani menduduki Bilecik dan Afyon pada 23 Maret. Di utara Adapazarı juga mengalami pendudukan Yunani pada 25 Maret.", "7d247e77"]},
"OLAYLAR_P0057:1921-03-28:0":{"b": ["Pasukan Turki mengosongkan Batum", "ba5745dc"], "d": ["Ketika Inggris mundur dari Kaukasus pada Juli 1920, mereka mengosongkan Batum dan kota itu diambil alih pemerintah Georgia. Menurut artikel Batum TDV, Perjanjian Moskow yang ditandatangani dengan Rusia Soviet pada 16 Maret 1921 menyerahkan Batum kepada Georgia. Pasukan Turki mengosongkan kota pada 28 Maret 1921 dan Batum menjadi pusat Republik Otonom Acara yang didirikan di dalam Georgia.", "9555d8e0"]},
"OLAYLAR_P0057:1921-04-07:0":{"b": ["Perebutan kembali Afyon — pertempuran Aslıhanlar", "2bbba17b"], "d": ["Setelah serangan Yunani dihentikan di İnönü Kedua pada 1 April, Afyon direbut kembali di front selatan pada 7 April. Artikel Millî Mücadele TDV meringkasnya dengan 'dikalahkan telak di Aslıhanlar dan Afyon direbut kembali pada 7 April'; namun kajian sejarah militer menempatkan pertempuran Aslıhanlar-Dumlupınar setelah pengosongan Afyon, antara 8-15 April, dan menulis bahwa keunggulan taktis tetap di pihak Yunani — kedua penuturan tidak cocok, keduanya diberikan. Kemenangan İnönü dirayakan dengan rapat umum di seluruh negeri, terutama di İstanbul.", "3525b97a"]},
"OLAYLAR_P0057:1921-06-28:0":{"b": ["Pembebasan İzmit — setelah Adapazarı", "cec60e36"], "d": ["Adapazarı, yang mengalami pendudukan Yunani pada Maret 1921, direbut kembali pada 21 Juni menurut artikel Adapazarı TDV. Menurut artikel İzmit TDV, İzmit, yang diduduki pertama oleh Inggris kemudian oleh Yunani pada 6 Juli 1920, dibebaskan pada 28 Juni 1921. Bangsa Yunani membakar bagian pasar ketika meninggalkan kota.", "da5f0806"]},
"OLAYLAR_P0057:1921-07-05:0":{"b": ["Pembebasan Muğla dari pendudukan Italia", "143ddf98"], "d": ["Italia mulai mundur dari zona pendudukannya di Anatolia pada musim panas 1921; pengosongan Antalya telah dimulai pada 1 Juni. Menurut artikel Muğla TDV, Muğla, yang berada di bawah pendudukan Italia sejak 23 Juli 1919, dibebaskan pada 5 Juli 1921.", "84bff82f"]},
"OLAYLAR_P0057:1921-07-20:0":{"b": ["Pengosongan Eskişehir — tentara Yunani memasuki Eskişehir, Kütahya, dan Bilecik", "a948a74d"], "d": ["Tentara Turki, yang tertangkap tanpa persiapan dalam pertempuran Kütahya-Eskişehir, mundur ke timur Sakarya atas perintah Mustafa Kemal Paşa. Menurut artikel-artikel TDV, bangsa Yunani memasuki Eskişehir pada 20 Juli 1921, Kütahya pada 21 Juli, dan Bilecik pada 22 Juli. Raja Yunani Konstantinos memimpin dewan perang di Kütahya pada 28 Juli dan tentara bersiap menyerang ke arah Ankara.", "29f7f871"]},
"OLAYLAR_P0057:1922-04-29:0":{"b": ["Penarikan pasukan Italia dari Marmaris dan Kuşadası", "1d672994"], "d": ["Italia, yang berada di pesisir Anatolia barat daya sejak Mei 1919, mengosongkan zona pendudukan selangkah demi selangkah setelah mendekat kepada Pemerintah Ankara. Antalya dan Bodrum telah dikosongkan pada musim panas 1921; pasukan Italia terakhir juga meninggalkan Kuşadası dan Marmaris pada akhir April 1922.", "f956076c"]},
"OLAYLAR_P0057:1922-08-26:0":{"b": ["Serangan Besar dimulai", "efba4bd3"], "d": ["Setelah persiapan setahun sejak Sakarya, tentara Turki melancarkan serangan umum di front Afyon. Menurut artikel Millî Mücadele dan Kütahya TDV, Serangan Besar dimulai dari Afyon pada pagi 26 Agustus 1922 dan perlawanan tentara Yunani patah dalam waktu singkat.", "7eaf426f"]},
"OLAYLAR_P0057:1922-08-27:0":{"b": ["Pembebasan Afyon", "beaeef23"], "d": ["Pada hari kedua serangan, front Yunani ditembus di depan Afyon. Menurut artikel Afyonkarahisar TDV, pada akhir Serangan Besar yang dipimpin langsung oleh Atatürk, pasukan Yunani dihancurkan dan kota dibebaskan pada 27 Agustus 1922. Hari ini dirayakan sebagai hari pembebasan Afyon.", "bfb4dd98"]},
"OLAYLAR_P0057:1922-08-30:0":{"b": ["Pertempuran Lapangan Panglima Tertinggi — pembebasan Kütahya", "376d3118"], "d": ["Pasukan utama tentara Yunani terkepung antara Afyon dan Dumlupınar. Menurut artikel Millî Mücadele TDV, operasi pengepungan diselesaikan pada 30 Agustus dengan Pertempuran Panglima Tertinggi yang dipimpin langsung oleh Panglima Tertinggi Mustafa Kemal Paşa. Menurut artikel Kütahya TDV, pada hari yang sama sebuah divisi kavaleri membebaskan Kütahya yang dibakar dan dihancurkan pasukan Yunani yang mundur.", "6ecd76e4"]},
"OLAYLAR_P0057:1922-09-01:0":{"b": ["Pembebasan Uşak", "0f2d44d1"], "d": ["Setelah Pertempuran Panglima Tertinggi, sisa-sisa tentara Yunani mundur ke barat, ke arah İzmir. Menurut artikel Uşak TDV, Uşak, yang berada di bawah pendudukan sejak 29 Agustus 1920, dibebaskan pada 1 September 1922 dengan masuknya pasukan nasional ke kota. Dalam kebakaran yang ditimbulkan pasukan pendudukan yang mundur, sekitar tiga perempat kota terbakar.", "ea4dc034"]},
"OLAYLAR_P0057:1922-09-02:0":{"b": ["Pembebasan Eskişehir", "f442de5c"], "d": ["Di sayap utara Serangan Besar, pasukan Yunani terpaksa meninggalkan Eskişehir juga. Menurut artikel Eskişehir TDV, kota yang berada di bawah pendudukan sejak 20 Juli 1921 dibebaskan pada 2 September 1922 setelah kemenangan 30 Agustus. Pada akhir pendudukan tiga belas bulan, bagian pasar telah dibakar dan kota setengah hancur.", "3b15a7c5"]},
"OLAYLAR_P0057:1922-09-06:0":{"b": ["Pembebasan Bilecik", "35dbd49b"], "d": ["Menurut artikel Bilecik TDV, kota mengalami pendudukan Yunani tiga kali selama Perjuangan Nasional; pendudukan ketiga yang dimulai pada 22 Juli 1921 berakhir pada 6 September 1922. Dalam kebakaran yang ditimbulkan pasukan Yunani ketika mengosongkan kota, sebagian besar rumah, toko, dan gedung pemerintahan terbakar.", "28e74c34"]},
"OLAYLAR_P0057:1922-09-07:0":{"b": ["Pembebasan Aydın", "ef1280b5"], "d": ["Dengan mendekatnya tentara Turki ke İzmir, pasukan Yunani di lembah Menderes juga mundur. Menurut artikel Aydın TDV, kota dibebaskan oleh pasukan Turki pada 7 September 1922 dalam keadaan sebagian hancur dan penduduknya sangat berkurang. Bangsa Yunani yang mundur telah membakar sebagian besar kota.", "358e3333"]},
"OLAYLAR_P0057:1922-09-11:0":{"b": ["Perebutan kembali Bursa", "6ad1da0b"], "d": ["Setelah pembebasan İzmir, tentara Turki maju ke utara menuju pesisir Marmara. Menurut artikel Bursa TDV, kota yang berada di bawah pendudukan Yunani sejak 8 Juli 1920 direbut kembali pada 10-11 September 1922. Berbarisnya tentara dari sini ke Çanakkale membuat Inggris cemas dan membuka jalan bagi perundingan Mudanya.", "caa09d48"]},
"OLAYLAR_P0057:1922-11-10:0":{"b": ["Penyerahan Trakia Timur — Kırklareli dan Tekirdağ", "2a08d65c"], "d": ["Gencatan Senjata Mudanya mengatur pengosongan Trakia Timur oleh tentara Yunani dan penyerahannya kepada Turki; Refet Paşa, yang ditugaskan menerima Trakia, tiba di İstanbul pada 19 Oktober. Menurut TDV, Kırklareli yang berada di bawah pendudukan sejak 26 Juli 1920 direbut kembali pada 10 November 1922, dan Tekirdağ dikembalikan kepada Turki sesuai gencatan senjata pada 13 November. Dengan demikian Trakia Timur bergabung ke wilayah Turki tanpa pertempuran.", "cb085872"]},
"OLAYLAR_P0058:1339-01-01:0":{"b": ["Eretna menghubungkan kawasan Tokat, Kayseri, dan Samsun dengan dirinya", "4a088f9f"], "d": ["Emîr Eretna, yang menguat di Anatolia sebagai gubernur Ilkhanid, setelah memperoleh kembali dukungan Sultan Mamluk en-Nâsır Muhammed memperluas batasnya pada 1339 dan menghubungkan kawasan Tokat, Kayseri, dan Samsun dengan dirinya. Kawasan Zamantı di timur Kayseri juga masuk ke administrasi Eretna pada masa ini. Beylik menyatakan kemerdekaannya pada 1341 dengan wafatnya en-Nâsır.", "5be963a4"]},
"OLAYLAR_P0058:1360-01-01:0":{"b": ["Halil Bey dari Dulkadirli memperluas batasnya hingga Zamantı", "aa911e87"], "d": ["Dengan naiknya Mehmed Bey yang masih kecil ke kepala Beylik Eretna, serbuan Türkmen dari selatan meningkat ke tanah Eretna yang melemah. Pada 1360, ketika Ömer Bey, salah satu pemimpin Türkmen, merebut Malatya, Halil Bey dari Dulkadiroğlu juga memperluas batas beyliknya hingga Zamantı di timur Kayseri. Dengan demikian kawasan Zamantı antara Elbistan dan Kayseri jatuh ke tangan Dulkadiroğulları dan beylik menguasai kawasan itu hingga aneksasi Utsmani tahun 1515.", "6f54371d"]},
"OLAYLAR_P0058:1394-01-01:0":{"b": ["Yıldırım Bayezid kembali mengepung İstanbul dengan ketat", "244834ca"], "d": ["İstanbul, yang diblokade secara berkala sejak 1391, kembali dikepung ketat oleh Yıldırım Bayezid pada musim semi 1394. Hubungan dengan Bizantium, yang sejak 1371 membayar upeti kepada Utsmani dan mengirim bantuan militer, dengan demikian berubah menjadi permusuhan terbuka. Pengepungan dicabut dengan munculnya bahaya Timur dan Pertempuran Ankara 1402.", "c3af0f1d"]},
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Perdamaian Bizantium dengan II. Murad — Bizantium kembali setuju membayar upeti", "6474d704"], "d": ["II. Murad, yang mengepung İstanbul pada 1422 terhadap Bizantium yang mendukung Düzmece Mustafa, menandatangani perjanjian damai dengan kaisar Bizantium pada 22 Februari 1424. Dengan perjanjian ini Bizantium kembali setuju membayar upeti kepada Utsmani dan setuju mengembalikan tempat-tempat yang diambilnya setelah 1402 di pesisir Marmara, Aegea, dan Laut Hitam, kecuali benteng Silivri dan Terkos; upeti tahunan yang dihindarinya dengan perjanjian bersama Emîr Süleyman pada 1403 dengan demikian kembali. Bizantium mempertahankan keadaan ini hingga penaklukan İstanbul pada 1453.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["Benteng Bayburt dan Kiğı diterima dari Safawi — Erzincan dan Bayburt diberikan kepada Bıyıklı Mehmed Bey", "2c7fd65e"], "d": ["Ketika Yavuz Sultan Selim, yang kembali dari Tebriz setelah kemenangan Çaldıran, berada di perkemahan, tiba kabar bahwa benteng Bayburt dan Kiğı telah diterima. Sancak beyi Trabzon Bıyıklı Mehmed Bey dan sancak beyi Yanya Mustafa Bey merebut Bayburt, yang dipertahankan Kara Maksûd-i Sultânî, salah satu emîr Şah İsmâil, pada Oktober 1514. Erzincan, yang masuk ke kekuasaan Utsmani tanpa perang, diberikan kepada Bıyıklı Mehmed Bey bersama Bayburt sebagai beylerbeyilik pada 23 Oktober 1514, dan Bayburt dijadikan pusat sancak.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Yavuz Sultan Selim kembali dari ekspedisi Tebriz ke Amasya dan melewatkan musim dingin di sana", "49d51f94"], "d": ["Yavuz Sultan Selim, yang tinggal sembilan hari di Tebriz, mengurungkan niat melewatkan musim dingin di Iran karena kesulitan perbekalan dan keengganan tentara, dan kembali lewat Kars dan Bayburt. Padişah, yang merayakan Hari Raya Ramadan di Niksar, tiba di Amasya dan melewatkan musim dingin di sini. Ia bermaksud kembali berbaris melawan Safawi pada tahun berikutnya; di Amasya tekanan para yeniçeri untuk kembali ke İstanbul dimulai, dan ekspedisi berlanjut pada musim semi 1515 dengan penaklukan Kemah.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["Eflak, Boğdan, dan Transilvania bersama-sama memberontak melawan Utsmani", "e71d3ee9"], "d": ["Pada pertengahan 1594 tiga voyvodalık di utara Tuna — Eflak, Boğdan, dan Transilvania — memutuskan bertindak bersama melawan Utsmani. Voyvoda Boğdan Aron Tiran bergabung dengan Liga Suci yang dibentuk Kaisar Austria dan Paus VIII. Clemens dan menempatkan dirinya di bawah Kepangeranan Transilvania; voyvoda Eflak Mihai Viteazul bergabung dalam gerakan karena ketidakpuasan terhadap beban pajak yang berat. Pada 13 November 1594 pemberontakan serentak melawan administrasi Utsmani dimulai di Eflak dan Boğdan, dan dengan dukungan Transilvania gerakan meluas ke selatan Tuna, ke wilayah Utsmani. Menurut TDV İslâm Ansiklopedisi, aliansi tiga pihak ini membuka front utara Perang Panjang Utsmani-Habsburg (1593-1606) yang berlangsung pada tahun-tahun yang sama.", "30f44add"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Penaklukan Benteng Ostrovica di lembah Una", "5c6cc91b"], "d": ["Ostrovica, yang berada di tangan keluarga Frankapan dan bangsawan Kroasia lainnya, berdiri di atas punggung bukit curam yang menghubungkan bagian utara dan selatan lembah Una. Pada 1523 ia masuk ke administrasi Utsmani dan menampung garnisun Utsmani hingga 1878. Benteng ini memperoleh arti pentingnya terutama setelah Karlofça (1699): karena dekat dengan perbatasan Venesia dan Austria, ia diperluas dan menjadi pusat kapetanat Stara Ostrovica; kota kecil Kulen Vakuf didirikan di kakinya pada awal abad XVIII.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Penaklukan benteng Udbina dan Krbava — Lika masuk ke administrasi Utsmani", "5fe329d3"], "d": ["Dataran Krbava telah kosong pada 1524 dan di Udbina hanya tersisa garnisun Karlović. Karlović meraih kemenangan terakhir di depan benteng pada April 1527, tetapi pada akhir Mei Udbina jatuh ke tangan pasha Bosnia bersama benteng Mrsinj dan Komić. Pada tahun yang sama wilayah Gospić diberikan kepada para ağa Senković. Setelah itu Lika dan Krbava menjadi bagian sancak yang berpusat di Obrovac, yang pada 1580 bernama Kırka.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Peralihan pasti Drežnik dan županija Drežnik ke administrasi Utsmani", "6624ad14"], "d": ["Drežnik, yang berada di tangan Frankapan sejak 1323, sempat dikuasai Utsmani secara sementara pada 1578. Pada 1592 benteng dan seluruh županija Drežnik masuk ke administrasi Utsmani secara pasti; pada tahun yang sama Bihaç juga jatuh. Pada abad XVIII Drežnik bergantung pada kapetanat Ostrožac.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Perebutan Benteng Cetin oleh Utsmani", "98815f97"], "d": ["Cetin, benteng kunci pertahanan kawasan Slunj terhadap Utsmani sejak pertengahan abad XVI, masuk ke administrasi Utsmani pada 1636 setelah dikepung berkali-kali. Masa Utsmani pertama ini berlangsung dua tahun.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Benteng Cetin kembali ke pihak Habsburg", "690f9f84"], "d": ["Cetin, yang jatuh ke tangan Utsmani pada 1636, kembali ke pertahanan perbatasan Kroasia-Habsburg pada 1638 dan tetap demikian hingga 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin kembali menjadi benteng Utsmani", "e1750675"], "d": ["Cetin kembali menjadi benteng Utsmani pada 1670 dan dibentengi secara menyeluruh pada abad XVIII: benteng abad pertengahan dikelilingi tembok berbenteng bundar. Benteng ini menguasai ujung barat laut perbatasan Bosnia hingga 1790.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Hilangnya Lika dan Krbava — Udbina dan Gospić jatuh ke tangan pasukan perbatasan Habsburg", "01277a38"], "d": ["Dalam perang yang berlanjut setelah kekalahan di Wina, pasukan perbatasan Kroasia di bawah jenderal Karlovac, Herberstein, merebut Udbina pada 1689; Gospić juga lepas dari administrasi Utsmani pada tahun yang sama. Lika Utsmani yang berlangsung lebih dari 160 tahun berakhir, tempat-tempat yang kosong dihuni penduduk Kroasia baru, dan Udbina menjadi benteng penting pertahanan perbatasan terhadap Utsmani hingga Perdamaian Ziştovi (1791).", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Perebutan Drežnik oleh Austria — front barat Pertempuran Dubica", "05d5e5f1"], "d": ["Dalam perang Utsmani-Austria 1788-1791, pasukan Habsburg merebut Drežnik di sebelah barat Bihaç. Berdasarkan pasal 4 Perjanjian Ziştovi, Drežnik dan Cetin tetap di bawah administrasi Habsburg dan tidak pernah kembali ke Bosnia.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Perebutan Benteng Cetin oleh Austria", "df182480"], "d": ["Pada 1790 tentara Habsburg menyerang Cetin, Bužim, dan Velika Kladuša, dan merebut Cetin. Mobilisasi dan serangan balik yang diumumkan gubernur Bosnia tidak mampu merebut kembali benteng; pasal 4 Perjanjian Ziştovi menyerahkan Cetin kepada Habsburg. Para serhadli Bosnia merebut kembali benteng itu dalam serbuan singkat pada 1809 dan 1813.", "fc69baec"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilecik pertama kali disebut — perbatasan dengan Bizantium dimulai di Bilecik", "7b69f743"], "d": ["Dalam peristiwa tahun 683 yang dikutip Neşrî, Bilecik disebut sebagai tempat dimulainya perbatasan antara beylik uç Osman Bey dan Bizantium. Ini adalah penyebutan pertama yang diketahui dalam sejarah atas permukiman itu; bukan pendiriannya.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Koin atas nama Gāzân Han di Burdur — saksi pertama kota yang diketahui", "01974ddc"], "d": ["Hamîdoğulları, di bawah tekanan Ilkhanid, terpaksa mencetak koin atas nama Gāzân Han di Burdur pada tahun 699. Koin ini adalah saksi tertulis/bertanggal pertama Burdur.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Çorum disebut dalam negeri Eretna — saksi pertama kota yang diketahui", "bf7bd67f"], "d": ["Çorum dihitung di antara kota-kota di bawah kekuasaan Eretna Bey ketika ia wafat pada Muharram 753. Pendirian kota tidak diketahui; penyebutan ini adalah saksi bertanggal paling awal yang dapat ditemukan.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["İbrail pertama kali disebut — dokumen imtiyaz Vlaicu Vodă untuk para pedagang Braşov", "0b3517a7"], "d": ["Voyvoda Eflak Vladislav memberikan dokumen kepada para pedagang Braşov yang memberikan kemudahan saat mengangkut barang melalui jalan İbrail. Dokumen ini adalah saksi tertulis pertama İbrail yang diketahui; tempat itu di sini belum disebut sebagai kota, melainkan sebagai ujung jalan di Tuna. Bukan tanggal pendirian.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Kişinev pertama kali disebut dalam ferman voyvoda Boğdan", "a50799d7"], "d": ["Nama Kişinev pertama kali muncul dalam sebuah ferman tahun 1420 dari voyvoda Boğdan Aleksandru. Kota lama tetap sebagai kota kecil Boğdan; ketika beralih ke Rusia bersama Besarabia pada 1812, ia menjadi pusat provinsi.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Kalas pertama kali disebut dalam dokumen voyvoda Boğdan", "a31af8a2"], "d": ["Voyvoda Boğdan II. Ştefan membebaskan dua gerobak Biara Humor yang mengangkut ikan dari Kalas dari bea cukai. Dokumen ini adalah saksi tertulis pertama Kalas yang diketahui dengan pasti; permukiman mungkin sebelumnya sudah ada sebagai desa nelayan di tepi Tuna.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["Nama Mostar pertama kali muncul dalam dokumen Dubrovnik", "a599bc55"], "d": ["Nama Mostar pertama kali muncul dalam dokumen Dubrovnik bertanggal 3 April 1452; permukiman itu berada di wilayah Kadipaten Herzegovina. Penaklukan Utsmani terjadi pada 1466-68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["Masjid Hünkâr di Saraybosna — saksi bertanggal paling awal permukiman", "ad697a7d"], "d": ["Sancak beyi Bosnia İshak Bey, di permukiman Muslim pertama di dataran Saray, membangun sebuah istana untuk dirinya, Masjid Hünkâr atas nama Fâtih Sultan Mehmed, dan sebuah hamam di sampingnya. Masjid itu bertanggal 862 (1458); ini adalah bangunan bertanggal paling awal Saraybosna yang diketahui.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Waqf İshak Bey — inti kota Saraybosna diwakafkan", "0b364229"], "d": ["Dari akta waqf İshak Bey tertanggal Cemâziyelevvel 866 (Februari 1462) dipahami bahwa selain masjid dan hamam, dibangun pula zâviye, mevlevîhâne, imaret, sebuah jembatan di atas Miljacka, Han Kolobara di seberang, bedesten, kervansaray, dan toko-toko. Dokumen ini adalah fondasi waqf kota; permukiman sudah ada sebelumnya.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Tatarpazarcığı pertama kali tercatat dalam defter akıncı", "3b1c839e"], "d": ["Catatan tertua tentang kota itu mundur hingga tahun 877 (1472): sebuah defter akıncı di Perpustakaan Nasional Sofia mencatat permukiman itu.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banaluka pertama kali disebut dalam instruksi Raja II. Vladislav", "0ebc6288"], "d": ["Nama Banja Luka pertama kali muncul dalam sebuah instruksi tertanggal 6 Februari 1494 dari raja Hongaria-Kroasia II. Vladislav; kawasan itu terikat pada mahkota Hongaria melalui banat Yayçe. Penaklukan Utsmani terjadi pada musim dingin 1527-28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["Penduduk Basra menyelesaikan pemindahan ke lokasi Basra masa kini — Basra lama ditinggalkan", "20f96eac"], "d": ["Penduduk, seiring waktu, mulai menetap di Basra masa kini yang mereka anggap lebih aman terhadap serangan Badui dan yang airnya lebih mudah diperoleh; peralihan ke lokasi baru selesai pada tahun 900 (1494-95). Basra lama, yang didirikan pada masa Hz. Ömer, berada sekitar 25 km dari kota masa kini.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Mengli Giray Han membangun Istana Khan di tepi Çürüksu — fondasi Bahçesaray", "0792497c"], "d": ["Di lembah yang merupakan kawasan berburu dan istirahat musim panas para gubernur Orda Emas dan khan Krimea pertama, I. Mengli Giray Han membangun istana yang kini dikenal sebagai Istana Khan di tepi Çürüksu dan meletakkan fondasi Bahçesaray. Kota berkembang di sekitar istana dan sepanjang lembah Çürüksu yang sempit, menjadi makmur pada akhir abad XVI, dan menjadi pusat Khanat Krimea.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["Kazak Zaporozhia mendirikan Sich pertama di pulau Khortytsia", "e6ca0dd9"], "d": ["Pangeran Dmytro Vyshnevetsky mendirikan Sich Zaporozhia pertama di pulau Khortytsia Kecil di Dnieper. Benteng dikepung dan dihancurkan oleh bangsa Tatar Krimea pada 1558; Sich kemudian dipindahkan ke pulau-pulau di selatan. Istilah: «Sich» (bahasa Ukraina Sich) adalah kamp pusat Kazak Zaporozhia di pulau-pulau Dnieper yang dibentengi dengan balok kayu dan parit; ia adalah markas, tempat dewan (Rada), dan pusat kepala tentara terpilih (koshovyi), bukan ibu kota negara.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["Sich Bazavluk didirikan", "fcd507ae"], "d": ["Setelah bangsa Tatar menghancurkan Sich Tomakivka, Kazak Zaporozhia mendirikan Sich baru di pulau Bazavluk, di tempat bertemunya cabang-cabang Dnieper Chortomlyk, Pidpilna, dan Skarban. Sich dihancurkan pada 1638 dengan ekspedisi Polandia setelah penumpasan pemberontakan Kazak. Istilah: «Sich» (bahasa Ukraina Sich) adalah kamp pusat Kazak Zaporozhia di pulau-pulau Dnieper yang dibentengi dengan balok kayu dan parit; ia adalah markas, tempat dewan (Rada), dan pusat kepala tentara terpilih (koshovyi), bukan ibu kota negara. Pada tanggal ini «Hetmanat» belum ada (1648); nama Zaporozhia berarti «seberang jeram» dan Sich-Sich berdiri di perbatasan stepa di hilir jeram Dnieper. Tidak ada kekerabatan etnis dengan Kazak Kazakhstan: Kazak Zaporozhia adalah komunitas Slavia Timur (Ukraina) dan Ortodoks; yang sama hanyalah kata «kazak» (pejuang bebas) yang berasal dari bahasa Turki.", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["Sich Mykytyn Rih pertama kali disebut", "61e22abc"], "d": ["Nama Sich keempat yang didirikan di Mykytyn Rih, di tempat Nikopol masa kini, pertama kali muncul pada 1628; pada 1648 direbut oleh Bohdan Khmelnytsky. Ini adalah saksi pertama tempat itu yang diketahui, bukan pendiriannya.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["Sich Chortomlyk didirikan", "4b6e8197"], "d": ["Kazak Zaporozhia mendirikan Sich Chortomlyk, yang juga disebut 'Sich Lama', di tanjung tempat Dnieper bertemu sungai Chortomlyk. Sich dihancurkan oleh tentara Rusia pada 25 Mei 1709 karena mereka mendukung Mazepa.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Kharkov didirikan oleh pengungsi Kazak", "288b303c"], "d": ["Di tepi utara stepa liar, di tempat bertemunya sungai Lopan dan Kharkov, para pengungsi Kazak yang datang dari tepi kanan Dnieper mendirikan sebuah permukiman. Kharkov segera menjadi pusat Sloboda Ukraina yang bergantung pada Moskow.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["Kazak Zaporozhia mendirikan Sich Oleshky dengan izin khan Krimea", "ed26f29d"], "d": ["Ketika serangan Rusia mengosongkan Sich di Kamenka, Kazak Zaporozhia dengan izin khan Krimea menetap di Oleshky, di tepi kiri sungai Konka, di tanah khanat. Setelah Perjanjian Prut, Kazak Gordiyenko juga bergabung dengan mereka. Khan tidak mengizinkan Sich memiliki tembok dan meriam.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["Sich Oleshky dijarah dan ditinggalkan", "52361709"], "d": ["Kazak Samara yang pro-Rusia menyerbu dan menjarah Sich Oleshky serta membakar barak. Sich tidak didirikan kembali; Kazak kembali ke Kamenka pada 1730 dan pada 1734 bersumpah setia kepada Rusia lalu mendirikan Sich Baru.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["Benteng Stavropol didirikan di tepi Volga", "eb087a50"], "d": ["Di Volga Tengah, benteng Stavropol didirikan untuk bangsa Kalmuk yang menerima agama Kristen (Tolyatti masa kini).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nâdir Şah merebut Kandahar dan merobohkan kota lama", "9cc23e6b"], "d": ["Nâdir Şah, penguasa Afşar, merebut Kandahar yang berada di tangan bangsa Afghan Ghilzai setelah pengepungan panjang. Kota dihancurkan dan penduduknya pindah ke Nâdirâbâd yang didirikan di tenggara lokasi lamanya; Kandahar lama tidak pernah menjadi kota lagi.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["Benteng Stavropol didirikan di garis Azak-Mozdok", "7fd9b9f1"], "d": ["Sepuluh benteng dibangun di garis benteng Azak-Mozdok yang didirikan setelah Küçük Kaynarca untuk mengawasi stepa antara Kuban dan Terek; salah satunya adalah Stavropol. Benteng itu kemudian menjadi pusat kegubernuran Kaukasus dan guberniya Stavropol.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["Galangan kapal Kherson didirikan di muara Dnieper", "115f2c34"], "d": ["Di muara Dnieper yang beralih ke Rusia setelah Küçük Kaynarca, sebuah galangan kapal didirikan di dekat benteng Aleksandr-şanc yang dibangun pada 1737 dan segera dihancurkan, dan diberi nama Kherson. Kota menjadi pusat kaza pada 1784 dan pusat gubernia pada 1803.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Orang Yunani dari Krimea mendirikan Mariupol di pesisir Azak", "4e3af209"], "d": ["Orang Yunani yang datang dari Krimea mendirikan Mariupol di tempat Kalmius bermuara ke Laut Azak. Kota menjadi pusat kaza yang bergantung pada kegubernuran Yekaterinoslav pada 1784.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Yekaterinoslav dipindahkan ke lokasinya masa kini di tepi Dnieper", "ec361381"], "d": ["Yekaterinoslav, yang didirikan Potemkin pada 1778 di tempat bertemunya sungai Kilçen dan Samara, dipindahkan ke lokasinya masa kini pada 1783 karena letaknya yang tidak sehat.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["Pelabuhan armada Rusia Sevastopol didirikan di teluk Akhtiar", "01058a25"], "d": ["Setelah aneksasi Krimea oleh Rusia pada 1783, teluk tempat desa Tatar Krimea Akhtiar (Akyar) berada dipilih sebagai pelabuhan militer; pelabuhan didirikan tahun berikutnya dan menerima nama Sevastopol. Kota menjadi pelabuhan utama armada Laut Hitam Rusia pada 1804.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Benteng Nikolayev didirikan di muara Bug", "d57e52b9"], "d": ["Atas perintah Knez Potemkin, sebuah benteng didirikan di tempat bertemunya sungai Bug Selatan dan İngul. Pada 1788 sebuah galangan kapal dibuka di sini dan permukiman menjadi salah satu pusat pembuatan kapal armada Laut Hitam.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Permukiman perbatasan, inti Melitopol, didirikan di tepi Molochna", "637d5817"], "d": ["Setelah aneksasi Krimea, sebuah permukiman perbatasan didirikan di tepi sungai Molochna. Permukiman menerima nama Novooleksandrivka pada 1816 dan dijadikan kota dengan nama Melitopol pada 1841.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Novocherkassk, pusat baru Tentara Kazak Don, didirikan", "bf5709fd"], "d": ["Pusat administratif Tentara Kazak Don berpindah dari Çerkask, yang hingga saat itu menjadi pusat, ke Novocherkassk yang didirikan di lokasi Biryuchiy Kut antara sungai Aksay dan Tuzlov.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Vâdî Halfâ dicatat dalam perjalanan Burckhardt ke Nubia", "6efc72ec"], "d": ["Pelancong Swiss J. L. Burckhardt menulis dalam buku hariannya tertanggal 6 Maret 1813 bahwa ia melewati Vâdî Halfâ dan bahwa di sana dilakukan sejumlah perdagangan. Ini adalah saksi bertanggal pertama yang dapat ditemukan.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Dermaga Berdyansk didirikan di pesisir Azak", "908ac3cf"], "d": ["Atas prakarsa Knez Mihail Vorontsov, Berdyansk didirikan di tempat sungai Berda bermuara ke Laut Azak. Permukiman menjadi kota pada 1835 dan pusat kaza pada 1842.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["Penduduk Malatya tinggal di kebun Aspuzu — inti Malatya modern", "d1dba159"], "d": ["Markas besar Utsmani melawan tentara Mesir İbrâhim Paşa dipindahkan dari Mezraa ke Malatya pada musim panas 1838. Penduduk Malatya yang tinggal di rumah musim panas mereka di Aspuzu tidak kembali ke rumah musim dingin mereka di kota lama yang rusak setelah kepergian tentara; Aspuzu menjadi inti Malatya modern. Malatya Lama (Battalgazi) mengecil dan terus hidup.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Van didirikan di lokasi barunya — kota lama yang hancur ditinggalkan", "6d278578"], "d": ["Van dibebaskan dari pendudukan pada 2 April 1918. Mereka yang kembali, alih-alih memperbaiki Van lama di tepi danau yang hancur selama tahun-tahun perang, mendirikan kota baru sekitar 7 km ke pedalaman dari pantai di lokasi bekas lingkungan Norşen dan Arak lama. Kota lama ditinggalkan.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Maraş beralih ke Mamluk — naib Aleppo Bilbân et-Tabahî merebutnya kembali dari bangsa Armenia", "03171265"], "d": ["Maraş, yang sejak 1258 berada di tangan Kerajaan Armenia Kilikia, dengan perjanjian Sultan Halil dengan bangsa Armenia pada 1293 untuk waktu singkat beralih ke Mamluk dan setelah mereka mundur kembali jatuh ke tangan Armenia. Pada 697 (1298) naib Mamluk di Aleppo Bilbân et-Tabahî merebut kembali kota itu. Maraş setelah itu tetap menjadi tanah Mamluk hingga bangkitnya Dulkadırlı.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Kekaisaran Bizantium menjadi pembayar upeti Utsmani", "615df998"], "d": ["Setelah kemenangan Çirmen (1371), kaisar Bizantium Ioannes V pada musim dingin 1372 menerima menjadi pembayar upeti Murad I: ia akan membayar upeti tahunan dan menyediakan pasukan bagi ekspedisi sultan. Bizantium sejak tanggal ini hingga 1403 tetap menjadi negara vasal yang terikat pada Utsmani; blokade Yıldırım Bayezid pada 1391 menaikkan upeti. Setelah kekalahan Ankara, perjanjian Gelibolu (1403) dengan Süleyman Çelebi membebaskan Bizantium dari upeti; dengan perjanjian dengan Murad II pada 1424 upeti dimulai kembali.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Yıldırım Bayezid, setelah wafatnya Barquq, memasukkan Besni, Darende, dan Divriği ke tanah Utsmani", "8e57d7e6"], "d": ["Setelah wafatnya Sultan Mamluk Barquq (Juni 1399), ketika urusan administrasi Negara Mamluk kacau, Yıldırım Bayezid turun ke cekungan Efrat dan memasukkan Besni (Behisni), Darende, dan Divriği bersama Malatya ke tanah Utsmani. Sivas sebelum itu diserahkan kepada Utsmani setelah wafatnya Kadı Burhâneddin pada musim panas 1398. Divriği sejak 1391 berada di bawah kekuasaan Mamluk dan merupakan pos terdepan yang terikat pada eyalet Aleppo. Pemerintahan Utsmani di sini tidak berlangsung lama: karena bahaya Timur yang mendekat, Divriği pada 1401 kembali diberikan kepada Mamluk, dan masuknya kota secara pasti ke pemerintahan Utsmani terjadi setelah Marj Dabiq 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni beralih ke Mamluk pada ekspedisi Timur ke Sivas dan Malatya", "4853da9a"], "d": ["Besni, yang direbut Yıldırım Bayezid pada 1398 bersama Sivas, Darende, dan Malatya, pada 1400 ketika Timur merebut Sivas dan Malatya jatuh ke tangan Mamluk. Timur pada 27 September 1400 setelah pengepungan sengit juga merebut Besni; ketika ia menarik diri dari kawasan itu, Besni kembali masuk ke kekuasaan Mamluk dan tetap di Mamluk (kecuali masa peralihan Dulkadırlı) hingga Yavuz Sultan Selim merebutnya pada Agustus 1516.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği diberikan kembali kepada Mamluk karena bahaya Timur", "97196b1f"], "d": ["Divriği, yang diambil Yıldırım Bayezid dari Mamluk pada 1398, ketika Timur mendekati Anatolia pada 1401 ditinggalkan kembali kepada Mamluk. Karena itu setelah Timur menghancurkan Sivas (1400), Divriği tampak di peta berwarna Mamluk; pada bulan-bulan yang sama Bayezid di timur merebut Erzincan dan Kemah, sehingga tanah Mamluk berada di antara tanah Utsmani di barat (Sivas) dan timur laut (Kemah). Divriği baru beralih secara pasti ke Utsmani setelah Marj Dabiq 1516.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Sultan Mamluk Şeyh merebut kembali Antep dan Darende dari Dulkadırlı", "f90c9508"], "d": ["Sultan Mamluk Şeyh, yang khawatir akan persahabatan Dulkadırlı dengan Utsmani, pada 1414 berekspedisi; ia merebut kembali Antep dan Darende yang sebelumnya atas kehendaknya sendiri ia berikan kepada Dulkadırlı.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Dulkadıroğlu Mehmed Bey merebut kembali Darende dan memasukkan Besni ke wilayahnya", "df914dcb"], "d": ["Darende, yang direbut Mamluk pada 1414, direbut kembali oleh Dulkadıroğlu Mehmed Bey pada 1418 dan ia juga memasukkan Besni ke wilayahnya.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Mamluk mengalahkan Dulkadırlı di Antep; Besni kembali ke pemerintahan Mamluk (perkiraan)", "72742430"], "d": ["Tentara Mamluk pada 1436 mengalahkan Dulkadırlı di Antep, Mehmed Bey mundur ke Akdağ. Tahun kembalinya Besni ke Mamluk tidak tertulis dalam sumber; Besni bergabung dengan Dulkadır pada 1418 dan telah kembali ke Mamluk sebelum Şehsuvar Bey mengambilnya dari Mamluk pada 1465. Atlas mengembalikan Besni ke Mamluk bersama kekalahan ini di pusat tetangga Antep (perkiraan yang dinyatakan).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Dulkadıroğlu Şehsuvar Bey merebut Besni dari Mamluk (perkiraan)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), yang diangkat Fatih Sultan Mehmed sebagai bey Dulkadır, merebut Besni, Gerger, Birecik, dan Rumkale yang berada di tangan Mamluk; Mamluk dikalahkan di Turnadağı pada musim gugur 1467 dan di dekat Antep pada musim semi 1468.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emîr Yeşbek mengalahkan Şehsuvar Bey; Besni kembali ke pemerintahan Mamluk (perkiraan)", "4d856aee"], "d": ["Pada musim semi 1471 Emîr Yeşbek mengalahkan Şehsuvar Bey di sungai Savron; Mamluk merebut kembali Kadirli dan Kozan. Şehsuvar dihukum mati di Kairo pada 1472, Mamluk mengangkat kembali Şahbudak sebagai bey. Besni pun dengan kembalinya ini masuk ke pemerintahan Mamluk (TDV besni: 'menjelang akhir abad ke-15 kembali jatuh ke tangan Mamluk').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Pasukan Ferdinand menduduki dan membentengi Solnok", "6c8416e6"], "d": ["Ketika Utsmani bersiap mendirikan benteng di Solnok di tepi Tisza, pasukan Ferdinand I mendahului: mereka menduduki Solnok pada pertengahan September 1550 dan benteng dibuat dapat dipertahankan pada pertengahan Oktober. Dengan demikian Solnok, yang termasuk negeri Izabella, jatuh ke tangan Habsburg setahun sebelum beralihnya Transilvania ke Ferdinand; Utsmani merebut benteng itu pada 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Transilvania beralih ke pemerintahan Habsburg: dewan Kolozsvár mengakui pelepasan hak Izabella", "8458a566"], "d": ["Dengan kesepakatan Martinuzzi dengan Ferdinand, Ratu Izabella atas nama raja kecil János Zsigmond menandatangani surat pelepasan yang dipaksakan kepadanya di benteng Szászsebes pada 19 Juni 1551. Dewan Transilvania yang bersidang di Kolozsvár pada 26 Juli mengakui pelepasan ini dan kedaulatan Raja Ferdinand; tentara Habsburg Jenderal Castaldo memasuki Belgrad Transilvania (Gyulafehérvár). Dengan demikian Transilvania yang terikat pada Utsmani beralih ke pemerintahan Habsburg yang akan berlangsung lima tahun.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Pemerintahan Habsburg di Transilvania berakhir: Transilvania kembali menjadi voyvodalık yang terikat Utsmani", "721a482a"], "d": ["Karena János Zsigmond masih kecil, Habsburg dengan perantaraan pastor keturunan Kroasia Martinuzzi (Fráter György) yang diangkat sebagai walinya, pada 1551 mencoba menguasai Transilvania; Belgrad Transilvania (Gyulafehérvár), Kolozsvár, Brassó, dan Segesvár selama lima tahun berada di bawah pemerintahan Habsburg. Utsmani mencegah keadaan ini dan Transilvania kembali menjadi voyvodalık pembayar upeti yang terikat kepadanya. Setelah itu, selama sekitar 150 tahun pada abad ke-16 dan ke-17, Transilvania mempertahankan statusnya yang bertumpu pada otonomi luas dalam urusan dalam negeri dan kesetiaan kepada Istanbul dalam urusan luar negeri.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt, dan Tokaj beralih ke pihak Szapolyai", "587c782d"], "d": ["Setelah kembalinya Izabella dan János Zsigmond ke Transilvania pada 1556, para pendukung Szapolyai pada 1556 mengepung Nagyvárad. Pada 1557 para aristokrat Tisza Hulu merebut benteng-benteng kerajaan terpenting — Várad, Huszt, dan Tokaj; di tangan Ferdinand hanya tersisa Gyula dan Világos. Várad setelah itu menjadi benteng kepangeranan Transilvania dan tetap demikian hingga Utsmani merebutnya pada 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi merebut Szatmár — ujung utara Transilvania beralih ke Habsburg", "2256bb27"], "d": ["Szatmár, yang beralih ke Habsburg pada 1561 dengan berpindahnya pihak Balassa Menyhért, direbut kembali Báthory István dalam serangan mendadak pada musim gugur 1564 dan dimasukkan ke Transilvania. Komandan Habsburg Lazarus von Schwendi melancarkan serangan balasan pada Februari 1565: Tokaj jatuh pada 9 Februari, Szerencs empat hari kemudian, dan Szatmár hampir tanpa perlawanan jatuh ke tangan pasukan kekaisaran.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Pasukan Bocskai merebut Szatmár", "e93b098b"], "d": ["Ketika pemberontakan Bocskai menyebar ke Hongaria timur laut, Gyulaffy merebut Szatmár yang dikepungnya pada 21 Januari 1605. Perdamaian Wina 23 Juni 1606 menyerahkan provinsi Szatmár kepada Bocskai seumur hidup; karena tidak ada pewaris laki-laki, dengan wafatnya Bocskai pada 29 Desember 1606 provinsi itu kembali ke kerajaan.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Wafatnya Bocskai István — provinsi Szatmár kembali ke kerajaan", "3721bb9b"], "d": ["Pangeran Transilvania Bocskai István wafat di Kassa pada 29 Desember 1606. Perdamaian Wina (23 Juni 1606) telah menyerahkan provinsi-provinsi, termasuk Szatmár, kepadanya seumur hidup, untuk kembali ke kerajaan bila tidak ada pewaris laki-laki; dengan ketentuan ini provinsi Szatmár kembali ke kerajaan Hongaria Habsburg. Transilvania mulai mencari pangeran baru.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor menguasai provinsi Szatmár", "80263da1"], "d": ["Dengan ekspedisi Bethlen Gábor ke Hongaria pada musim gugur 1619, provinsi Szatmár masuk ke kendali pangeran Transilvania; pada November 1619 ia menyapa provinsi itu melalui surat. Pra-perjanjian 23 Januari 1620 dan Perdamaian Nikolsburg menyerahkan tujuh provinsi, termasuk Szatmár, kepada Bethlen seumur hidup. Setelah wafatnya Bethlen (15 November 1629), pengembalian provinsi-provinsi kepada kerajaan rampung pada 30 Maret 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Pengembalian tujuh provinsi Bethlen Gábor kepada kerajaan rampung", "31b5968f"], "d": ["Perdamaian Nikolsburg telah menyerahkan tujuh provinsi Hongaria Hulu, termasuk Szatmár, kepada Bethlen Gábor seumur hidup. Setelah wafatnya Bethlen pada 15 November 1629, pengembalian provinsi-provinsi kepada kerajaan dimulai dengan instruksi 30 November 1629 dan rampung pada 30 Maret 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György I Rákóczi menerima penyerahan Szatmár", "f398635b"], "d": ["Pada ekspedisi 1644 pangeran Transilvania György I Rákóczi, garnisun Jerman Szatmár beralih ke dinas Rákóczi dan benteng jatuh ke tangan Transilvania. Perdamaian Linz 16 Desember 1645 menyerahkan benteng itu kepada para pewaris Rákóczi selama seorang Rákóczi duduk di takhta Transilvania.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Hilangnya Nitra — De Souches merebut kembali benteng", "c71bf012"], "d": ["Nitra, yang menyerah dengan perlawanan singkat setelah penaklukan Uyvar pada 1663, dikepung komandan kekaisaran De Souches pada 15 April 1664; benteng menyerah pada 3 Mei 1664. Karena Perjanjian Vasvár meninggalkan tempat-tempat yang direbut sebagaimana adanya, Uyvar tetap di Utsmani sedangkan Nitra tetap di tangan Habsburg.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Hilangnya Léva", "f311920e"], "d": ["De Souches setelah Nitra mengepung Léva pada 9 Juni 1664; pada 13 Juni ditandatangani kapitulasi dan pada 14 Juni benteng berada di tangan pasukan kekaisaran. Pertempuran Léva (Garamszentbenedek) pada 19 Juli 1664 tidak mengubah kepemilikan; hasilnya Habsburg tetap menguasai Léva dan Nitra.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroşenko menyerahkan Chigirin kepada Samoylovych", "3b538237"], "d": ["Hetman tepi kanan di bawah perlindungan Utsmani Petro Doroshenko pada 19 September 1676 menyerahkan ibu kotanya Chigirin kepada hetman tepi kiri Samoylovych dan pasukan Rusia. Utsmani mencopot Doroshenko dan mengangkat Yuri Khmelnytsky sebagai gantinya; pengepungan 1677 untuk mengusir garnisun Rusia di Chigirin gagal, benteng baru direbut pada 21 Agustus 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Penyerahan benteng-benteng Banat Transilvania (Temeşvar, Lippa, Lugos, Karánsebes) kepada Raja Hongaria Ferdinand", "0e354976"], "d": ["Pada 1551 tentara Habsburg di bawah Jenderal Castaldo memasuki Transilvania; Ratu Izabella dan putranya terpaksa melepaskan hak atas takhta Hongaria. Dengan persetujuan Castaldo, pada pertengahan Juli 1551 Martinuzzi mengutus Báthory Endre untuk menerima benteng-benteng Temeşvar, Lippa, Solymos, Karánsebes, Lugos, Becse, Becskerek, dan Çanad atas nama Ferdinand. Benteng-benteng selatan Transilvania yang berada di bawah perlindungan Utsmani pun jatuh ke tangan Habsburg; ekspedisi Kanûnî tahun 1551-1552 adalah jawabannya.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Pengangkatan Petrovics Péter sebagai sancakbeyi Lugos dan Karánsebes", "bcbe73e4"], "d": ["Atas permohonan gigih Izabella dan Petrovics, Kanûnî memutuskan mengembalikan János Zsigmond yang masih kecil ke Transilvania. Dengan surat dari Aleppo pada 7 April 1554, ia memerintahkan agar Transilvania membawa anak itu kembali ke negerinya; ia juga memerintahkan para voyvoda Eflak dan Boğdan membantu Petrovics dalam hal ini, yang pada saat yang sama diangkatnya sebagai sancakbeyi Lugos dan Karánsebes. Lugos, yang ditaklukkan pada 1552, dengan demikian diberikan kepada Petrovics sebagai sebuah sancak Utsmani.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Pengepungan Lippa dicabut — serbuan ban Lugos ke Temeşvar", "be03430e"], "d": ["Pada musim semi 1596 pasha Temeşvar mengepung Lippa. Pada malam yang menghubungkan 10 Mei dengan 11-nya, atas perintah Palatics György, ban Lugos dari Transilvania, prajurit Buday György menyerbu pinggiran Temeşvar dan membakarnya; Borbély György yang menembakkan seluruh meriam di benteng juga meyakinkan sang pasha bahwa bantuan telah datang. Pada 11 Mei pasha mundur dari depan Lippa dan bergegas melindungi pusatnya sendiri. Pada saat itu Lugos berada di tangan Kepangeranan Transilvania.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Pendudukan Orsova oleh pasukan Austria di bawah Veterani", "1b4a4f6c"], "d": ["Dalam ekspedisi 1688, Jenderal Veterani, setelah merebut Karánsebes, bergerak ke Orsova dan menduduki tempat itu juga. Dalam sumber tidak ada hari pendudukan; dipakai dasar tahun, 1 Januari 1688.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Perebutan kembali Orsova oleh Thököly dan pasukan Utsmani", "c5645da9"], "d": ["Setelah Vetislan direbut, Thököly dan para pasha Utsmani bergerak ke Orsova yang diduduki Veterani pada 1688. Setelah pertempuran kecil, Thököly memasuki Orsova pada 15 Juli 1689. Heissler, yang datang karena kabar bahaya, melihat pasukan di hadapannya dilengkapi dengan baik dalam hal amunisi dan kapal, lalu mundur untuk melindungi Transilvania. Serangan Herbeville di depan kota pada Agustus juga tidak mampu merebut kembali Orsova.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Sancak Lugos masuk ke pendudukan Habsburg (1691-1695)", "c8bcd6bd"], "d": ["Sancak Lugos berada di bawah pendudukan Habsburg (Jerman) antara 1691 dan 1695; II. Mustafa merebutnya kembali pada 22 September 1695. Dalam catatan lama, 1689-1695 adalah kekosongan yang dinyatakan; irisan 1691-1695 kini diwarnai sebagai Habsburg, sedangkan 1689-1691 tetap kosong. Tanggal hanya diambil berupa tahun.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Benteng Lugos masuk ke administrasi Habsburg", "6a9d401f"], "d": ["Lugoj, benteng sancak yang bergantung pada eyalet Tımışvar, berada di tangan Utsmani sejak 1695; ia dilepaskan kepada Monarki Habsburg bersama penyerahan pusat eyalet pada akhir pengepungan 1716. Catatan lama menaruh peralihan itu pada dasar tahun, 1 Januari 1716.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Perebutan Orsova oleh tentara Habsburg (ekspedisi 1717)", "7a4faffe"], "d": ["Dalam ekspedisi 1717, Jenderal Splényi tiba di depan Orsova pada 27 Agustus dan merebut kota itu dengan mudah; Orsova, yang tak mampu direbut Mercy pada 1716, dengan demikian jatuh ke tangan Habsburg. Petak-petak tepi Tuna di sekitarnya (termasuk bagian Đerdap di sisi Serbia) bergantung pada titik permukiman terdekat, Orsova, sehingga diwarnai dengan pemiliknya. Tanggal hanya diambil berupa tahun; hari pastinya belum terkonfirmasi.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Peralihan palanka Orsova ke Utsmani — komandan penjaga mundur ke Adakale", "de759b16"], "d": ["Pada awal ekspedisi 1738, komandan Vidin Hacı Mehmed Paşa menyerang tabya Erzsébet di tepi Tuna. Pada sore 8 Mei pasukan sipahi 4-5 ribu orang berbaris dari tepi kiri Tuna ke Orsova dan menyerang palanka Orsova; komandan Austria yang kehilangan sekitar seratus orang mundur ke Orsova Baru, yaitu benteng pulau Adakale. Setelah pertempuran Mehadiye pada Juli, Adakale juga jatuh ke tangan Utsmani pada Agustus 1738; Perjanjian Belgrade 1739 mengakui keadaan itu.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["II. Murad merebut Alacahisar, Niş dan Şehirköy kembali ke Utsmani", "54af926a"], "d": ["Setelah wafatnya Despot Serbia Stefan Lazarević tanpa pewaris (1427), II. Murad bergerak dengan menyatakan dirinya pewaris sah Serbia berdasarkan pernikahan Yıldırım Bayezid dengan putri Serbia, dan merebut Alacahisar (1428). Pada tahun yang sama, setelah wafatnya Lazarević, Utsmani juga merebut kembali benteng Şehirköy — kota itu direbut Stefan pada 1412 dan dipertahankan melawan Mûsâ Çelebi. Menurut artikel TDV nis, Utsmani juga merebut kembali Niş pada tahun yang sama (831/1428). Dengan demikian garis yang menghubungkan lembah Morava Besar dan Nišava masuk ke bawah kendali Utsmani.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Tentara Salib merebut Şehirköy — cabang Nišava dari 'Ekspedisi Panjang'", "fdf6140c"], "d": ["Tentara Salib di bawah pimpinan Raja Vladislav dan Despot Serbia Đurađ Branković merebut Şehirköy pada 1443. Dalam kelanjutan ekspedisi yang sama, pasukan Utsmani akan dikalahkan di celah İzladi pada November. Şehirköy diberikan kembali kepada Serbia oleh II. Murad setelah Perjanjian Segedin (1444), tetapi beralih ke Utsmani setelah wafatnya Đurađ Branković pada 1456.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Kekuasaan Utsmani yang pasti di kawasan Alacahisar terwujud", "9715382a"], "d": ["Alacahisar, yang diserahkan kepada Branković pada akhir perjanjian dengan utusan Hongaria tahun 1444, kembali masuk ke kekuasaan Turki pada tahun-tahun setelah kemenangan Varna. Penaklukan kedua kota ini tidak dibuktikan dengan catatan perang, melainkan catatan keuangan: catatan timar beberapa desa yang bergantung pada Alacahisar bertanggal akhir 1453/awal 1454; tetapi ini hanya kesaksian desa — pada 1454 pasukan Utsmani dikalahkan di sekitar Alacahisar, dan pada 1455 Alacahisar ditinggalkan kepada Branković sebagai perbatasan. Menurut TDV, kekuasaan Utsmani yang pasti di kawasan itu terwujud pada 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Pendirian Despotat Mora — Manuel Kantakuzenos di Mezistre", "87660b82"], "d": ["Kaisar Bizantium Ioannes Kantakuzenos memberikan putranya Manuel sebuah wilayah administratif tersendiri di Mora; Despotat Mora yang berpusat di Mezistre lahir dengan cara ini. Manuel memerintah hingga 1380; pada masa ini budaya dan seni Bizantium berkembang terutama di Mezistre. Despotat bertahan hingga penaklukan Fâtih pada 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Despot Konstantinos merebut Patras dari bangsa Frank", "cb0dd18c"], "d": ["Konstantinos, Despot Mora (kaisar Bizantium terakhir pada 1449), merebut kembali Patras dari bangsa Latin; dengan demikian pelabuhan penting di barat laut semenanjung ini juga bergabung ke despotat. Patras masuk ke kekuasaan Utsmani pada ekspedisi Mora Fâtih tahun 1458.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić-Kosača 'Adipati St. Sava' — lahirnya Hersek", "cc67061f"], "d": ["Stjepan Vukčić-Kosača, yang menyatukan Hum dan Trebinje dalam satu kebeyan, memberontak melawan raja Bosnia dan menyatakan dirinya 'Herzeg (adipati) St. Sava'; gelar itu diberikan oleh Kaisar Friedrich III pada 1448. Nama Herzegovina ('tanah sang Herzeg') berasal dari gelar ini. Hersek beralih sepotong demi sepotong ke Utsmani sejak 1466, menjadi sancak pada 1470; sisa wilayahnya bergabung pada awal 1482.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Perdamaian Kraków — negara ordo Teutonik berubah menjadi Kadipaten Prusia", "78666ddd"], "d": ["Albrecht dari Brandenburg, Grand Master Ksatria Teutonik, yang tidak menemukan bantuan melawan Polandia, menandatangani Perdamaian Kraków. Negara ordo (Ordensstaat) menjadi sebuah kadipaten turun-temurun dan duniawi yang beralih ke dinasti Brandenburg di bawah suzerainitas Polandia. Pusatnya adalah Königsberg; Albrecht mendirikan Universitas Albertus di sana pada 1544. Kadipaten itu berubah menjadi Kerajaan Prusia pada 1701.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Proklamasi Republik Austria — akhir monarki Habsburg", "c84f316c"], "d": ["Sehari setelah Kaisar Karl I menarik diri dari urusan negara pada 11 November, Majelis Nasional Sementara mengesahkan undang-undang tentang bentuk negara dan pemerintahan, dan republik diproklamasikan. Republik Pertama yang berpusat di Wina menggantikan Austria Habsburg. Dengan proklamasi ini Wina, Linz, Salzburg, Innsbruck, Klagenfurt, Bregenz, dan kota-kota Jerman-Austria lainnya menjadi wilayah Republik Austria (Deutschösterreich).", "2dcc1399"]}
});
